/* chinese/idioms/data/set2.js — 作者 B 的成語（catalog.js 第二欄 = 2 的那幾個）＋素養閱讀。照 set0.js 的寫法寫；規格 kids-member/docs/CHINESE_IDIOM_SPEC.md。
   出處、人物、朝代、注音、近反義已逐條對過教育部《成語典》（dict.idioms.moe.edu.tw）正文條目；故事、解說、例句、題目全部原創。 */
window.DATA_CY = (window.DATA_CY || []).concat([
  // ==================== L1 常用寓言 ====================
  {
    id: 'cy005', lv: 1, word: '亡羊補牢', zhuyin: 'ㄨㄤˊ ㄧㄤˊ ㄅㄨˇ ㄌㄠˊ', src: '《戰國策．楚策四》',
    quote: '見兔而顧犬，未為晚也；亡羊而補牢，未為遲也',
    facts: ['典源是《戰國策．楚策四》：戰國時楚國大臣莊辛勸諫楚襄王｜教育部《成語典》', '楚襄王只顧玩樂，不聽莊辛勸告；秦國攻打楚國後，襄王逃到城陽，才後悔並把莊辛請回來｜教育部《成語典》典故說明', '莊辛引用俗話「見兔而顧犬，未為晚也；亡羊而補牢，未為遲也」，說現在補救還不晚｜《戰國策．楚策四》'],
    story: [
      '戰國時代，南方有一個大國叫楚國。楚國的國君楚襄王很喜歡玩樂，身邊圍著幾個只會說好聽話的大臣，每天陪他吃喝、打獵、看歌舞，國家大事卻沒有人管。',
      '有一位大臣叫莊辛，看了很著急。他對襄王說：「大王，您整天只顧著玩，把國家的事丟在一邊，這樣下去，楚國會有危險的！」襄王聽了很不高興：「你是老糊塗了吧？還是故意說壞話嚇唬人？」',
      '莊辛知道再說也沒有用，只好說：「既然大王不相信，請讓我先到趙國去住一陣子，看看事情會怎麼發展。」於是他離開了楚國。',
      '果然，莊辛走了才五個月，強大的秦國就派兵攻打楚國，一連拿下好幾座城。襄王慌慌張張的逃到城陽這個地方，這才想起莊辛的話，後悔得不得了，趕緊派人到趙國把莊辛請回來。',
      '襄王一見到莊辛就問：「我以前不聽你的話，才落到今天這個地步。現在還有辦法嗎？」莊辛回答：「我聽過一句俗話：看到兔子再回頭叫獵狗去追，還不算晚；羊跑掉了再趕快修補羊圈，也還不算遲。」',
      '莊辛接著說，楚國雖然丟了一些土地，剩下的地方還很大，只要大王從現在開始認真治理國家，還是有希望的。襄王這次聽進去了，照著莊辛的建議做，楚國慢慢重新振作，還收回了一些失去的土地。',
      '「亡羊補牢」的「亡」是丟失、跑掉，「牢」是關羊的圈。羊已經跑掉幾隻，損失是真的；但如果馬上把破洞補好，剩下的羊就不會再跑掉。重點在於：發現錯了，就趕快改正。'
    ],
    mean: '羊跑掉了，趕快修補羊圈。比喻犯了錯或受到損失以後，及時想辦法改正、補救，還來得及。',
    usage: ['用在「已經出了問題，趕快補救，避免再發生」的時候，帶有鼓勵的意思。', '一定要先有錯誤或損失，才能說亡羊補牢；事情還沒發生就先準備，要說「未雨綢繆」。', '常說「亡羊補牢，為時未晚」，強調現在補救還不晚。'],
    misuse: ['「颱風還沒來，我們就先把窗戶貼好膠帶，這叫亡羊補牢。」✗　還沒有損失就先防範，是「未雨綢繆」；亡羊補牢要先有損失，再來補救。'],
    eg: ['上次段考粗心丟了好多分，這次我每題都檢查兩遍，希望亡羊補牢還來得及。', '社區的路燈壞了一個月，有人跌倒以後才修好，雖然是亡羊補牢，總比一直不修好。'],
    syn: [], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '莊辛第一次勸楚襄王時，襄王的反應是什麼？', opts: ['很不高興，說莊辛老糊塗', '馬上照著莊辛的話去做', '送莊辛很多禮物謝謝他', '請莊辛當楚國的大將軍'], a: 0, why: '第二段：襄王「聽了很不高興」，說莊辛「老糊塗了吧」。他是後來吃了虧才聽莊辛的話。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '莊辛離開楚國以後，到趙國去住。', a: true, why: '第三段：莊辛說「請讓我先到趙國去住一陣子」，於是離開了楚國；第四段襄王也是派人「到趙國」請他回來。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '襄王為什麼趕緊派人把莊辛請回來？', opts: ['秦國攻打楚國，他發現莊辛說對了', '趙國的國君要楚國把莊辛接走', '他想找莊辛陪自己打獵、看歌舞', '莊辛寫信說自己很想念楚國'], a: 0, why: '第四段：秦國打下好幾座城，襄王「這才想起莊辛的話，後悔得不得了」。莊辛的警告成真了，所以要請他回來想辦法。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '莊辛說「羊跑掉了再補羊圈，也還不算遲」，是想告訴襄王什麼？', opts: ['雖然已經有損失，現在改正還有希望', '楚國應該多養一些羊來賺錢', '丟掉的土地一定全部都拿得回來', '犯錯也沒關係，不用改也可以'], a: 0, why: '第五、六段合起來看：楚國已經丟了土地（損失），但只要現在認真治理，「還是有希望的」。重點是現在就改，不是不用改。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '莊辛第一次勸告時，襄王不聽；第二次，襄王聽了。你覺得是什麼讓襄王改變？如果你是莊辛，第一次會不會換一種方法勸他？請用故事內容說明。',
        ref: '讓襄王改變的是秦國真的打來，他吃了大虧，才知道莊辛說的是對的。如果我是莊辛，第一次我會舉出具體的例子，例如秦國最近在準備軍隊，讓襄王知道危險就在眼前，而不是只說「楚國會有危險」。',
        rubric: ['說出襄王改變的原因（秦國攻打、吃了虧）', '能用到故事內容當證據', '提出一個具體的勸告方法並說明理由'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「亡羊補牢」的「牢」是什麼意思？', opts: ['關羊、養羊的圈', '很牢固、很堅固', '關犯人的地方', '綁羊用的繩子'], a: 0, why: '故事最後一段：「牢」是關羊的圈。這裡不是「牢固」，也不是監牢。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '小翔每天騎腳踏車上學。有一天他發現煞車有點鬆，但他想「還能騎」就沒理會。結果下坡時煞不住，差點撞到電線桿，膝蓋擦破了皮。回家後，他馬上請哥哥陪他到車行把煞車修好，也把這次的教訓寫進日記裡。', q: '小翔受傷後的做法，最適合用哪個成語形容？', opts: ['亡羊補牢', '揠苗助長', '守株待兔', '畫蛇添足'], a: 0, why: '小翔已經吃了虧（受傷），馬上把煞車修好，是出事後及時補救。揠苗助長是太心急壞事，守株待兔是只等好運，畫蛇添足是多做不必要的事。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈日記〉明天要校外教學，我今天晚上就把水壺、雨衣和悠遊卡都放進背包。表哥看了說：「你這樣亡羊補牢，準備得真周到！」', q: '表哥用「亡羊補牢」用得恰當。', a: false, why: '還沒有發生任何損失，事先準備好東西，應該說「未雨綢繆」。亡羊補牢一定要先有錯誤或損失。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「水族箱的蓋子沒蓋好，跳出去一條魚；爸爸馬上買了新蓋子蓋緊，總算亡羊補牢。」這句話的「亡羊補牢」用得恰當。', a: true, why: '先有損失（跳出去一條魚），再趕快補救（換新蓋子），剩下的魚就不會再跳出去，用得恰當。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '莊辛說：「羊跑掉了再補羊圈，還不算遲。」想一想你最近犯過的一個錯（作業、和朋友相處、整理東西都可以），你可以怎麼「補牢」，讓同樣的事不再發生？',
        ref: '上星期我忘了帶美勞課要用的剪刀，只好跟同學借，害他也來不及剪。我的補救方法是：前一天晚上照著聯絡簿把要帶的東西一樣一樣放進書包，打勾確認，這個星期就沒有再忘記了。',
        rubric: ['說出一個自己犯過的具體錯誤或損失', '提出一個實際的補救做法', '說明這個做法怎麼避免同樣的事再發生'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '花圃的圍籬破了一個洞，小狗跑進去踩壞了幾株花。工友伯伯馬上把洞補好，說：「＿＿＿＿，現在修還來得及。」', opts: ['亡羊補牢', '杞人憂天', '自相矛盾', '狐假虎威'], a: 0, why: '花已經被踩壞（損失），趕快補洞（補救），用亡羊補牢。杞人憂天是沒根據的擔心，自相矛盾是前後衝突，狐假虎威是借別人的威風，放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '小芸的平板沒有設密碼，有一天被弟弟拿去亂按，不小心刪掉了她做了一半的報告。小芸雖然很難過，但沒有一直生氣，而是馬上設定了密碼，把剩下的檔案都備份到隨身碟，再把報告重新補做完成。', q: '小芸檔案被刪掉以後的做法，最適合用哪一個成語形容？', opts: ['亡羊補牢', '揠苗助長', '杯弓蛇影', '守株待兔'], a: 0, why: '檔案已經被刪（損失），小芸馬上設密碼、備份、補做，是及時補救。揠苗助長是太心急，杯弓蛇影是自己嚇自己，守株待兔是不努力等好運。' }
    ]
  },
  {
    id: 'cy008', lv: 1, word: '自相矛盾', zhuyin: 'ㄗˋ ㄒㄧㄤ ㄇㄠˊ ㄉㄨㄣˋ', src: '《韓非子．難一》',
    quote: '以子之矛，陷子之盾，何如',
    facts: ['典源是《韓非子．難一》：楚國有人在市集上同時賣矛和盾｜教育部《成語典》', '同一個故事也見於《韓非子．難勢》｜教育部《成語典》', '「矛」是刺人的長兵器，「盾」是擋住攻擊的盾牌；賣的人被問「用你的矛刺你的盾會怎樣」，答不出來｜教育部《成語典》典故說明'],
    story: [
      '戰國時代，楚國的市集每天都很熱鬧，賣菜的、賣布的、賣陶器的，吆喝聲此起彼落。有一個商人在路邊擺了個攤子，專門賣打仗用的兵器：一邊放著盾，一邊放著矛。',
      '「盾」是拿在手上擋住攻擊的大板子，「矛」是長長的、前端很尖的武器。商人先舉起盾，大聲叫賣：「快來看喔！我的盾是天下最堅固的，不管什麼東西都刺不穿它！」幾個路人停下來，好奇的摸了摸盾牌。',
      '過了一會兒，商人又拿起矛，揮了揮說：「再來看看我的矛！它是天下最鋒利的，不管什麼東西，它都刺得穿！」旁邊的人越圍越多，有人點頭，有人小聲討論。',
      '這時，人群裡有一個人開口問：「那麼，如果拿你的矛，去刺你的盾，會怎麼樣呢？」',
      '商人張著嘴，「這……這……」了半天，一句話也說不出來。因為他如果說刺得穿，就表示他的盾不是最堅固的；如果說刺不穿，就表示他的矛不是最鋒利的。兩句大話，不管怎麼回答，總有一句是假的。圍觀的人哈哈大笑，紛紛走開了。',
      '後來，思想家韓非把這個故事寫進書裡，用來說明：兩個互相衝突的說法，不可能同時都對。後人把「矛」和「盾」連在一起，就有了「矛盾」這個詞；說話或做事前後對不上、自己打自己的嘴巴，就叫做「自相矛盾」。'
    ],
    mean: '比喻說話或做事前後對不上，互相衝突。',
    usage: ['用在一個人的說法、做法前後互相衝突的時候，帶有批評的意思。', '要是「同一個人」或「同一件事」裡的說法對不上；兩個人意見不同，只是「意見分歧」，不是自相矛盾。'],
    misuse: ['「哥哥喜歡籃球，弟弟喜歡足球，兄弟倆真是自相矛盾。」✗　兩個人喜好不同很正常；自相矛盾是同一個人自己的話或做法前後衝突。'],
    eg: ['他說自己最討厭吃甜食，卻一口氣吃了三塊蛋糕，說法和做法自相矛盾。', '這篇作文前面說夏天最舒服，後面又說夏天熱得受不了，內容自相矛盾。'],
    syn: [], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '商人怎麼誇他的盾？', opts: ['什麼東西都刺不穿它', '又輕又便宜，誰都買得起', '是國王親手做的寶物', '可以拿來當桌子用'], a: 0, why: '第二段：商人說「不管什麼東西都刺不穿它」。' },
      { id: 'r2', p: 1, d: 1, type: 'mc', q: '圍觀的人問了商人什麼問題？', opts: ['拿你的矛刺你的盾，會怎樣', '你的矛和盾一共要賣多少錢', '你的兵器是從哪裡買來的', '你為什麼不去別的市集賣'], a: 0, why: '第四段：「如果拿你的矛，去刺你的盾，會怎麼樣呢？」' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '商人為什麼說不出話來？', opts: ['怎麼回答，都會拆穿一句大話', '他忘記矛和盾放在哪裡了', '他聽不懂那個人的問題', '他覺得那人太沒禮貌了'], a: 0, why: '第五段：說刺得穿，盾就不是最堅固；說刺不穿，矛就不是最鋒利。兩句大話總有一句是假的。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '「矛盾」這個詞為什麼可以用來形容說法前後對不上？', opts: ['最利的矛和最硬的盾不能同時存在', '矛和盾都是古代戰場上打仗用的兵器', '商人賣的矛和盾品質都很差', '矛和盾的形狀和用法剛好相反'], a: 0, why: '把第五、六段合起來看：「刺什麼都穿」和「什麼都刺不穿」不可能同時成立，所以「矛盾」用來指兩種說法互相衝突。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '如果你是那個商人，被人這樣一問，你會怎麼回答，才能誠實又能把東西賣出去？請說出你的說法，並說明為什麼這樣比較好。',
        ref: '我會說：「我的盾很堅固，一般的刀劍刺不穿；我的矛也很鋒利，可以刺穿一般的皮甲。至於互相刺會怎樣，我沒試過，不敢亂說。」這樣不誇大，客人比較會相信我，也不會被大家笑。',
        rubric: ['提出一個具體的回答', '回答不再說「天下第一」這類互相衝突的大話', '說明誠實介紹為什麼比誇大好'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「自相矛盾」的意思是什麼？', opts: ['說法或做法前後對不上，互相衝突', '自己同時拿著矛和盾，跟別人比賽', '和別人意見不同，吵了起來', '做事小心，攻擊防守都會'], a: 0, why: '自相矛盾是自己的說法或做法前後衝突。跟別人意見不同、拿兵器比賽都不是它的意思。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '班會討論要不要在教室養魚。阿哲第一個舉手說：「我反對！養魚太麻煩，還要天天換水。」大家討論了一會兒，決定養魚，並且要選出照顧小組。阿哲又舉手說：「那我要當組長，我最喜歡照顧魚了！」大家都轉頭看著他，忍不住笑了出來。', q: '阿哲在班會上說的話，最適合用哪個成語形容？', opts: ['自相矛盾', '亡羊補牢', '杞人憂天', '畫蛇添足'], a: 0, why: '阿哲先說養魚太麻煩，後來又說最喜歡照顧魚，前後兩句話對不上，就是自相矛盾。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈運動會報導〉今年大隊接力，五年一班和五年二班同時衝過終點線，兩班的實力自相矛盾，裁判看了好久的影片才分出名次。', q: '這段報導用「自相矛盾」恰當嗎？', opts: ['不恰當，兩班實力相當，應該說不分上下', '恰當，因為兩個班級的實力互相衝突', '恰當，因為比賽本來就有攻擊和防守', '不恰當，自相矛盾只能用在買賣東西'], a: 0, why: '兩班一樣強是「不分上下」，不是某一方的說法前後衝突。自相矛盾也不是只能用在買賣上。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「弟弟說他已經長大了，不用人陪；可是晚上又吵著要人陪他睡，說法真是自相矛盾。」這句話的「自相矛盾」用得恰當。', a: true, why: '同一個人先說不用人陪、又要人陪，前後說法衝突，用自相矛盾恰當。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '賣矛和盾的商人為了把東西賣出去，說了兩句互相衝突的大話。在生活中（自我介紹、寫作文、跟朋友說話），你有沒有不小心說出前後對不上的話？以後可以怎麼避免？',
        ref: '有一次我寫作文，開頭寫「我最喜歡下雨天」，結尾卻寫「下雨天真討厭，哪裡都不能去」，老師在旁邊畫了問號。以後我寫完會從頭再讀一遍，看看前面和後面的想法有沒有對得上。',
        rubric: ['舉出一個說話或寫作前後對不上的例子', '說明它跟商人的錯有什麼相同', '提出避免的方法（例如說話前想清楚、寫完再檢查）'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '他一下說這部卡通很無聊，一下又說每一集都看了三遍，說法＿＿＿＿。', opts: ['自相矛盾', '亡羊補牢', '東施效顰', '杯弓蛇影'], a: 0, why: '說無聊又說每集看三遍，前後衝突，用自相矛盾。亡羊補牢是補救，東施效顰是盲目模仿，杯弓蛇影是自己嚇自己，放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '社區的公告欄貼了一張海報，上面寫著：「本週六的淨灘活動全程免費，歡迎大家參加！」可是海報最下面又用小字寫著：「每位參加者要先繳交報名費一百元。」路過的鄰居看了都搖搖頭：「到底要不要錢啊？」', q: '這張海報上的說明，最適合用哪一個成語形容？', opts: ['自相矛盾', '亡羊補牢', '三人成虎', '班門弄斧'], a: 0, why: '海報先說全程免費，又說要繳報名費，前後說法衝突，就是自相矛盾。' }
    ]
  },
  {
    id: 'cy011', lv: 1, word: '杞人憂天', zhuyin: 'ㄑㄧˇ ㄖㄣˊ ㄧㄡ ㄊㄧㄢ', src: '《列子．天瑞》',
    quote: '杞國有人憂天地崩墜，身亡所寄，廢寢食者',
    facts: ['典源是《列子．天瑞》：古時杞國有一個人擔心天會塌、地會陷｜教育部《成語典》', '有人向他解釋天是氣聚積成的、地是土塊堆積成的，他才放下心來｜教育部《成語典》典故說明', '《成語典》辨識：「杞人憂天」側重「憂」，專指沒有根據的憂慮；「庸人自擾」側重「擾」，指自找麻煩｜教育部《成語典》'],
    story: [
      '很久以前，有一個小國家叫杞國。杞國有一個人，有一天抬頭看著天空，心裡忽然冒出一個可怕的想法：「天這麼大、這麼高，要是哪一天塌下來，那該怎麼辦？地這麼重，要是裂開陷下去，我又能躲到哪裡去？」',
      '從那天起，他就天天為這件事發愁。吃飯的時候，他吃兩口就停下來，抬頭看看天；晚上躺在床上，他翻來覆去睡不著，總覺得屋頂上的天好像越來越低。沒過多久，他整個人瘦了一大圈，臉色也越來越差。',
      '他的一位朋友看到他這個樣子，很替他擔心，就跑來開導他：「天不過是一大片聚在一起的氣，我們每天走路、呼吸、伸手抬腳，都在天裡面活動，它怎麼會塌下來呢？」',
      '那個人聽了，又皺起眉頭：「如果天真的只是氣，那太陽、月亮和星星掛在上面，難道不會掉下來嗎？」朋友笑著說：「太陽、月亮和星星，也只是會發光的氣，就算真的掉下來，也不會傷到人。」',
      '「那地呢？地要是陷下去怎麼辦？」朋友耐心的說：「地是一塊一塊的土堆積起來的，四面八方都是土，你天天在上面走、在上面跳，也沒看它陷下去呀！」',
      '聽完這些話，那個人終於鬆了一口氣，高興得笑了出來，朋友也跟著開心起來。後來，人們就用「杞人憂天」來形容：擔心一些根本沒有根據、不必要的事情，讓自己白白煩惱。'
    ],
    mean: '杞國有人擔心天會塌下來。比喻擔心一些沒有根據、不必要的事。',
    usage: ['用在擔心的事情根本沒有根據、不太可能發生的時候，有勸人別白操心的意思。', '如果擔心的事有根據、真的可能發生，就不能說杞人憂天；例如颱風要來了先做準備，是「未雨綢繆」。'],
    misuse: ['「氣象局發布颱風警報，阿姨趕快去買手電筒和乾糧，真是杞人憂天。」✗　颱風警報是有根據的，事先準備是未雨綢繆，不是杞人憂天。'],
    eg: ['才剛開學，他就擔心六年後考不上喜歡的學校，未免太杞人憂天了。', '溜滑梯是新蓋的，也通過了安全檢查，你不用杞人憂天，擔心它會垮下來。'],
    syn: ['庸人自擾', '鰓鰓過慮'], ant: ['不憂不懼', '無憂無慮'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '杞國那個人擔心什麼事？', opts: ['天會塌下來、地會陷下去', '家裡的糧食會被人偷走', '明天會下大雨，不能出門', '自己的朋友會離開杞國'], a: 0, why: '第一段：他擔心「天要是塌下來」「地要是裂開陷下去」。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '朋友說，太陽、月亮和星星就算掉下來，也不會傷到人。', a: true, why: '第四段朋友說：「就算真的掉下來，也不會傷到人。」' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '從第二段可以看出，一直擔心會讓人怎麼樣？', opts: ['吃不好、睡不好，身體也變差', '變得更聰明，懂得更多知識', '交到更多朋友，大家都關心他', '變得更勇敢，什麼都不怕了'], a: 0, why: '第二段：他吃兩口就停、晚上睡不著，「瘦了一大圈，臉色也越來越差」。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '朋友是用什麼方法，讓那個人不再擔心？', opts: ['用每天看得到的事，一件件解釋', '帶他搬到一個看不見天空的地方', '叫他乾脆不要想這件事', '送他一頂堅固的帽子'], a: 0, why: '第三到五段：朋友用「每天走路、呼吸都在天裡面」「天天在地上走、跳也沒陷下去」這些平常的事，一個問題一個問題回答。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '朋友沒有笑那個人膽小，而是一個問題一個問題耐心回答。你覺得朋友的做法好不好？如果你的好朋友也一直擔心一件不會發生的事，你會怎麼幫他？',
        ref: '我覺得朋友的做法很好，因為笑他只會讓他更難過，耐心解釋才能讓他真的放心。如果我的好朋友一直擔心晚上會有怪物，我會陪他把房間的燈打開，一個角落一個角落看清楚，讓他知道什麼都沒有。',
        rubric: ['對朋友的做法提出看法並說出理由', '理由能用到故事內容（耐心回答、用平常的事解釋）', '提出一個幫助朋友的具體做法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「杞人憂天」的「杞」指的是什麼？', opts: ['古代一個國家的名字', '一種會開花結果的樹木', '一個人的名字', '天空裡的一顆星'], a: 0, why: '「杞人」就是杞國的人。杞是古代的國名。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '明天要去動物園校外教學。晚上，小安躺在床上睡不著：「萬一長頸鹿的脖子太長，彎下來咬我怎麼辦？萬一遊覽車開到一半，輪子飛走了怎麼辦？萬一……」他越想越害怕，一直到半夜才睡著。第二天，大家玩得很開心，什麼事都沒有發生。', q: '小安前一天晚上的樣子，最適合用哪個成語形容？', opts: ['杞人憂天', '亡羊補牢', '自相矛盾', '畫蛇添足'], a: 0, why: '小安擔心的事都沒有根據，結果白白煩惱睡不著，就是杞人憂天。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈新聞短評〉氣象局發布颱風警報，預估明天晚上颱風就會登陸。有些家庭提早把陽臺的花盆搬進屋裡、準備手電筒，這種做法實在是杞人憂天。', q: '這篇短評用「杞人憂天」用得恰當。', a: false, why: '颱風警報是有根據的，提早準備是「未雨綢繆」。杞人憂天只能用在沒有根據的擔心。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '把成語和它跟「杞人憂天」的關係配起來。', pairs: [['庸人自擾', '近義：自己找麻煩、白白煩惱'], ['無憂無慮', '反義：一點煩惱都沒有'], ['亡羊補牢', '無關：出了錯趕快補救']], why: '《成語典》把庸人自擾列為近義、無憂無慮列為反義。亡羊補牢說的是補救，跟擔心沒有關係。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '杞國人因為擔心不會發生的事，吃不下、睡不著。你有沒有為某件事擔心太多的經驗（考試、上臺、看牙醫）？想一想，怎麼分辨「需要準備的擔心」和「不必要的擔心」？',
        ref: '上臺演講前，我擔心忘詞，也擔心臺下的人會笑我、麥克風會壞掉。後來我發現，忘詞是真的可能發生，所以要多練習幾次；大家笑我、麥克風壞掉其實很少發生，就算發生了老師也會幫忙。能準備的就去準備，想太多也沒用的就先放下。',
        rubric: ['說出一個自己擔心太多的具體經驗', '分出哪些擔心有根據、哪些沒有根據', '對「有根據的擔心」提出準備方法'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '妹妹第一次去露營，一直擔心月亮會掉下來砸到帳篷，爺爺笑她是＿＿＿＿。', opts: ['杞人憂天', '亡羊補牢', '自相矛盾', '鷸蚌相爭'], a: 0, why: '擔心月亮掉下來沒有根據，用杞人憂天。亡羊補牢是補救，自相矛盾是前後衝突，鷸蚌相爭是兩方相爭讓第三者得利，都不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '小芳聽同學說「把照片放在鉛筆盒裡會帶來壞運氣」，從此每天上學都很不安，上課常常分心，晚上還睡不好。後來姊姊告訴她：「照片只是紙，不會帶來壞運氣，這種說法一點根據都沒有。」小芳這才放下心來，又能專心上課了。', q: '小芳因為那句話整天擔心，最適合用哪一個成語形容？', opts: ['杞人憂天', '亡羊補牢', '如魚得水', '百發百中'], a: 0, why: '小芳擔心的事沒有根據，卻白白煩惱到睡不好，就是杞人憂天。' }
    ]
  },
  {
    id: 'cy014', lv: 1, word: '葉公好龍', zhuyin: 'ㄕㄜˋ ㄍㄨㄥ ㄏㄠˋ ㄌㄨㄥˊ', src: '《莊子》逸文',
    quote: '葉公見之，棄而還走，失其魂魄', quoteFrom: '漢．劉向《新序．雜事》',
    facts: ['典出《莊子》逸文；漢．劉向《新序．雜事》也記載這個故事｜教育部《成語典》、漢．劉向《新序．雜事》', '孔子的學生子張去見喜歡結交士人的魯哀公，沒有受到重視，就講葉公的故事，諷刺哀公只是貪慕喜歡人才的名聲｜教育部《成語典》典故說明', '《成語典》注音：「葉」讀ㄕㄜˋ，「好」讀ㄏㄠˋ｜教育部《成語典》'],
    story: [
      '春秋時代，孔子有一個學生叫子張。他聽說魯國的國君魯哀公非常喜歡人才，就不怕路途遙遠，走了好多天的路來到魯國，希望能為國家做事。',
      '可是子張到了以後，等了一天又一天，魯哀公一直沒有好好接待他。子張終於明白了，就請人帶一個故事給哀公聽，然後收拾行李離開了。',
      '他說的是葉公的故事。從前有一位葉公，大家都知道他最喜歡龍。他衣帶上的扣環刻著龍，喝酒的器具畫著龍，家裡的牆壁、柱子、屋梁，也到處雕滿了龍。只要有客人來，他就得意的介紹：「你看，這條龍的鱗片多漂亮！」',
      '天上的真龍聽說人間有一個這麼喜歡龍的人，非常感動，心想：「我應該去看看他。」於是真龍從天上飛下來，把頭從葉公家的窗戶探進去，長長的尾巴一直拖到大廳。',
      '葉公一看到真的龍，嚇得臉色發白，轉身就逃，好像魂都飛走了。原來，葉公喜歡的不是真正的龍，只是那些「看起來像龍」的圖案和雕刻罷了。',
      '子張託人轉告哀公：「我聽說您喜歡人才，才遠道而來；可是您好像跟葉公一樣，喜歡的只是愛人才的名聲，並不是真的喜歡人才。」後來，人們就用「葉公好龍」比喻嘴上說喜歡，其實並不是真心喜歡，表裡不一。這裡的「好」要讀ㄏㄠˋ，是喜愛的意思。'
    ],
    mean: '葉公說喜歡龍，真龍來了卻嚇得逃走。比喻嘴上說喜愛，其實並不是真心喜愛，表裡不一、有名無實。',
    usage: ['用在「口頭上說喜歡、支持，真的碰到了卻退縮或不要」的時候（貶義）。', '「好」讀ㄏㄠˋ，是喜愛的意思；依《成語典》，「葉」讀ㄕㄜˋ。'],
    misuse: ['「他非常喜歡畫龍，牆上貼滿了自己畫的龍，真是葉公好龍。」✗　他是真心喜歡畫龍，沒有表裡不一，不能用葉公好龍。'],
    eg: ['他天天說最愛小狗，鄰居請他幫忙照顧小狗一天，他卻嫌麻煩不肯，真是葉公好龍。', '班長說歡迎大家提意見，可是有人提了，他又生氣，這種葉公好龍的態度讓人失望。'],
    syn: ['言行不一', '表裡不一'], ant: ['言行一致'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '葉公家裡哪裡看得到龍？', opts: ['牆壁、柱子和屋梁上都有', '只有大門口的一塊招牌上', '後院的池塘裡真的養著龍', '只有葉公的書本裡畫著'], a: 0, why: '第三段：「家裡的牆壁、柱子、屋梁，也到處雕滿了龍。」' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '真龍來到葉公家時，葉公高興的跑去迎接。', a: false, why: '第五段：葉公「嚇得臉色發白，轉身就逃」。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '子張說魯哀公跟葉公一樣，是什麼意思？', opts: ['只愛人才名聲，不真心用人才', '他家裡也一樣到處雕滿了龍', '他跟葉公一樣很怕龍', '他和葉公是很好的朋友'], a: 0, why: '第六段：哀公「喜歡的只是愛人才的名聲，並不是真的喜歡人才」，就像葉公只愛龍的圖案、不愛真龍。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '葉公喜歡的到底是什麼？', opts: ['看起來像龍的圖案和雕刻', '在天上飛來飛去的真龍', '比龍更兇猛的老虎', '別人送他的龍形禮物'], a: 0, why: '第三段他家到處是龍的圖案，第五段卻被真龍嚇跑；合起來看，他喜歡的只是「看起來像龍」的東西。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '子張沒有當面責怪魯哀公，而是請人轉述一個故事就離開。你覺得用故事來表達不滿，比直接說出來好嗎？請說出你的看法和理由。',
        ref: '我覺得用故事比較好。如果直接說「你根本不重視人才」，哀公可能會生氣、不想聽；用葉公的故事，哀公聽了會自己想到「我是不是也這樣」，比較容易反省。不過如果對方聽不懂故事，就要再說清楚一點。',
        rubric: ['表明用故事好或不好的看法', '說出理由（例如對方比較聽得進去、比較不會生氣）', '能連結到故事中子張和哀公的情形'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「葉公好龍」的「好」是什麼意思？', opts: ['喜愛', '很好', '容易', '完成'], a: 0, why: '「好」讀ㄏㄠˋ，是喜愛。葉公好龍就是「葉公喜愛龍」。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '小志常常跟大家說：「我最喜歡大自然了，以後要當昆蟲學家！」自然課老師帶全班到校園找昆蟲，大家發現一隻毛毛蟲，請小志來看看。小志卻嚇得往後跳，大叫：「好噁心，快拿走！」接下來的課，他都躲在走廊上不肯過來。', q: '小志的表現，最適合用哪個成語形容？', opts: ['葉公好龍', '杞人憂天', '東施效顰', '亡羊補牢'], a: 0, why: '小志嘴上說最愛昆蟲，真的看到卻嚇得逃開，就像葉公見到真龍就跑，是葉公好龍。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈部落格〉我的表妹很喜歡龍，她的筆記本、書包和水壺上都是龍的圖案，週末還去博物館看龍的展覽，看得目不轉睛。她真是葉公好龍啊！', q: '這段文字用「葉公好龍」恰當嗎？', opts: ['不恰當，表妹是真心喜歡，沒有表裡不一', '恰當，因為表妹收集了很多龍的圖案', '恰當，因為葉公好龍就是很喜歡龍', '不恰當，因為表妹喜歡的不是真的龍'], a: 0, why: '葉公好龍是說「嘴上喜歡、其實不是真心」。表妹真心喜歡，還主動去看展覽，用這個成語反而像在批評她。' },
      { id: 'p4', k: 'pair', d: 2, type: 'mc', q: '下面哪一個成語，和「葉公好龍」的意思最接近？', opts: ['表裡不一', '言行一致', '杞人憂天', '亡羊補牢'], a: 0, why: '《成語典》把「表裡不一」列為近義、「言行一致」列為反義。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '葉公說喜歡龍，真的龍來了卻逃走。想一想，你有沒有說過「我很喜歡○○」，可是真的要去做的時候卻退縮了（例如學樂器、養寵物、參加社團）？怎麼做才能讓自己「說的」和「做的」一樣？',
        ref: '我說過很想養小狗，可是表姊請我幫忙遛狗一個星期，我遛了兩天就嫌累不想去。我發現自己只是喜歡小狗可愛的樣子。以後說喜歡一件事以前，我會先想想要付出什麼，真的決定了就要做到。',
        rubric: ['舉出一個「說喜歡卻退縮」的具體例子', '說明它和葉公的相同之處', '提出讓說和做一致的方法'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '他整天說自己是棒球迷，可是一聽到要早起去球場看比賽，就說太累不想去，根本是＿＿＿＿。', opts: ['葉公好龍', '亡羊補牢', '百發百中', '如魚得水'], a: 0, why: '嘴上說是球迷，真的要去看比賽卻退縮，用葉公好龍。亡羊補牢是補救，百發百中是很準，如魚得水是找到合適的環境，都不通。' },
      { id: 'x2', k: 'use', d: 2, type: 'tf', ctx: '〈班會紀錄〉阿傑說他很喜歡下棋，每天放學都到圖書館找同學下棋，寒假還參加了圍棋營，棋藝進步很多。小美說：「阿傑真是葉公好龍。」', q: '小美說的「葉公好龍」用得恰當。', a: false, why: '阿傑說喜歡、也真的天天去下棋，說到做到，不是表裡不一，不能用葉公好龍。' }
    ]
  },
  {
    id: 'cy017', lv: 1, word: '鷸蚌相爭', zhuyin: 'ㄩˋ ㄅㄤˋ ㄒㄧㄤ ㄓㄥ', src: '《戰國策．燕策二》',
    quote: '兩者不肯相舍，漁者得而并禽之',
    facts: ['典源是《戰國策．燕策二》：戰國時趙惠王想攻打燕國，蘇代用這個寓言勸他｜教育部《成語典》', '蘇代提醒趙王：趙、燕兩國相爭，秦國就會像漁夫一樣得到好處；趙王聽了就放棄攻打燕國｜教育部《成語典》典故說明', '《成語典》把「漁人得利」「鷸蚌相持，漁人得利」列為可以互相參考的說法｜教育部《成語典》'],
    story: [
      '戰國時代，七個大國互相爭地盤，常常打來打去。有一年，趙國的國君趙惠王準備派兵攻打隔壁的燕國。燕國很著急，就請了一位很會說話的人——蘇代，到趙國去勸趙惠王。',
      '蘇代見了趙惠王，沒有一開口就講大道理，而是說：「我來的路上，經過易水河邊，看到一件有趣的事。」',
      '「一隻河蚌爬上沙灘，張開殼曬太陽。這時飛來一隻鷸鳥，牠有長長的尖嘴，一下子就去啄蚌殼裡的肉。河蚌立刻把殼合起來，緊緊夾住了鷸鳥的嘴。」',
      '「鷸鳥說：『今天不下雨，明天不下雨，你就會被曬乾！』河蚌也不甘示弱：『今天不放你，明天不放你，你就會餓扁！』兩個誰也不肯讓誰，就這樣僵在沙灘上。」',
      '「這時候，一個漁夫走過來，一看，哈哈！不用費一點力氣，就把鷸鳥和河蚌一起抓走了。」',
      '說完，蘇代認真的看著趙惠王：「現在趙國想攻打燕國，兩國一直打下去，人民都很辛苦，國力也會越打越弱。我擔心，強大的秦國會變成那個漁夫啊！希望大王好好想一想。」',
      '趙惠王聽了，覺得很有道理，就打消了攻打燕國的念頭。後來，人們就用「鷸蚌相爭」比喻雙方爭執不讓，結果兩邊都吃虧，反而讓第三者撿到便宜。'
    ],
    mean: '鷸鳥和河蚌互相夾住不放，結果都被漁夫抓走。比喻雙方爭執不肯退讓，兩敗俱傷，讓第三者得到好處。',
    usage: ['用在兩方互不相讓、結果都吃虧，讓別人得利的時候，常說「鷸蚌相爭，漁翁得利」。', '一定要有「兩方都吃虧、第三者得利」的意思；兩個人合作順利，不能用鷸蚌相爭。'],
    misuse: [],
    eg: ['兩隊為了搶籃球場吵個不停，結果被別班先占走了，真是鷸蚌相爭，漁翁得利。', '兄弟倆搶最後一塊蛋糕搶到掉在地上，被小狗吃掉了，這就是鷸蚌相爭的下場。'],
    syn: [], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '蘇代到趙國去，是想勸趙惠王做什麼？', opts: ['不要攻打燕國', '派兵攻打秦國', '去易水邊抓魚', '把國都搬到燕國'], a: 0, why: '第一段：趙惠王準備攻打燕國，燕國請蘇代「到趙國去勸趙惠王」；最後趙王「打消了攻打燕國的念頭」。' },
      { id: 'r2', p: 1, d: 1, type: 'mc', q: '鷸鳥的嘴為什麼被夾住？', opts: ['牠去啄蚌肉，河蚌把殼合起來', '漁夫用網子把牠纏住了', '牠想喝河水，卡在石頭縫', '牠跟其他鷸鳥打架受傷了'], a: 0, why: '第三段：鷸鳥去啄蚌肉，「河蚌立刻把殼合起來，緊緊夾住了鷸鳥的嘴」。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '蘇代說「秦國會變成那個漁夫」，意思是什麼？', opts: ['趙燕打得兩敗俱傷，秦國撿便宜', '秦國人很會抓魚，常到河邊', '秦國會派漁夫來幫趙國一起打仗', '秦國會跟燕國一起打趙國'], a: 0, why: '鷸和蚌像趙和燕，漁夫像秦國：兩國打到國力變弱，秦國就能輕鬆得到好處。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '蘇代為什麼不直接說「不要打」，而要先講鷸蚌的故事？', opts: ['用故事讓趙王自己看出後果', '他不清楚趙國和燕國的事', '他想表現自己很會抓魚', '趙王最愛聽動物的故事'], a: 0, why: '故事裡的鷸、蚌、漁夫，剛好對應趙、燕、秦。趙王聽完自己就想通了，比直接勸更有說服力。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '鷸鳥和河蚌都不肯先放開。如果你是鷸鳥或河蚌，你會怎麼做，才能兩個都平安？請用故事的情節說明理由。',
        ref: '如果我是河蚌，我會先跟鷸鳥說好：「我數到三就放開你，你也不要再啄我。」因為一直僵著，不是被曬乾就是餓扁，最後還被漁夫一起抓走。先各退一步，兩個都能平安離開。',
        rubric: ['提出一個讓雙方都退一步的具體做法', '用故事情節說明一直僵持的後果', '說明自己的做法為什麼能讓兩邊都平安'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「鷸蚌相爭」的意思是什麼？', opts: ['雙方爭執不讓，結果讓第三者得利', '兩種動物比賽，看誰跑得比較快', '漁夫很聰明，懂得抓魚的方法', '鳥和貝殼成了互相幫忙的朋友'], a: 0, why: '重點是兩方相爭、都吃虧，讓第三者撿便宜。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '五年級兩個班都想在園遊會賣珍珠奶茶。兩班班長為了誰能賣，在走廊上吵了三天，誰都不肯讓。結果攤位登記截止了，兩班都沒有報到名，賣飲料的攤位最後給了六年級。六年級的學長笑著說：「謝謝你們讓給我們啦！」', q: '這件事最適合用哪個成語形容？', opts: ['鷸蚌相爭', '亡羊補牢', '葉公好龍', '杞人憂天'], a: 0, why: '兩班爭得不肯讓，兩邊都沒報到名，反而讓六年級得到攤位，就是鷸蚌相爭、漁翁得利。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈日記〉今天下課，我和小明一起合作完成拼圖，他找邊框，我拼中間，只花了十分鐘就拼好了。我們真是鷸蚌相爭！', q: '日記裡的「鷸蚌相爭」用得恰當。', a: false, why: '兩個人是合作，不是相爭，也沒有第三者得利。可以說「同心協力」。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「兩隻小狗搶一根骨頭，咬來咬去，結果骨頭被旁邊的貓叼走了，正是鷸蚌相爭。」這句話的「鷸蚌相爭」用得恰當。', a: true, why: '兩隻狗爭不下（相爭），骨頭被貓拿走（第三者得利），用得恰當。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '鷸鳥和河蚌誰都不肯讓，最後一起被抓走。想一想你和兄弟姊妹或同學爭東西的經驗，如果繼續爭下去，可能會讓誰「得利」，或讓兩個人都吃虧？你們可以怎麼做，讓兩邊都不吃虧？',
        ref: '我和妹妹常常搶電視遙控器，吵到最後被媽媽關掉電視，兩個人都沒得看。我們可以先說好，一個人看半小時，再換另一個人，或是一起選一個兩個人都喜歡的節目。',
        rubric: ['說出一個和別人相爭的具體經驗', '說明繼續爭下去的後果（兩敗俱傷或別人得利）', '提出讓雙方都不吃虧的辦法'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '兩家飲料店天天削價競爭，越賣越便宜，最後兩家都撐不下去，倒讓新開的第三家撿了便宜，真是＿＿＿＿。', opts: ['鷸蚌相爭', '亡羊補牢', '杯弓蛇影', '自相矛盾'], a: 0, why: '兩家相爭都吃虧，第三家得利，用鷸蚌相爭。其他三個放進句子都說不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '躲避球比賽前，阿明和阿強都想當隊長，兩人從早上吵到中午，連練習時間都拿來爭論，其他隊員只能在旁邊乾等。老師說：「既然你們兩個都不讓，那就讓小雅當隊長吧！」小雅本來沒想要當，卻輕輕鬆鬆就當上了隊長。', q: '這件事最適合用哪一個成語形容？', opts: ['鷸蚌相爭', '百發百中', '三人成虎', '葉公好龍'], a: 0, why: '阿明和阿強爭不下，結果誰都沒當成，反而讓小雅得到隊長，是鷸蚌相爭。' }
    ]
  },
  {
    id: 'cy020', lv: 1, word: '東施效顰', zhuyin: 'ㄉㄨㄥ ㄕ ㄒㄧㄠˋ ㄆㄧㄣˊ', src: '《莊子．天運》',
    quote: '西施病心而矉其里，其里之醜人見而美之',
    facts: ['典源是《莊子．天運》：越國美女西施有心痛的毛病，同鄉的一個姑娘模仿她捧心皺眉｜教育部《成語典》', '《莊子》原文只說是「其里之醜人」，後人才叫她「東施」，和西施對照｜教育部《成語典》典故說明', '故事是魯國的太師講的，用來說明做事要懂得變通，不能不看情況硬照著做｜教育部《成語典》典故說明', '《成語典》辨識：東施效顰側重招來反效果；邯鄲學步側重連原有的都喪失掉｜教育部《成語典》'],
    story: [
      '春秋時代，越國有一個非常美麗的姑娘，名叫西施。她住在一個小村子裡，村裡的人都誇她長得好看。',
      '西施有心痛的毛病。發作的時候，她會用手按著胸口，輕輕皺起眉頭，慢慢的走路。村裡的人看了，不但不覺得奇怪，反而覺得她這樣更惹人憐愛。',
      '同一個村子裡，有一個姑娘很羨慕西施。她看到西施按著胸口、皺著眉頭的樣子，心想：「原來這樣就會變漂亮！我也要學。」',
      '第二天，她也用手按著胸口，把眉頭皺得緊緊的，在村子裡走來走去。可是她的心並不痛，只是硬學出來的樣子，看起來非常不自然。村裡的人看了，有的趕快把大門關上，有的帶著家人繞路走開。她不但沒有變得更美，反而讓大家都想避開她。',
      '這個故事記在《莊子》這本書裡，原本只說她是「同村的一個姑娘」。後來的人為了和西施對照，就叫她「東施」。',
      '在《莊子》裡，講這個故事的是一位魯國的太師。他想說的是：別人的做法有他的原因，只看表面、不管自己的情況就照著學，結果反而會更糟。「效」是模仿，「顰」是皺眉頭，「東施效顰」就是比喻盲目模仿別人，結果適得其反。'
    ],
    mean: '模仿西施皺眉，卻讓人更想避開。比喻不顧自己的情況，盲目模仿別人，結果適得其反。',
    usage: ['用在盲目模仿別人、反而弄得更糟的時候（貶義）；重點是「亂學」，不要拿來批評別人的長相。', '跟「邯鄲學步」都是模仿不成：東施效顰重在「反而更糟」，邯鄲學步重在「連自己原本會的都忘了」。'],
    misuse: ['「她跟著書法老師一筆一畫認真學寫字，進步很多，真是東施效顰。」✗　認真向老師學習、而且進步了，是好的學習，不能用東施效顰。'],
    eg: ['看到別人在臺上講笑話很受歡迎，他也硬背了幾個笑話，結果大家都笑不出來，真是東施效顰。', '每個人適合的讀書方法不一樣，看到別人熬夜就跟著熬夜，只會東施效顰，白天反而沒精神。'],
    syn: ['生搬硬套', '邯鄲學步'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '西施心痛發作時，會有什麼樣子？', opts: ['按著胸口、皺起眉頭', '躺在床上大聲哭叫', '坐在溪邊不停唱歌', '跑去找醫生拿藥'], a: 0, why: '第二段：她會「用手按著胸口，輕輕皺起眉頭，慢慢的走路」。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '在《莊子》的原文裡，就已經把模仿西施的姑娘叫做「東施」。', a: false, why: '第五段：原文只說是「同村的一個姑娘」，「東施」是後來的人取的。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '村裡的人為什麼覺得西施皺眉好看，看到那個姑娘皺眉卻想避開？', opts: ['西施很自然，她是硬裝出來的', '她皺眉皺得比西施久', '西施皺眉的時候，衣服比較漂亮', '大家本來就不喜歡她'], a: 0, why: '第四段：她「心並不痛，只是硬學出來的樣子，看起來非常不自然」。西施是真的不舒服，表情自然。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '魯國太師講這個故事，主要想提醒什麼？', opts: ['不看自己情況就照著學，反而更糟', '長得漂亮的人不管做什麼都好看', '心痛的時候一定要趕快去看醫生', '住在同一個村子的人要互相幫忙'], a: 0, why: '最後一段：「只看表面、不管自己的情況就照著學，結果反而會更糟。」' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '那個姑娘很想變漂亮，所以去學西施。你覺得她「想變好」的心錯了嗎？她錯在哪裡？如果你是她的朋友，會給她什麼建議？',
        ref: '我覺得想變好的心沒有錯，錯在她只學西施的動作，沒想到西施皺眉是因為生病，自己硬裝反而不自然。我會建議她找出自己的優點，例如笑起來很親切，就多笑一笑，不用學別人。',
        rubric: ['對「想變好」提出看法', '說出她錯在哪裡（只學表面、不看自己情況）', '提出一個具體、合適的建議'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「東施效顰」的「顰」是什麼意思？', opts: ['皺眉頭', '心痛', '洗衣服', '走路'], a: 0, why: '「顰」是皺眉頭，「效顰」就是模仿別人皺眉。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '小婷看到網路上有人用很誇張的聲音和表情介紹文具，影片很受歡迎。她也拍了一支，學那個人大聲尖叫、擠眉弄眼，可是她平常說話很溫柔，這樣一學反而很不自然。同學看了都說：「你原本自然的樣子比較好看。」', q: '小婷的做法，最適合用哪個成語形容？', opts: ['東施效顰', '亡羊補牢', '鷸蚌相爭', '杞人憂天'], a: 0, why: '小婷不管適不適合自己，照著別人亂學，結果更不自然，是東施效顰。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈作文〉我很欣賞阿姨做事有條理，就學她每天寫下要做的事，一件一件完成。一個月後，我的房間變整齊了，作業也不再忘記寫。我覺得自己這次東施效顰，學得很成功！', q: '這篇作文用「東施效顰」恰當嗎？', opts: ['不恰當，學得好又有效果，不是盲目模仿', '恰當，因為作者真的模仿了阿姨的做法', '恰當，因為東施效顰就是學習別人', '不恰當，因為阿姨並不是西施'], a: 0, why: '東施效顰是「學了反而更糟」。作者學得有效果，是好的學習，用這個成語反而像在說自己學壞了。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '把成語和它跟「東施效顰」的關係配起來。', pairs: [['邯鄲學步', '近義：模仿不成，連原本的都丟了'], ['生搬硬套', '近義：不看情況，硬把別人的做法拿來用'], ['杞人憂天', '無關：擔心沒有根據的事']], why: '《成語典》把邯鄲學步、生搬硬套列為東施效顰的近義成語。杞人憂天說的是擔心，跟模仿無關。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '東施只學了西施的「樣子」，沒想到自己適不適合。你有沒有想模仿的人（明星、同學、運動員）？你會學他的哪些地方？哪些地方不適合硬學？為什麼？',
        ref: '我很佩服班上跑最快的阿凱。我想學他每天早上練跑的習慣，因為這是努力，誰都可以學。可是他跑步時喜歡大聲喊叫，那是他的個性，我硬學只會很奇怪，所以不用學。',
        rubric: ['說出一個想模仿的對象', '分出「值得學的地方」和「不適合硬學的地方」', '說明分辨的理由'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '他看到哥哥用左手投籃很帥，也硬改用左手，結果一球都投不進，被大家笑說是＿＿＿＿。', opts: ['東施效顰', '百發百中', '如魚得水', '亡羊補牢'], a: 0, why: '不看自己適不適合，硬學別人，結果更糟，用東施效顰。百發百中剛好相反，如魚得水是找到合適環境，亡羊補牢是補救。' },
      { id: 'x2', k: 'use', d: 2, type: 'tf', ctx: '〈校刊短評〉六年級的學長姊參觀了別的學校後，回來討論哪些做法適合我們學校，最後只選了「晨間閱讀」來試，還依照我們的作息調整了時間。有同學說這是東施效顰。', q: '這位同學說的「東施效顰」用得恰當。', a: false, why: '學長姊有考慮自己學校的情況，也調整了做法，不是盲目模仿，不能說東施效顰。' }
    ]
  },
  {
    id: 'cy023', lv: 1, word: '杯弓蛇影', zhuyin: 'ㄅㄟ ㄍㄨㄥ ㄕㄜˊ ㄧㄥˇ', src: '漢．應劭《風俗通義．怪神》',
    quote: '時北壁上有懸赤弩，照於杯，形如蛇',
    facts: ['典源是漢．應劭《風俗通義．怪神》（卷九〈世間多有見怪驚怖以自傷者〉）｜教育部《成語典》', '東漢時應郴在夏至那天請部下杜宣喝酒，掛在北邊牆上的弓映在酒杯裡，杜宣以為是蛇，喝下後就生病了｜教育部《成語典》典故說明', '應郴回官府後發現是弓的影子，再請杜宣坐回原位看清楚，杜宣的病就好了｜教育部《成語典》典故說明', '應郴當時是汲縣的縣令（原文「予之祖父郴，為汲令」），杜宣是他的部下（主簿）｜漢．應劭《風俗通義．怪神》', '《成語典》辨識：杯弓蛇影著重因虛幻的事物而害怕；草木皆兵、風聲鶴唳著重因外在情勢而害怕｜教育部《成語典》'],
    story: [
      '東漢的時候，有一位叫應郴的人，在汲縣當縣令。有一年夏至，天氣很熱，他請部下杜宣到官府裡喝酒，兩個人一邊喝一邊聊天。',
      '杜宣舉起酒杯，正要喝的時候，忽然看見杯子裡好像有一條紅色的小蛇，還在扭來扭去。他嚇了一大跳，可是長官請喝的酒，又不好意思不喝，只好硬著頭皮，閉上眼睛一口喝下去。',
      '回到家以後，杜宣一直覺得肚子怪怪的，好像蛇在肚子裡鑽來鑽去。他吃不下飯、睡不著覺，一天比一天瘦，請了很多醫生、吃了很多藥，病都沒有好。',
      '應郴聽說杜宣生病了，就去看他。杜宣說：「那天喝酒的時候，我好像把一條蛇喝進肚子裡了。」應郴覺得很奇怪，回到官府以後坐在那天喝酒的位子上，左看右看，終於發現：北邊的牆上掛著一把紅色的弓，弓的影子剛好映在酒杯裡，看起來就像一條蛇！',
      '應郴馬上派車把杜宣接來，請他坐在原來的位子上，倒了一杯酒說：「你再看看杯子裡。」杜宣一看，蛇又出現了。應郴指著牆上的弓說：「這條『蛇』，其實是那把弓的影子啊！」',
      '杜宣抬頭一看，恍然大悟，心裡的大石頭一下子放下來，病也馬上就好了。這件事後來被應郴的孫子應劭寫進書裡。人們就用「杯弓蛇影」比喻為了根本不存在的事疑神疑鬼，自己嚇自己，白白驚慌。'
    ],
    mean: '把杯子裡的弓影當成蛇。比喻因為不存在的事物而疑神疑鬼，白白驚慌害怕。',
    usage: ['用在害怕的東西其實不存在、是自己看錯或想像出來的時候。', '「杯弓蛇影」著重被「虛幻的東西」嚇到；「草木皆兵」「風聲鶴唳」著重被「緊張的情勢」嚇到。'],
    misuse: [],
    eg: ['晚上看到窗簾在晃，他以為有小偷，原來只是電風扇在吹，真是杯弓蛇影。', '聽完鬼故事以後，她連自己的影子都怕，這種杯弓蛇影的心情，過了好幾天才消失。'],
    syn: ['風聲鶴唳', '草木皆兵', '疑神疑鬼'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '杜宣在酒杯裡看到了什麼？', opts: ['一條紅色的小蛇', '一隻掉進去的蒼蠅', '自己的臉', '一片樹葉'], a: 0, why: '第二段：他「看見杯子裡好像有一條紅色的小蛇」。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '杜宣吃了很多藥，病就慢慢好了。', a: false, why: '第三段：「吃了很多藥，病都沒有好。」他的病是看清真相以後才好的。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '杜宣為什麼明明害怕，還是把酒喝下去？', opts: ['長官請的酒，他不好意思不喝', '他很口渴，想趕快喝東西', '他想證明自己一點都不怕蛇', '醫生說這杯酒可以治病'], a: 0, why: '第二段：「長官請喝的酒，又不好意思不喝，只好硬著頭皮」喝下去。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '杜宣的病，真正的原因是什麼？', opts: ['心裡一直害怕肚子裡有蛇', '真的有蛇在肚子裡咬傷了他', '那杯酒已經壞掉了', '夏天太熱讓他中暑'], a: 0, why: '杯子裡只有弓的影子（第四段），沒有真的蛇；他是越想越怕才生病，所以一知道真相（第六段），病馬上就好了。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '醫生和藥都治不好杜宣的病，應郴卻一下子就治好了。你覺得應郴的方法好在哪裡？如果你身邊有人「自己嚇自己」，你可以怎麼幫他？',
        ref: '應郴的方法好在他找到害怕的真正原因，而且讓杜宣自己親眼看到「蛇」只是弓的影子，杜宣就不會再懷疑。如果弟弟晚上怕房間裡有怪物，我會陪他把燈打開，一起看清楚衣櫃後面只是一件外套。',
        rubric: ['說出應郴方法的好處（找出原因、讓對方親眼看清楚）', '能用故事內容當證據', '提出一個幫助別人的具體做法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「杯弓蛇影」裡，酒杯中的「蛇」其實是什麼？', opts: ['牆上弓的影子', '真的小蛇', '杜宣的倒影', '酒裡的雜質'], a: 0, why: '故事第四段：北邊牆上掛著一把紅色的弓，影子映在酒杯裡，看起來像蛇。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '露營的晚上，小宇起床上廁所，看到帳篷外有一個黑黑長長的東西在晃，以為是大蛇，嚇得叫醒全家人。爸爸拿手電筒出去一照，原來是一條掛在樹枝上的跳繩，被風吹得一直搖。小宇不好意思的笑了。', q: '小宇的情形，最適合用哪個成語形容？', opts: ['杯弓蛇影', '葉公好龍', '亡羊補牢', '東施效顰'], a: 0, why: '把跳繩看成蛇，為了不存在的東西驚慌，就是杯弓蛇影。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈新聞短評〉山區連下三天大雨，氣象單位發出土石流警報，附近居民聽從安排，提早搬到學校避難。記者說居民這樣做是杯弓蛇影。', q: '記者用「杯弓蛇影」用得恰當。', a: false, why: '土石流警報是真的危險，不是看錯、想像出來的東西。提早避難是謹慎，不是杯弓蛇影。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '把成語和它跟「杯弓蛇影」的關係配起來。', pairs: [['疑神疑鬼', '近義：沒有根據的亂懷疑、害怕'], ['草木皆兵', '近義：情勢緊張，看什麼都像敵人'], ['葉公好龍', '無關：嘴上說喜歡，其實不是真心']], why: '《成語典》把疑神疑鬼、草木皆兵列為杯弓蛇影的近義。葉公好龍說的是表裡不一。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '杜宣把弓的影子當成蛇，越想越害怕，連身體都生病了。你有沒有因為看錯、聽錯，自己嚇自己的經驗？後來你是怎麼發現真相的？下次遇到可以怎麼做？',
        ref: '有一次半夜我聽到廚房「咚」一聲，以為有小偷，整晚不敢睡。第二天才知道是冰箱自動製冰掉下冰塊的聲音。下次我會先深呼吸，打開燈去看清楚，或是問家人，不要一直自己亂想。',
        rubric: ['說出一個看錯或聽錯而害怕的經驗', '說明後來怎麼發現真相', '提出下次可以怎麼做'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '她經過學校的舊倉庫，聽到「喀喀」聲就嚇得拔腿跑走，其實只是窗戶被風吹動，真是＿＿＿＿。', opts: ['杯弓蛇影', '百發百中', '如魚得水', '亡羊補牢'], a: 0, why: '把風吹窗戶的聲音當成可怕的東西，白白驚慌，用杯弓蛇影。其他三個放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '午休時，小琳伸手到抽屜裡，摸到一團毛茸茸、軟軟的東西，以為是老鼠，尖叫著跳起來，全班都被吵醒了。大家圍過去一看，原來是她自己早上塞進去的毛線手套。小琳紅著臉說：「我還以為有老鼠躲在裡面！」', q: '小琳的反應，最適合用哪一個成語形容？', opts: ['杯弓蛇影', '杞人憂天', '鷸蚌相爭', '自相矛盾'], a: 0, why: '把手套當成老鼠，是把眼前的東西認錯而驚慌，用杯弓蛇影。杞人憂天是擔心還沒發生、沒有根據的事，不是把東西看錯。' }
    ]
  },
  // ==================== L2 歷史故事 ====================
  {
    id: 'cy027', lv: 2, word: '三人成虎', zhuyin: 'ㄙㄢ ㄖㄣˊ ㄔㄥˊ ㄏㄨˇ', src: '《戰國策．魏策二》',
    quote: '夫市之無虎明矣，然而三人言而成虎',
    facts: ['典源是《戰國策．魏策二》：魏國大臣龐葱要陪太子到趙國的邯鄲當人質｜教育部《成語典》', '龐葱擔心離開後有人說他壞話，先用「街上有老虎」問魏王；後來果然有很多人說他壞話，回國後魏王就疏遠他、不再重用他｜教育部《成語典》典故說明', '《韓非子．內儲說上》也有這個故事，人物寫作「龐恭」｜《韓非子．內儲說上》'],
    story: [
      '戰國時代，國和國之間為了表示信任，有時會把太子送到對方國家去住，叫做「人質」。有一次，魏國的太子要到趙國的都城邯鄲當人質，魏王派大臣龐葱陪他一起去。',
      '出發前，龐葱心裡很不安。他知道朝廷裡有些人不喜歡他，自己離開那麼遠、那麼久，這些人一定會趁機在魏王面前說他的壞話。',
      '於是他去見魏王，問：「大王，如果現在有一個人跑來說，市場裡出現了一隻老虎，您相信嗎？」魏王說：「不信。市場裡人那麼多，怎麼會有老虎？」',
      '「如果又有第二個人跑來，也說市場裡有老虎呢？」魏王想了想：「那我就有點懷疑了。」「如果第三個人也這樣說呢？」魏王點點頭：「三個人都這麼說，那我大概就相信了。」',
      '龐葱說：「市場裡明明沒有老虎，可是三個人都這樣說，大王就相信有老虎了。邯鄲離我們這裡，比市場遠得多；以後說我壞話的人，也一定不只三個。希望大王能好好分辨。」魏王說：「你放心，我自己會判斷。」',
      '龐葱出發以後，說他壞話的人果然一個接著一個。等到太子結束人質的日子回國，龐葱再也見不到魏王，魏王已經疏遠他，不再重用他了。',
      '一句不是真的話，說的人多了，連答應過「自己會判斷」的國君都會相信。後來，人們就用「三人成虎」比喻謠言一再重複，就會讓人信以為真。'
    ],
    mean: '三個人都說市場裡有老虎，聽的人就相信真的有老虎。比喻謠言一再重複，就會讓人信以為真。',
    usage: ['用在「不是真的事，因為很多人一直說，就被當成真的」的情況，提醒人不要輕信傳言。', '重點是「假的消息被說成真的」；跟幾個人合作、人多力量大都沒有關係。'],
    misuse: ['「全班三個人一起努力，終於把海報做完了，真是三人成虎。」✗　三人成虎說的是謠言被當真，跟合作沒有關係，可以說「齊心協力」。'],
    eg: ['網路上有人說颱風假要連放三天，轉傳的人一多，大家都信了，結果根本沒有這回事，真是三人成虎。', '別小看三人成虎的力量，一句沒查證的話轉傳幾次，就可能傷害一個人的名聲。'],
    syn: ['以訛傳訛', '眾口鑠金', '積毀成山'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '龐葱要陪太子到哪裡去？', opts: ['趙國的邯鄲', '秦國的咸陽', '楚國的郢都', '燕國的易水'], a: 0, why: '第一段：太子「要到趙國的都城邯鄲當人質」。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '魏王聽到第一個人說市場有老虎時，就相信了。', a: false, why: '第三段：第一個人說的時候，魏王說「不信」；到第三個人他才說「大概就相信了」。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '龐葱出發前為什麼要問魏王「老虎」的問題？', opts: ['怕離開後有人說壞話，先提醒魏王', '他聽說市場裡真的出現了老虎', '他想知道魏王喜不喜歡老虎', '他想請魏王派人去抓老虎'], a: 0, why: '第二段：他擔心「這些人一定會趁機在魏王面前說他的壞話」，所以先用老虎打比方提醒魏王。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '故事的結局說明了什麼？', opts: ['提醒過了，謠言多還是會被相信', '魏王本來就一直很討厭龐葱', '龐葱在趙國做錯了很多事', '太子回國後不想再見龐葱'], a: 0, why: '第五段魏王說「我自己會判斷」，第六段卻還是相信了壞話。可見謠言一多，就算事先提醒過也擋不住。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '魏王答應龐葱「我自己會判斷」，最後還是相信了壞話。你覺得魏王應該怎麼做，才不會被謠言影響？請用故事內容說明。',
        ref: '魏王聽到壞話時，應該先問：「說的人有沒有親眼看到？有沒有證據？」也可以派人去邯鄲問清楚，或是等龐葱回來，聽聽他怎麼說。故事裡魏王只是一直聽別人說，沒有去查，才會把謠言當真。',
        rubric: ['提出至少一個不被謠言影響的方法（查證、問當事人等）', '用故事內容說明魏王哪裡做得不夠', '方法具體可行'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「三人成虎」的意思是什麼？', opts: ['謠言說的人多了，就會被當成真的', '三個人一起，力量像老虎一樣大', '三個人看到老虎，嚇得趕快逃走', '人多的地方，老虎就不敢靠近'], a: 0, why: '市場本來沒有老虎，三個人說了就被相信，比喻謠言重複多了被當真。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '有人在班級群組說：「聽說營養午餐的湯裡有蟲！」接著又有幾個人轉傳，還加上「我也聽說了」。到了中午，好多同學都不敢喝湯。後來營養師來班上說明，那天的湯根本沒有問題，也沒有任何人真的看到蟲。', q: '這件事最適合用哪個成語形容？', opts: ['三人成虎', '杯弓蛇影', '亡羊補牢', '鷸蚌相爭'], a: 0, why: '沒有人真的看到蟲，只是轉傳的人越來越多，大家就信以為真，是三人成虎。杯弓蛇影是把看到的東西認錯，這裡沒有人看到任何東西。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈班會紀錄〉這學期的整潔比賽，我們班得到第一名。班長說：「這是全班一起掃地、擦窗戶換來的，三人成虎，大家的力量真大！」', q: '班長用「三人成虎」恰當嗎？', opts: ['不恰當，它是指謠言被當真', '恰當，全班很多人一起努力', '恰當，人多力量像老虎一樣', '不恰當，我們班不只三個人'], a: 0, why: '三人成虎是說謠言一再重複就被相信，跟合作、力量大無關。這裡可以說「齊心協力」。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「一個人說那家早餐店的老闆生病了，第二個、第三個人也跟著說，結果大家都相信了，其實老闆只是出國旅行，這就是三人成虎。」這句話的「三人成虎」用得恰當。', a: true, why: '不是真的消息，說的人多了大家就相信，正是三人成虎。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '魏王因為聽到很多人說壞話，就不再相信龐葱。現在網路上的消息傳得很快，如果你在群組裡看到一則「聽說……」的消息，你會怎麼做，才不會變成「說老虎的第三個人」？',
        ref: '我會先想：這則消息是誰說的？有沒有可靠的來源，像是學校的公告或新聞？如果查不到，我就不轉傳，也會提醒傳給我的人先查證。這樣謠言傳到我這裡就會停下來。',
        rubric: ['提出一個查證消息的方法', '說明不隨便轉傳的理由', '連結到故事中謠言越傳越多、讓人相信的道理'] }
    ],
    xq: [
      { id: 'x1', k: 'sit', d: 2, type: 'mc', ctx: '有人在社區說：「公園的溜滑梯壞了，有小朋友受傷。」買菜的阿姨聽到，又告訴了早餐店老闆，老闆再告訴來吃早餐的客人。不到一天，整個社區都在說，好多家長都不讓孩子去公園。後來里長到公園檢查，發現溜滑梯好好的，也沒有人受傷。', q: '這件事最適合用哪一個成語形容？', opts: ['三人成虎', '杯弓蛇影', '葉公好龍', '班門弄斧'], a: 0, why: '沒有根據的消息越傳越多人，大家就當真了，是三人成虎。' },
      { id: 'x2', k: 'use', d: 2, type: 'tf', ctx: '小美：「我聽好多人說，下星期的英語課要換新老師了。」\n小華：「我問過教務處，根本沒有這回事。只是一傳十、十傳百，三人成虎，大家就都信了。」', q: '小華說的「三人成虎」用得恰當。', a: true, why: '消息不是真的，卻因為很多人在傳而被相信，用三人成虎恰當。' }
    ]
  },
  {
    id: 'cy030', lv: 2, word: '班門弄斧', zhuyin: 'ㄅㄢ ㄇㄣˊ ㄋㄨㄥˋ ㄈㄨˇ', src: '唐．柳宗元〈王氏伯仲唱和詩序〉',
    facts: ['典源是唐．柳宗元〈王氏伯仲唱和詩序〉｜教育部《成語典》', '柳宗元替王緯兄弟的唱和詩寫序，稱讚他們的詩可比應璩、應瑒和陸機、陸雲兩對兄弟，又說自己寫序像在魯班、郢匠門前耍弄斧頭，是在行家面前獻醜｜教育部《成語典》典故說明', '「班」指魯班，古代有名的巧匠｜教育部《成語典》釋義'],
    story: [
      '古代有一位手藝非常高明的工匠，名叫魯班。傳說他做的木器又精巧又堅固，木匠們都把他當成老師。另外，傳說中還有一位「郢匠」，揮起斧頭又快又準，也是大家佩服的高手。',
      '唐朝的時候，有一對姓王的兄弟，其中一位叫王緯。他們出生在讀書人的家庭，從小就很有文采。兄弟倆常常互相寫詩應和：你寫一首，我就照著題目再寫一首回應，叫做「唱和」。',
      '有一次，王家兄弟來到京城，把唱和的詩集合起來，請當時有名的文學家柳宗元幫忙寫一篇「序」，也就是放在書最前面的介紹文章。',
      '柳宗元讀了這些詩，十分欣賞。他在序裡稱讚，兩兄弟的詩，可以跟古代有名的應璩、應瑒兄弟，還有陸機、陸雲兄弟相比。',
      '可是寫到最後，柳宗元很客氣的說：這兩兄弟的詩寫得這麼好，自己卻要在前面替他們寫介紹，就好像拿著斧頭，跑到魯班和郢匠的家門口去揮舞一樣，真是厚著臉皮。意思是：在真正的高手面前表演，實在不好意思。',
      '後來，人們把這個比喻濃縮成「班門弄斧」。今天常用來批評在行家面前賣弄本領、不自量力的人；說自己的時候，也可以用來表示謙虛，例如：「在書法老師面前寫毛筆字，我這是班門弄斧了。」'
    ],
    mean: '在魯班門前耍弄斧頭。比喻在行家面前賣弄本事，不自量力。',
    usage: ['批評別人在專家面前賣弄、不知道自己有幾兩重（貶義）。', '說自己的時候常用來表示謙虛，例如「我只是班門弄斧，請大家多指教」。', '一定要有「行家、高手」在場；在不懂的人面前表演，不能說班門弄斧。'],
    misuse: ['「他在一年級的弟弟面前表演倒立，真是班門弄斧。」✗　弟弟不是倒立的高手，談不上在行家面前賣弄。'],
    eg: ['在全國冠軍面前講怎麼跳繩，我這是班門弄斧，大家聽聽就好。', '他只學了三個月的魔術，就跑到魔術師的店裡表演，簡直是班門弄斧。'],
    syn: ['布鼓雷門'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '王家兄弟請柳宗元做什麼？', opts: ['替他們的詩集寫一篇序', '教他們怎麼寫詩', '幫他們做一把很好用的斧頭', '帶他們去見魯班'], a: 0, why: '第三段：請柳宗元「幫忙寫一篇『序』」。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '柳宗元讀了王家兄弟的詩，覺得寫得不好。', a: false, why: '第四段：柳宗元「十分欣賞」，還拿他們跟古代有名的兄弟相比。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '柳宗元說自己像「在魯班門口揮斧頭」，是什麼意思？', opts: ['在高手作品前寫介紹，很不好意思', '他其實很會用斧頭砍木頭', '他想要跟魯班比賽，看誰比較厲害', '他覺得王家兄弟的詩寫太長'], a: 0, why: '第五段：「在真正的高手面前表演，實在不好意思。」他把王家兄弟比作魯班，自己寫序像弄斧。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '柳宗元用「班門弄斧」說自己，和今天用它批評別人，有什麼不同？', opts: ['說自己是謙虛，說別人是批評他不自量力', '說自己是誇獎，說別人是稱讚他很厲害', '兩種都是在稱讚對方斧頭用得好', '兩種都是在說木匠的工作很辛苦'], a: 0, why: '第五段柳宗元是客氣、謙虛；第六段說今天多用來批評別人在行家面前賣弄。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '柳宗元明明是很有名的文學家，卻說自己替人寫序是「班門弄斧」。你覺得他為什麼要這樣說？你欣賞這種說話方式嗎？請說明理由。',
        ref: '我覺得他是想表示尊重王家兄弟，讓大家知道主角是他們的詩。我欣賞這種說法，因為有名的人還這麼謙虛，會讓人更願意親近他。不過如果太常說客氣話，別人可能會覺得不夠真誠。',
        rubric: ['推想柳宗元這樣說的原因', '表明是否欣賞並說出理由', '能用故事內容（稱讚兄弟、自稱弄斧）當證據'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「班門弄斧」的「班」指的是誰？', opts: ['古代的巧匠魯班', '班上的同學', '柳宗元的學生', '一支軍隊的名稱'], a: 0, why: '「班」指魯班，古代有名的巧匠。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '社區請來一位得過全國比賽冠軍的麵包師傅，教大家做麵包。阿凱只在家裡看過幾支影片，卻搶著站到前面說：「師傅，你的揉麵方法不對，應該像我這樣！」他用力亂揉一通，麵團黏得滿手都是。旁邊的人都忍不住偷笑。', q: '阿凱的做法，最適合用哪個成語形容？', opts: ['班門弄斧', '三人成虎', '亡羊補牢', '杯弓蛇影'], a: 0, why: '阿凱在冠軍師傅（行家）面前賣弄自己不熟的本事，就是班門弄斧。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈日記〉今天我教一年級的小表妹折紙鶴，她從來沒有折過，一下就學會了。我覺得自己真是班門弄斧，教得好成功！', q: '這篇日記的「班門弄斧」用得恰當嗎？', opts: ['不恰當，表妹不是行家，也沒有賣弄的意思', '恰當，因為作者把自己會的事教給了別人', '恰當，因為班門弄斧就是很會教人', '不恰當，因為折紙鶴不用斧頭'], a: 0, why: '班門弄斧一定要在「行家」面前。表妹從沒折過，作者是在教她，不是在高手面前賣弄。' },
      { id: 'p4', k: 'judge', d: 3, type: 'tf', q: '「在國家音樂廳的鋼琴家面前，我彈了一首剛學會的小曲子，真是班門弄斧，請大家多包涵。」這句話的「班門弄斧」用得恰當。', a: true, why: '在鋼琴家（行家）面前彈琴，用班門弄斧表示自己的謙虛，用得恰當。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '柳宗元在高手面前保持謙虛。想一想，當你在某方面比你厲害的人面前（例如比你會畫畫、會打球的人），想要表現自己時，可以怎麼說、怎麼做，既能大方表現，又不會讓人覺得在賣弄？',
        ref: '表哥很會打籃球，有一次我想表演剛學會的胯下運球。我會先說：「我才剛學，做給你看，你幫我看看哪裡要改。」這樣我可以大方表現，又是在請教他，而不是在跟他比厲害。',
        rubric: ['設想一個在高手面前表現的情境', '提出既大方又謙虛的說法或做法', '說明這樣做為什麼不會變成賣弄'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '在下過幾十年圍棋的爺爺面前，我才學了一個月就說要教他下棋，這不是＿＿＿＿嗎？', opts: ['班門弄斧', '三人成虎', '杞人憂天', '如魚得水'], a: 0, why: '在行家（下了幾十年棋的爺爺）面前賣弄，用班門弄斧。其他三個放進句子都不通。' },
      { id: 'x2', k: 'use', d: 2, type: 'mc', ctx: '〈校刊〉體育課上，阿宏把剛學會的運球技巧，示範給從來沒打過籃球的轉學生看，還一步一步教他。轉學生很感謝，說：「謝謝你班門弄斧，教得好清楚！」', q: '轉學生說的「班門弄斧」用得恰當嗎？', opts: ['不恰當，轉學生不是高手，阿宏也沒有賣弄', '恰當，因為阿宏在別人面前表演了運球技巧', '恰當，因為班門弄斧就是熱心教別人', '不恰當，因為只有木匠能用班門弄斧'], a: 0, why: '轉學生沒打過籃球，不是行家；阿宏是熱心教人，不是賣弄。用班門弄斧反而像在說阿宏不自量力。' }
    ]
  },
  {
    id: 'cy035', lv: 2, word: '入木三分', zhuyin: 'ㄖㄨˋ ㄇㄨˋ ㄙㄢ ㄈㄣ', src: '南朝宋．羊欣《筆陣圖》',
    quote: '工人削之，筆入木三分', quoteFrom: '唐．張懷瓘《書斷．卷二》',
    facts: ['典源是南朝宋．羊欣《筆陣圖》｜教育部《成語典》', '「工人削之，筆入木三分」這段文字見於唐．張懷瓘《書斷》｜唐．張懷瓘《書斷．卷二》', '東晉書法家王羲之在祝版上寫字；皇帝到北郊祭祀要更換祝版，工人削木板時發現墨跡透進木頭三分深｜教育部《成語典》典故說明', '王羲之當過右軍將軍，人稱「王右軍」，後世尊稱「書聖」｜教育部《成語典》典故說明', '《成語典》辨識：入木三分可用於見解議論，也可用於人物性格刻畫；鞭辟入裡專用於議論｜教育部《成語典》'],
    story: [
      '東晉的時候，有一位非常有名的書法家，名叫王羲之。他當過右軍將軍，所以大家也叫他「王右軍」。他從小就愛寫字，每天練、天天練，寫出來的字有力又好看，後來被人尊稱為「書聖」。',
      '那個時候，皇帝要到京城北邊的郊外舉行祭祀。祭祀時要念的祝文，會先寫在一塊木板上，叫做「祝版」。有一次，祝版上的字就是請王羲之寫的。',
      '後來，祝版需要更換新的文字。工人拿起刀子，想把舊的字削掉，再寫上新的。他削了一層，字還在；又削了一層，字還是在。',
      '工人覺得很奇怪，就一直往下削，越削越深，最後發現：王羲之的墨跡竟然滲進木頭裡，大約有三分那麼深！大家都嚇了一跳，紛紛稱讚王羲之寫字的力量實在驚人。',
      '一支軟軟的毛筆，怎麼能把墨寫進木頭裡呢？這跟王羲之下筆很有力、又長年苦練有很大的關係。也因為這個故事，人們用「入木三分」來形容書法的筆力強勁。',
      '後來，「入木三分」的用法越來越廣。如果一篇評論把道理說得很深刻、很中肯，或是一本小說把人物寫得活靈活現、好像就在眼前，我們也可以說它「入木三分」。'
    ],
    mean: '墨跡透進木板三分深，形容書法筆力強勁。後來也比喻評論深刻中肯，或描寫生動逼真。',
    usage: ['形容書法、字寫得很有力。', '形容評論、分析很深刻，或是把人物的性格、神情描寫得很生動（褒義）。', '和「鞭辟入裡」都有深刻的意思，但鞭辟入裡只用在議論道理；入木三分還可以形容人物描寫。'],
    misuse: [],
    eg: ['這篇作文把奶奶做菜時的神情寫得入木三分，讀起來好像真的看到了她。', '評審對這部電影的分析入木三分，一下子就說出了它好看的原因。'],
    syn: ['力透紙背', '鞭辟入裡'], ant: ['不著邊際'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '「祝版」是什麼？', opts: ['寫著祭祀祝文的木板', '王羲之練字用的桌子', '皇帝送給王羲之的禮物', '工人削木頭用的刀子'], a: 0, why: '第二段：祝文「會先寫在一塊木板上，叫做『祝版』」。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '工人削了一層木板，王羲之的字就不見了。', a: false, why: '第三段：削了一層「字還在」，又削一層「字還是在」。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '從故事可以推想，王羲之的字為什麼能「入木三分」？', opts: ['下筆很有力，又長年不斷苦練', '他用的毛筆特別尖、特別硬', '工人削木板的刀子太鈍了', '祝版用的木頭特別軟'], a: 0, why: '第一段說他「每天練、天天練」，第五段說這跟他「下筆很有力、又長年苦練」有關。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '「入木三分」從形容寫字，後來又可以形容什麼？', opts: ['評論深刻，或人物描寫得很生動', '木頭很硬，工人怎麼削都削不掉', '做事很慢，要花很多時間', '把東西藏得很深，找不到'], a: 0, why: '最後一段：可以形容評論「深刻、中肯」，或小說把人物寫得「活靈活現」。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '工人發現墨跡透進木頭三分深，大家都很驚訝。你覺得這個故事是要稱讚王羲之的天分，還是他的努力？請用故事裡的內容說明你的看法。',
        ref: '我覺得比較是稱讚他的努力。故事第一段說他從小「每天練、天天練」，第五段也說入木三分跟他「長年苦練」有關。就算有天分，不練習也寫不出這麼有力的字。',
        rubric: ['表明自己的看法（天分、努力或兩者都有）', '引用故事內容當證據', '說明證據和看法之間的關係'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「入木三分」最早是形容什麼？', opts: ['書法的筆力很強', '木匠的刀法很好', '樹木長得很高大', '木頭裡藏了寶物'], a: 0, why: '最早是說王羲之的墨跡透進木板三分，形容書法筆力強勁。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '語文課上，小玲念了她寫的〈我的阿公〉。她寫阿公修腳踏車時，眼鏡滑到鼻尖、嘴裡哼著老歌，手上沾滿黑黑的機油，修好了還得意的按兩聲車鈴，再拍拍坐墊叫她上車。同學聽她念完都說：「好像阿公就站在我們面前！」', q: '同學對這篇作文的感覺，最適合用哪個成語形容？', opts: ['入木三分', '班門弄斧', '三人成虎', '東施效顰'], a: 0, why: '把人物寫得生動逼真，好像就在眼前，可以說描寫得入木三分。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈校園新聞〉工友伯伯修理講臺時，用鐵鎚把釘子一根一根敲進木板裡，每根都敲得入木三分，講臺變得很穩固。', q: '這則新聞用「入木三分」用得恰當。', a: false, why: '入木三分形容的是書法筆力，或評論、描寫很深刻，不是真的把釘子敲進木頭。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '把成語和它跟「入木三分」的關係配起來。', pairs: [['力透紙背', '近義：形容寫字筆力強勁'], ['鞭辟入裡', '近義：形容議論深刻透澈'], ['不著邊際', '反義：說話空泛，抓不到重點']], why: '《成語典》辨識欄：力透紙背、鞭辟入裡是近義，不著邊際是反義。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '王羲之的字能「入木三分」，靠的是長年練習。你有沒有一件想做到「入木三分」那麼好的事（寫字、畫畫、寫作、運動）？你打算怎麼練習？',
        ref: '我想把作文寫得像入木三分那樣生動。我打算每天寫三行日記，練習描寫一個人的動作和表情，例如媽媽煮飯時的樣子；每個星期再挑一篇讀給家人聽，問他們有沒有「好像看到了」。',
        rubric: ['說出一件想練好的事', '提出具體、可以持續的練習方法', '說明怎麼知道自己有沒有進步'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '這位記者把颱風過後農民收拾田地的辛苦描寫得＿＿＿＿，讀者看了都很感動。', opts: ['入木三分', '班門弄斧', '鷸蚌相爭', '杯弓蛇影'], a: 0, why: '描寫深刻、讓人感動，用入木三分。其他三個放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '學校舉辦書法比賽，評審老師拿起小剛的作品，仔細看了很久，說：「你看這一撇一捺，下筆又穩又重，每一個字都好像要從紙上站起來一樣。」原來小剛每天放學都練一小時，已經練了三年。同學們圍過來看，也都忍不住點頭。', q: '評審老師對小剛的字，最可能用哪一個成語稱讚？', opts: ['入木三分', '東施效顰', '葉公好龍', '杞人憂天'], a: 0, why: '下筆又穩又重，形容書法筆力強勁，用入木三分。' }
    ]
  },
  {
    id: 'cy038', lv: 2, word: '負荊請罪', zhuyin: 'ㄈㄨˋ ㄐㄧㄥ ㄑㄧㄥˇ ㄗㄨㄟˋ', src: '《史記．廉頗藺相如列傳》',
    quote: '廉頗聞之，肉袒負荊，因賓客至藺相如門謝罪',
    facts: ['典源是《史記．廉頗藺相如列傳》：戰國時趙國的大將廉頗和上卿藺相如｜教育部《成語典》', '藺相如因外交立功，官位比廉頗高，廉頗不服氣；藺相如處處迴避，說是把國家安危放在私人恩怨前面｜教育部《成語典》典故說明', '廉頗聽了很慚愧，背著荊條到藺相如家認錯，兩人成了好朋友；同一段故事也產生了成語「刎頸之交」｜教育部《成語典》'],
    story: [
      '戰國時代，趙國有兩位重要的大臣。一位是大將軍廉頗，打過很多勝仗，是趙國最勇猛的將軍；另一位是藺相如，他靠著勇氣和智慧，在和強大的秦國交涉時，好幾次替趙國保住了面子和寶物。',
      '因為藺相如立了大功，趙王封他當「上卿」，官位比廉頗還要高。廉頗很不服氣：「我在戰場上拚命，他只靠一張嘴，憑什麼排在我前面？要是讓我碰到他，我一定要讓他難堪！」',
      '藺相如聽說了，就處處避開廉頗。上朝的時候，他常常說自己生病不去；有一次坐車出門，遠遠看到廉頗的車子迎面而來，他馬上叫車夫把車轉進小巷子裡躲起來。',
      '藺相如的手下覺得很丟臉，紛紛說：「您的官比廉將軍大，為什麼要這樣怕他？我們都想走了。」藺相如問他們：「廉將軍和秦王比，誰比較厲害？」大家說：「當然是秦王。」',
      '藺相如說：「秦王那麼兇，我都敢當面跟他爭，怎麼會怕廉將軍呢？強大的秦國不敢來攻打趙國，就是因為趙國有我們兩個人。如果我們兩個互相爭鬥，就像兩隻老虎打架，總有一個會受傷。我躲著他，是把國家的安危放在前面，把個人的恩怨放在後面啊！」',
      '這些話傳到廉頗耳裡，他慚愧得滿臉通紅。他脫下上衣，背上綁著帶刺的荊條，請朋友帶路，到藺相如家門口認錯：「我是個粗人，不知道您這麼寬宏大量。請用這些荊條責罰我吧！」藺相如趕緊扶起他。從此，兩個人成了可以同生共死的好朋友。'
    ],
    mean: '背著荊條到對方家，請對方責罰。比喻主動向人承認錯誤，請求責罰和原諒。',
    usage: ['用在自己做錯事，主動、誠心去向對方認錯道歉的時候。', '認錯的人要是「做錯事的那一方」；被冒犯的人去找對方算帳，不能說負荊請罪。'],
    misuse: ['「同學弄壞了我的筆，我主動去找他負荊請罪，要他賠我。」✗　負荊請罪是犯錯的人去認錯；被弄壞東西的人去要求賠償，不是負荊請罪。'],
    eg: ['我不小心把同學的作業弄濕了，第二天一早就帶著新的資料夾去向他負荊請罪。', '比賽時我對隊友發了脾氣，賽後我主動找他負荊請罪，我們又和好了。'],
    syn: ['肉袒牽羊'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '廉頗為什麼不服氣藺相如？', opts: ['藺相如的官位比他還高', '藺相如搶走了他的寶物', '藺相如在戰場上打敗了他', '藺相如說了他的壞話'], a: 0, why: '第二段：趙王封藺相如當上卿，「官位比廉頗還要高」，廉頗很不服氣。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '藺相如在路上看到廉頗的車子，就叫車夫把車轉進小巷子躲起來。', a: true, why: '第三段寫得很清楚。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '藺相如為什麼要一直避開廉頗？', opts: ['怕兩人相爭，讓秦國有機會', '他真的很害怕廉頗會打他', '他那時生了重病不能出門', '他想讓廉頗覺得自己厲害'], a: 0, why: '第五段：秦國不敢攻打趙國，是因為趙國有他們兩個；兩人相爭會傷到國家。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '廉頗「背著荊條」去見藺相如，代表什麼意思？', opts: ['願意接受責罰，真心認錯', '想送荊條給藺相如當禮物', '想用荊條跟藺相如比武', '要藺相如幫他修補衣服'], a: 0, why: '第六段：廉頗說「請用這些荊條責罰我吧」，表示真心認錯、願意受罰。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '藺相如和廉頗，你比較欣賞誰？請用故事中他們說的話或做的事，說明你的理由。',
        ref: '我比較欣賞廉頗。他是有名的大將軍，卻願意脫下上衣、背著荊條去認錯，這需要很大的勇氣。很多人知道自己錯了也不肯道歉，廉頗卻能放下面子，所以後來兩人才能成為好朋友。',
        rubric: ['說出比較欣賞的人', '引用故事中這個人說的話或做的事', '說明這些表現為什麼值得欣賞'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「負荊請罪」的「負」是什麼意思？', opts: ['背著', '失敗', '欠錢', '負責'], a: 0, why: '「負荊」就是背著荊條。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '躲避球比賽輸了，阿威在休息時大聲責怪小傑：「都是你漏接，害我們輸了！」小傑難過得哭了。回家後阿威想了想，其實自己也漏接了好幾球。第二天，他一到學校就走到小傑的座位旁，低著頭說：「昨天是我不對，你要罵我也沒關係，對不起。」', q: '阿威第二天的做法，最適合用哪個成語形容？', opts: ['負荊請罪', '班門弄斧', '三人成虎', '入木三分'], a: 0, why: '阿威主動向小傑承認錯誤，還說「你要罵我也沒關係」，就像廉頗負荊請罪。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈聯絡簿〉今天妹妹拿走我的彩色筆，還畫斷了兩支。我很生氣，就跑去她房間負荊請罪，叫她以後不准再亂拿。', q: '這段聯絡簿用「負荊請罪」恰當嗎？', opts: ['不恰當，作者沒做錯事，是去責怪妹妹', '恰當，因為作者主動去找妹妹說清楚', '恰當，因為負荊請罪就是去找人算帳', '不恰當，因為家裡沒有荊條可以背'], a: 0, why: '負荊請罪是犯錯的人主動認錯。作者是被弄壞東西的一方，去責怪妹妹，剛好相反。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「上次我冤枉了表哥，今天特地帶著他最愛吃的點心去負荊請罪。」這句話的「負荊請罪」用得恰當。', a: true, why: '自己冤枉了表哥（做錯事），主動去認錯，用得恰當。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '廉頗是大將軍，卻願意放下面子，向藺相如認錯。你有沒有做錯事、卻不好意思道歉的經驗？如果重來一次，你會怎麼做？',
        ref: '有一次我不小心把同學的水壺碰倒，水灑在他的課本上，我怕被罵就假裝沒看到。如果重來一次，我會馬上說對不起，拿衛生紙幫他擦乾，再問他需不需要我幫忙抄筆記。',
        rubric: ['說出一個做錯事卻沒道歉的經驗', '提出具體的道歉方式', '說明認錯之後可以做哪些補救'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '昨天我在班會上說話太衝，傷了副班長的心，今天一早我就去向他＿＿＿＿。', opts: ['負荊請罪', '班門弄斧', '鷸蚌相爭', '百發百中'], a: 0, why: '自己說錯話，主動去認錯，用負荊請罪。其他三個放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '小如借了好朋友的故事書，卻不小心把果汁打翻在書上，頁面都皺了。她沒有偷偷把書還回去，而是拿著書和自己存的零用錢，到好朋友家說明經過：「是我太不小心了，這些錢給你買一本新的，請你原諒我。」', q: '小如的做法，最適合用哪一個成語形容？', opts: ['負荊請罪', '如魚得水', '杯弓蛇影', '入木三分'], a: 0, why: '小如主動承認錯誤、請求原諒，是負荊請罪。' }
    ]
  },
  {
    id: 'cy041', lv: 2, word: '百發百中', zhuyin: 'ㄅㄞˇ ㄈㄚ ㄅㄞˇ ㄓㄨㄥˋ', src: '《戰國策．西周策》',
    quote: '去柳葉者百步而射之，百發百中',
    facts: ['典源是《戰國策．西周策》：戰國時謀士蘇厲聽說秦國大將白起要攻打魏國的都城大梁｜教育部《成語典》', '蘇厲認為大梁被攻下，周就危險了，建議周王派人去勸白起，並講了楚國神射手養由基的故事｜教育部《成語典》典故說明', '養由基離柳葉一百步射箭，百發百中；有路人提醒他不懂得休息，累了只要一箭不中，就前功盡棄｜教育部《成語典》典故說明', '後來也用來形容料事、用計、施藥等非常準確｜教育部《成語典》釋義'],
    story: [
      '戰國時代，秦國有一位很會打仗的大將叫白起，他帶兵打敗了好幾個國家。有一年，白起準備去攻打魏國的都城大梁。謀士蘇厲聽說了，很擔心：大梁要是被攻下，周就危險了。',
      '蘇厲對周王說：「請大王派人去對白起講一個故事。」這個故事是這樣的——',
      '楚國有一個射箭高手，名叫養由基。他站在離柳樹一百步遠的地方，瞄準一片小小的柳葉射過去，一箭就射中。他一連射了一百箭，每一箭都射中柳葉。圍觀的人都拍手叫好：「真是百發百中啊！」',
      '這時，有一個路過的人說：「射得很好，不過，我可以教你射箭。」養由基有點不高興：「大家都說我射得好，你憑什麼教我？」',
      '那人說：「我不是要教你怎麼拉弓。我是想提醒你：你現在百發百中，卻不懂得見好就收、好好休息。等一下手臂痠了、力氣用完了，只要有一箭沒射中，你以前的成績就全白費了。」',
      '蘇厲要人轉告白起：「將軍已經打了那麼多勝仗，就像養由基射中了一百箭。現在還要去打大梁，萬一失敗，以前的功勞就前功盡棄了。不如說自己生病，不要出兵吧！」',
      '這個故事裡，「百發百中」原本是形容養由基的箭術高明，射一百次中一百次。後來也用來形容做事、預測、出主意非常準確，很少失手。'
    ],
    mean: '射一百箭，中一百箭。形容射擊技術非常高明；也形容預料事情、用計等非常準確。',
    usage: ['形容射擊、投籃、投球等「命中目標」的技術很高超（褒義）。', '也可以形容預測、判斷非常準，例如「天氣預報百發百中」。', '要是真的「每次都準」；只是常常參加、很努力練，但準不準不知道，不能說百發百中。'],
    misuse: [],
    eg: ['他練了一整個暑假的罰球，現在站上罰球線幾乎百發百中。', '姊姊猜考試題目一向百發百中，同學都叫她「小神算」。'],
    syn: ['百步穿楊', '矢無虛發', '料事如神'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '養由基站在離柳葉多遠的地方射箭？', opts: ['一百步', '十步', '五十步', '一千步'], a: 0, why: '第三段：「站在離柳樹一百步遠的地方」。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '路過的人想教養由基怎麼拉弓。', a: false, why: '第五段：那人說「我不是要教你怎麼拉弓」，而是提醒他要見好就收。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '路人說「以前的成績就全白費了」，是在提醒養由基什麼？', opts: ['射太多會累，該見好就收', '拉弓的姿勢不對，要重學', '柳葉太小，應該換大目標', '圍觀的人多，會讓他分心'], a: 0, why: '第五段：手臂痠了、力氣用完，只要一箭沒中，前面的成績就白費了，所以要懂得休息。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '蘇厲把白起比作養由基，是想勸白起怎麼做？', opts: ['勝仗已經夠多，別再冒險打大梁', '要像養由基一樣，每天多練射箭', '趕快攻打大梁，一定會贏', '請養由基來幫秦國打仗'], a: 0, why: '第六段：白起打了很多勝仗，就像射中了一百箭；再去打大梁萬一失敗，就前功盡棄。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '路人說要「見好就收」。你覺得在什麼情況下應該見好就收？什麼情況下應該繼續努力、不要停？請各舉一個例子，並用故事說明你的想法。',
        ref: '練琴練到手很痠的時候應該見好就收，就像養由基累了還一直射，反而會失手。可是如果是一首曲子還沒練熟，只是覺得有點難，就應該繼續練。累到會出錯時要休息，只是怕困難時不要放棄。',
        rubric: ['舉出一個該見好就收的例子', '舉出一個該繼續努力的例子', '能用故事內容（累了會失手、前功盡棄）說明分辨的方法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「百發百中」的「中」是什麼意思？', opts: ['射中目標', '中間位置', '中等程度', '中途停止'], a: 0, why: '「中」讀ㄓㄨㄥˋ，是射中、命中。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '學校的投籃比賽，阿豪站在線後，一顆接著一顆把球投出去。只見籃球劃出漂亮的弧線，「唰！唰！唰！」一連進了二十球，一球都沒有落空。圍觀的同學都看呆了，計分板上的數字一直往上跳，最後他輕輕鬆鬆拿下全校第一名。', q: '阿豪的投籃表現，最適合用哪個成語形容？', opts: ['百發百中', '班門弄斧', '入木三分', '負荊請罪'], a: 0, why: '投二十球進二十球，每一次都命中，就是百發百中。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈作文〉我們班玩猜謎遊戲，小芸猜了十題，錯了七題。大家都笑著說她百發百中，真是太厲害了！', q: '作文裡的「百發百中」用得恰當嗎？', opts: ['不恰當，她錯了七題，一點都不準', '恰當，因為她一連猜了十題', '恰當，百發百中就是很喜歡猜謎', '不恰當，百發百中只能用在射箭'], a: 0, why: '百發百中是每次都中。錯了七題剛好相反。它也可以形容猜測、預料很準，不是只能用在射箭。' },
      { id: 'p4', k: 'pair', d: 2, type: 'mc', q: '下面哪一個成語，跟「百發百中」的意思最接近？', opts: ['百步穿楊', '班門弄斧', '三人成虎', '杯弓蛇影'], a: 0, why: '《成語典》把百步穿楊列為近義，也是形容射箭非常準。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '養由基射得那麼準，背後一定練了很久。想一想，你有沒有哪一件事，想練到「百發百中」？你會怎麼安排練習？又要怎麼記得路人的提醒，適時休息？',
        ref: '我想把九九乘法練到百發百中。我會每天早上花五分鐘，請家人隨便抽題考我，錯的題目記在小卡片上隔天再練。不過我一次只練五分鐘，練太久會累，反而容易答錯。',
        rubric: ['說出一件想練到很準的事', '提出具體的練習安排', '說明怎麼安排休息，避免太累失手'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '這位氣象播報員預測下雨的時間，一個月來＿＿＿＿，大家都說他比鬧鐘還準。', opts: ['百發百中', '杯弓蛇影', '負荊請罪', '東施效顰'], a: 0, why: '每次預測都很準，用百發百中。其他三個放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '射箭社的學姊參加全市比賽，最後一輪要射十支箭。她深呼吸，拉弓、放箭，每一支都射進了靶心的黃色圈圈裡。裁判數完以後宣布：「十支全中！」臺下的家長和同學都站起來拍手，學姊開心得跳了起來，抱住了教練。', q: '學姊這一輪的表現，可以用哪一個成語形容？', opts: ['百發百中', '入木三分', '班門弄斧', '鷸蚌相爭'], a: 0, why: '十支箭全部射中靶心，沒有一支落空，是百發百中。入木三分形容的是筆力或描寫深刻。' }
    ]
  },
  {
    id: 'cy044', lv: 2, word: '草木皆兵', zhuyin: 'ㄘㄠˇ ㄇㄨˋ ㄐㄧㄝ ㄅㄧㄥ', src: '《晉書．苻堅載記》',
    quote: '望八公山上草木，皆類人形',
    facts: ['典源是《晉書．苻堅載記下》：前秦的苻堅帶大軍南下，和東晉在肥水對峙｜教育部《成語典》', '苻堅和弟弟苻融登上壽陽城，遠遠看見八公山上的草木，以為都是晉兵，臉上露出害怕的神情｜教育部《成語典》典故說明', '東晉孝武帝太元八年（西元383年），苻堅在肥水之戰敗給謝玄｜教育部《成語典》典故說明', '《成語典》辨識：草木皆兵的恐懼多來自外在情勢；杯弓蛇影的恐懼多來自虛幻的事物｜教育部《成語典》'],
    story: [
      '西元383年，中國北方有一個國家叫前秦，國君叫苻堅；南方則是東晉。苻堅打下了北方很多地方，越來越自信，決定帶著大軍南下，想一口氣打敗東晉。',
      '他很驕傲的說：「我的士兵那麼多，每個人把馬鞭丟進江裡，就能把江水擋住！東晉那一點點兵，有什麼好怕的？」',
      '東晉派出將軍謝石、謝玄帶兵迎戰。兩邊的軍隊隔著一條叫肥水的河對峙。苻堅和弟弟苻融登上壽陽城的城牆，想看看東晉軍隊的情形。',
      '他們看見晉軍的隊伍排得整整齊齊，士兵個個精神飽滿。苻堅再往北邊的八公山一看，心裡一驚：山上密密麻麻的，好像全都是晉國的士兵！其實，那只是山上的草和樹罷了。',
      '苻堅的臉色變了，轉頭對苻融說：「這也是很強的敵人啊，怎麼能說他們兵少呢？」原本驕傲的他，第一次露出害怕的神情。',
      '後來兩軍在肥水交戰，前秦的大軍亂成一團，苻堅打了敗仗，只好帶著剩下的人馬退回北方。這一場仗，就是歷史上有名的「肥水之戰」，也有人寫作「淝水之戰」。',
      '苻堅把草木看成敵兵，是因為戰爭的情勢緊張，心裡已經開始害怕了。後來，人們就用「草木皆兵」形容人在緊張害怕的時候，疑神疑鬼，看到什麼都以為有危險。'
    ],
    mean: '把山上的草和樹都看成敵兵。形容人在緊張害怕時疑神疑鬼，看到什麼都以為有危險。',
    usage: ['用在因為情勢緊張而變得疑神疑鬼、驚慌害怕的時候。', '和「杯弓蛇影」很像：草木皆兵的害怕多來自緊張的「情勢」；杯弓蛇影多來自把東西「看錯、想錯」。'],
    misuse: [],
    eg: ['社區傳出有小偷以後，大家都草木皆兵，一聽到狗叫就打開燈查看。', '球隊連輸好幾場，變得草木皆兵，對手一個假動作就讓大家亂成一團。'],
    syn: ['杯弓蛇影', '風聲鶴唳', '疑神疑鬼'], ant: ['處變不驚'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '苻堅在八公山上看到的「晉兵」，其實是什麼？', opts: ['山上的草和樹', '真的晉國士兵', '山上的大石頭', '一群飛過的鳥'], a: 0, why: '第四段：「其實，那只是山上的草和樹罷了。」' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '苻堅出兵前，覺得東晉的兵很少，一點都不怕。', a: true, why: '第二段他說：「東晉那一點點兵，有什麼好怕的？」' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '苻堅為什麼會把草木看成敵兵？', opts: ['看到晉軍很整齊，心裡開始害怕', '那天霧太大，什麼都看不清楚', '他的眼睛生病，看東西很模糊', '苻融騙他說山上都是晉兵'], a: 0, why: '第四段他先看到晉軍「排得整整齊齊」，心裡一驚，再看八公山就覺得到處都是兵。最後一段也說，是因為情勢緊張、心裡害怕。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '比較苻堅出兵前和登上城牆後的心情，有什麼變化？', opts: ['從驕傲自信，變成緊張害怕', '從緊張害怕，變成驕傲自信', '一直都很害怕，沒有改變', '一直都很自信，沒有改變'], a: 0, why: '第二段他很驕傲，第五段「第一次露出害怕的神情」。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '苻堅出兵前說大話，看到晉軍後卻嚇到把草木當成敵兵。你覺得太驕傲和太害怕，哪一個對他的影響比較大？請用故事內容說明。',
        ref: '我覺得太驕傲的影響比較大。因為他太看不起東晉，一開始沒有好好了解對手；等到真的看到晉軍很整齊，才一下子慌了，連草木都看成敵人。如果他一開始就謹慎，就不會從驕傲突然變成害怕。',
        rubric: ['選出一個並表明看法', '引用故事中苻堅前後的表現當證據', '說明驕傲和害怕之間的關係'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「草木皆兵」是什麼意思？', opts: ['緊張害怕，看什麼都以為是敵人', '山上的花草長得像士兵一樣整齊', '每個士兵都很愛護花草樹木', '打仗時用草木做成假的士兵'], a: 0, why: '苻堅心裡害怕，把草木都看成敵兵，比喻緊張得疑神疑鬼。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '學校最近在走廊發生了好幾次文具不見的事。從那天起，小柔變得很緊張：同學經過她的座位，她就趕快抱住鉛筆盒；有人在後面講話，她就以為在說要拿她的東西。一整天下來，她什麼事都做不好，累得不得了。', q: '小柔這幾天的樣子，最適合用哪個成語形容？', opts: ['草木皆兵', '百發百中', '負荊請罪', '入木三分'], a: 0, why: '因為文具常不見的緊張情勢，小柔看到誰都懷疑，就是草木皆兵。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈日記〉今天天氣很好，我和弟弟在公園裡放風箏，看到滿山的花草樹木，綠油油的好漂亮，真是草木皆兵啊！', q: '日記裡的「草木皆兵」用得恰當。', a: false, why: '草木皆兵是形容緊張害怕、疑神疑鬼，不是形容花草樹木很多、很漂亮。' },
      { id: 'p4', k: 'pair', d: 3, type: 'match', q: '把成語和它跟「草木皆兵」的關係配起來。', pairs: [['風聲鶴唳', '近義：聽到一點聲音就驚慌害怕'], ['處變不驚', '反義：遇到變化也很鎮定'], ['百發百中', '無關：射得非常準']], why: '《成語典》辨識欄：風聲鶴唳是近義，處變不驚是反義。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '苻堅在緊張的時候，把草木都看成敵兵。你有沒有在很緊張的時候（比賽前、考試前、一個人在家），覺得到處都有問題？你可以用什麼方法讓自己冷靜下來？',
        ref: '運動會接力賽前，我緊張到覺得鞋帶一直鬆、大家都在看我。後來我發現深呼吸三次，再把等一下要做的動作在心裡想一遍，就比較冷靜。也可以跟隊友說說話，就不會一直亂想。',
        rubric: ['說出一個緊張時疑神疑鬼的經驗', '提出至少一個讓自己冷靜的方法', '說明這個方法為什麼有用'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '地震過後，大家＿＿＿＿，連卡車開過去、窗戶震一下，都以為又地震了。', opts: ['草木皆兵', '班門弄斧', '百發百中', '如魚得水'], a: 0, why: '地震後情勢緊張，一點動靜都以為是地震，用草木皆兵。其他三個放進句子都不通。' },
      { id: 'x2', k: 'use', d: 2, type: 'mc', ctx: '〈運動會報導〉大隊接力決賽，五年三班一路領先，最後一棒衝過終點，全班歡聲雷動，大家草木皆兵，抱在一起又叫又跳。', q: '這段報導的「草木皆兵」用得恰當嗎？', opts: ['不恰當，大家是開心慶祝，不是緊張害怕', '恰當，因為全班的人數很多', '恰當，因為大家排得像士兵一樣整整齊齊', '不恰當，因為比賽場地沒有草木'], a: 0, why: '草木皆兵形容緊張害怕、疑神疑鬼。全班是贏了比賽在開心慶祝，意思完全不合。' }
    ]
  },
  {
    id: 'cy047', lv: 2, word: '退避三舍', zhuyin: 'ㄊㄨㄟˋ ㄅㄧˋ ㄙㄢ ㄕㄜˋ', src: '《左傳．僖公二十三年》',
    quote: '晉、楚治兵，遇於中原，其辟君三舍',
    facts: ['典源是《左傳．僖公二十三年》：晉國公子重耳流亡到楚國，楚成王用盛大的酒宴招待他｜教育部《成語典》', '楚成王問重耳將來怎麼報答，重耳說如果兩國軍隊在中原相遇，他會讓軍隊後退九十里；楚軍還進逼，才拿起弓箭周旋｜教育部《成語典》典故說明', '古代三十里為一舍；原文「辟君三舍」的「辟」通「避」｜教育部《成語典》', '重耳後來回國當上國君，就是晉文公｜《左傳．僖公二十四年》', '晉、楚兩軍在城濮相遇時，晉文公真的命令軍隊後退三舍（九十里），實踐了當年的話；這一仗楚軍由大將子玉帶領，楚成王本人沒有上陣｜《左傳．僖公二十八年》'],
    story: [
      '春秋時代，晉國的國君晉獻公很寵愛一位叫驪姬的妃子。驪姬想讓自己的兒子當太子，就在宮裡製造許多風波。晉獻公的兒子重耳為了保住性命，只好離開晉國，到處流浪。',
      '重耳在外面流浪了十幾年，走過很多國家。有些國君看不起他，對他很冷淡；有些國君則看出他是個人才，對他很好。',
      '有一天，重耳來到南方的大國楚國。楚國的國君楚成王用很隆重的宴會招待他，好酒好菜擺滿桌子。喝到一半，楚成王笑著問：「公子，如果有一天你回到晉國當上國君，要怎麼報答我呢？」',
      '重耳想了想說：「美女、寶玉、絲綢，大王您都有了；珍貴的鳥羽、象牙、皮革，也都是楚國出產的，我實在不知道拿什麼報答您。」楚成王說：「話雖然這麼說，你總要報答我一點什麼吧？」',
      '重耳認真的回答：「如果託大王的福，我能回到晉國，將來晉國和楚國的軍隊不得不在中原相遇，我會先讓軍隊往後退三舍，也就是九十里，來報答您。如果退了這麼遠，楚軍還是一直追過來，我才會拿起弓箭，跟您周旋。」',
      '後來重耳果然回國當上國君，就是有名的晉文公。幾年以後，晉國和楚國真的在城濮這個地方對峙，晉文公遵守當年的承諾，先命令軍隊後退了九十里。',
      '古時候行軍，三十里叫做「一舍」，「退避三舍」就是退後九十里。後來，人們用它比喻主動退讓，不和別人相爭。'
    ],
    mean: '古代三十里為一舍，退避三舍是讓軍隊後退九十里。比喻主動退讓，不和人相爭。',
    usage: ['用在主動讓步、避免和別人起衝突的時候。', '「舍」在這裡讀ㄕㄜˋ，是古代的距離單位，不是「捨不得」的「捨」。', '一定是「讓開、往後退」；跑在前面、遙遙領先，剛好相反。'],
    misuse: [],
    eg: ['學弟跟我搶同一個社團的名額，我想他比我更需要，就退避三舍，改報別的社團。', '兩班都想借體育館，我們班主動退避三舍，把時間讓給要比賽的班級。'],
    syn: [], ant: ['周旋到底', '當仁不讓'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '重耳說要怎麼報答楚成王？', opts: ['兩軍相遇時，先讓軍隊後退九十里', '送給楚成王很多美女、寶玉和絲綢', '把晉國的一半土地送給楚國', '每年送楚國很多象牙和皮革'], a: 0, why: '第五段：「我會先讓軍隊往後退三舍，也就是九十里，來報答您。」' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '「一舍」是三十里，「三舍」就是九十里。', a: true, why: '最後一段：「三十里叫做『一舍』，『退避三舍』就是退後九十里。」' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '重耳說「美女、寶玉、絲綢，大王您都有了」，是想表達什麼？', opts: ['楚國什麼都不缺，很難用財物報答', '楚成王太貪心了，什麼東西都想要', '他身上沒有帶任何的禮物', '晉國的東西比楚國的更好'], a: 0, why: '第四段：寶物楚國都有，「我實在不知道拿什麼報答您」，所以後來才想出退避三舍這種報答方式。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '從晉文公在城濮的做法，可以看出他是怎樣的人？', opts: ['說到做到，遵守承諾', '膽小怕事，不敢打仗', '愛說大話，從不做到', '忘恩負義，不記得恩情'], a: 0, why: '第五段他答應退三舍，第六段在城濮「遵守當年的承諾，先命令軍隊後退了九十里」。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '重耳的回答，一方面感謝楚成王，一方面也表示晉國不會一直退讓。你覺得這個回答好在哪裡？如果是你，會怎麼回答楚成王？',
        ref: '這個回答好在既有禮貌，又有骨氣。他願意先退九十里報恩，但也說清楚楚軍再追就會對抗，不會讓晉國吃虧。如果是我，我也會先感謝楚成王，再說將來兩國有事時願意先讓步、好好談，但不會答應做傷害自己國家的事。',
        rubric: ['說出回答的優點（報恩、也守住底線）', '能用故事中重耳說的話當證據', '提出自己的回答方式'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「退避三舍」的「舍」是什麼意思？', opts: ['三十里的距離', '住人的房子', '捨棄、放下', '古代的兵器'], a: 0, why: '古代行軍三十里為一舍，三舍就是九十里。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '下課時，阿哲和小偉都想用唯一的一顆排球。小偉急得快要跟阿哲吵起來，阿哲卻笑著說：「沒關係，你們先玩，我去跳繩。」他把排球遞給小偉，自己走到另一邊。後來小偉玩完，還特地把球拿來給阿哲，跟他說謝謝。', q: '阿哲的做法，最適合用哪個成語形容？', opts: ['退避三舍', '草木皆兵', '三人成虎', '東施效顰'], a: 0, why: '阿哲主動讓出排球，不和小偉爭，是退避三舍。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈運動會報導〉大隊接力時，五年四班的最後一棒一路領先，他越跑越快，把後面的對手遠遠甩開，退避三舍，最後拿下第一名。', q: '這段報導用「退避三舍」恰當嗎？', opts: ['不恰當，它是主動退讓，不是領先', '恰當，他把對手甩得很遠', '恰當，因為接力賽要跑很長的距離', '不恰當，接力賽沒有九十里'], a: 0, why: '退避三舍是自己往後退、讓給別人。把對手甩在後面是遙遙領先，意思剛好相反。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '把成語和它跟「退避三舍」的關係配起來。', pairs: [['當仁不讓', '反義：該做的事主動承擔，不推讓'], ['周旋到底', '反義：跟對方對抗到最後'], ['負荊請罪', '無關：主動認錯，請求原諒']], why: '《成語典》辨識欄把當仁不讓、周旋到底列為反義。負荊請罪說的是認錯。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '重耳用「主動退讓」來報答別人的恩情。想一想，在生活中什麼時候「退一步」反而是好的？什麼時候不應該一直退讓？請各舉一個例子。',
        ref: '排隊玩遊樂器材時，看到年紀小的弟弟妹妹很想玩，我讓他們先玩，大家都很開心，這時退一步是好的。可是如果有人一直插隊，或要我把作業給他抄，我就不應該退讓，要清楚的說「不可以」。',
        rubric: ['舉出一個適合退讓的例子', '舉出一個不應該退讓的例子', '說明兩者的差別（是否傷害自己或違反規則）'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '看到學弟妹也想玩盪鞦韆，哥哥＿＿＿＿，讓他們先玩。', opts: ['退避三舍', '百發百中', '杯弓蛇影', '班門弄斧'], a: 0, why: '主動讓步給學弟妹，用退避三舍。其他三個放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '社區的籃球場只剩一個籃框。國中的大哥哥們和小學生都想用，眼看就要吵起來了。大哥哥們討論了一下，說：「你們年紀小，先打吧！我們去旁邊練跑步，半個小時後再回來。」小學生們開心的拍手道謝，一場爭吵就這樣化解了。', q: '大哥哥們的做法，最適合用哪一個成語形容？', opts: ['退避三舍', '鷸蚌相爭', '草木皆兵', '葉公好龍'], a: 0, why: '大哥哥們主動讓出球場，避免爭吵，是退避三舍。鷸蚌相爭是兩方爭得都吃虧，剛好相反。' }
    ]
  },
  {
    id: 'cy050', lv: 2, word: '如魚得水', zhuyin: 'ㄖㄨˊ ㄩˊ ㄉㄜˊ ㄕㄨㄟˇ', src: '《三國志．蜀書．諸葛亮傳》',
    quote: '孤之有孔明，猶魚之有水也',
    facts: ['典源是《三國志．蜀書．諸葛亮傳》：劉備得到諸葛亮（孔明）以後，兩人感情越來越好｜教育部《成語典》', '關羽、張飛不高興，劉備說「孤之有孔明，猶魚之有水也，願諸君勿復言」｜《三國志．蜀書．諸葛亮傳》', '《成語典》收了三個意思：比喻筆法靈活、比喻得到志同道合的人或適合自己發展的環境、比喻兩人感情親密；本則講第二個｜教育部《成語典》'],
    story: [
      '東漢末年，天下大亂，各地的英雄都想闖出一番事業。劉備是其中一位，他身邊有兩位勇猛的好兄弟——關羽和張飛，可是一直缺少一位能出主意、看清天下局勢的人。',
      '有人告訴劉備：「有一位叫諸葛亮的人，字孔明，很有智慧。」劉備就親自去拜訪，去了三次，才見到諸葛亮。諸葛亮替劉備分析天下大勢，說明該先做什麼、後做什麼，劉備聽了非常佩服，請他出來幫忙。',
      '從此，劉備什麼事都跟諸葛亮商量，兩人常常一起討論事情，感情一天比一天好。',
      '關羽和張飛看在眼裡，心裡不太舒服：「我們跟大哥出生入死那麼多年，這個新來的年輕人，憑什麼這麼受重視？」他們常常在劉備面前抱怨。',
      '劉備聽了，耐心的對他們說：「我有了孔明，就像魚有了水一樣。希望你們不要再說了。」魚離開水就活不下去，劉備是在告訴兩位兄弟：孔明對他非常重要，有了孔明，他才能好好發揮。關羽和張飛聽了，就不再抱怨了。',
      '後來，人們就用「如魚得水」，比喻遇到志同道合的人，或是找到很適合自己發揮的環境，就像魚兒在水裡一樣自在。'
    ],
    mean: '像魚得到了水一樣。比喻遇到志同道合的人，或得到很適合自己發展的環境。',
    usage: ['用在遇到合得來的夥伴，或到了很適合自己的地方，做起事來輕鬆自在的時候（褒義）。', '只是「喜歡玩水、會游泳」不能用如魚得水；要有「找到適合自己的人或環境」的意思。'],
    misuse: [],
    eg: ['小安很愛畫畫，參加美術社以後如魚得水，每天都畫得好開心。', '哥哥轉到有棒球隊的學校，遇到一群一樣熱愛棒球的隊友，簡直如魚得水。'],
    syn: ['志同道合', '意氣相投'], ant: ['格格不入', '龍困淺灘'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '劉備去拜訪諸葛亮幾次，才見到他？', opts: ['三次', '一次', '兩次', '十次'], a: 0, why: '第二段：「去了三次，才見到諸葛亮。」' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '關羽和張飛一開始就很高興劉備請來了諸葛亮。', a: false, why: '第四段：他們「心裡不太舒服」，還常常抱怨。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '劉備說「我有了孔明，就像魚有了水」，是想讓關羽、張飛明白什麼？', opts: ['孔明對他非常重要，少不了', '他喜歡吃魚，想請孔明煮魚', '他打算搬到河邊去住', '關羽和張飛已經不重要了'], a: 0, why: '第五段：魚離開水就活不下去，劉備是說孔明對他非常重要。他沒有說兩位兄弟不重要。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '劉備請諸葛亮出來幫忙之前，最缺少的是什麼樣的人？', opts: ['能出主意、看清局勢的人', '力氣很大、很會打仗的人', '很會煮飯、照顧大家的人', '很有錢、可以出軍費的人'], a: 0, why: '第一段說他「缺少一位能出主意、看清天下局勢的人」，第二段諸葛亮正好替他分析天下大勢。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '關羽、張飛覺得新來的孔明太受重視，心裡不舒服。如果你是劉備，除了說「如魚得水」這句話，你還會怎麼做，讓大家都能好好相處？',
        ref: '我會找關羽、張飛一起和孔明討論事情，讓他們知道孔明出主意、他們帶兵打仗，大家各有長處，少了誰都不行。我也會公開感謝他們多年來的辛苦，讓他們知道自己沒有被忘記。',
        rubric: ['提出一個具體的做法', '做法能照顧到關羽、張飛的感受', '能說明大家各有長處、可以合作'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「如魚得水」最常用來比喻什麼？', opts: ['找到合適的夥伴或環境', '游泳游得像魚一樣非常快', '魚缸的水要常常換', '下雨時到處都是水'], a: 0, why: '比喻得到志同道合的人，或適合自己發展的環境。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '小倫在原本的班上話很少，因為大家都在聊卡通，他只喜歡研究昆蟲。升上五年級，他加入了學校的自然探索社，社員們每天都在討論蝴蝶、甲蟲，還一起做觀察紀錄。小倫每天都笑得好開心，還當上了社長。', q: '小倫加入自然探索社以後，最適合用哪個成語形容？', opts: ['如魚得水', '退避三舍', '草木皆兵', '班門弄斧'], a: 0, why: '小倫找到一群志同道合的夥伴，也找到適合自己的地方，就是如魚得水。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈日記〉今天第一次上游泳課，我很怕水，一下水就嗆到，嚇得緊緊抓住池邊不敢放手，真是如魚得水。', q: '日記裡的「如魚得水」用得恰當。', a: false, why: '作者很怕水、很不自在，剛好跟如魚得水相反。不能因為「在水裡」就用這個成語。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '把成語和它跟「如魚得水」的關係配起來。', pairs: [['志同道合', '近義：彼此的志向、想法相同'], ['格格不入', '反義：跟環境或別人合不來'], ['草木皆兵', '無關：緊張得疑神疑鬼']], why: '《成語典》辨識欄：志同道合是近義，格格不入是反義。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '劉備找到孔明，就像魚得到水。你覺得自己在什麼地方、跟什麼人在一起時，最「如魚得水」？為什麼？如果到了一個讓你覺得不自在的新環境，你可以怎麼讓自己慢慢適應？',
        ref: '我在學校的合唱團最如魚得水，因為大家都喜歡唱歌，練習時會互相提醒。如果到了不自在的新環境，像剛轉學，我會先找一個跟我有相同興趣的同學聊天，慢慢交到朋友。',
        rubric: ['說出一個讓自己如魚得水的地方或夥伴', '說明原因', '提出適應新環境的具體方法'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '姊姊很喜歡說話，又有好口才，當上學校的廣播員以後，真是＿＿＿＿。', opts: ['如魚得水', '杞人憂天', '鷸蚌相爭', '負荊請罪'], a: 0, why: '找到很適合自己的工作，用如魚得水。其他三個放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '阿美從小就愛做菜，常常在廚房幫阿嬤包水餃。學校開了烹飪社，她第一個報名。社團老師教的切菜、調味，她一學就會，還常常想出新口味，大家都搶著吃她做的點心。阿美說：「在烹飪社的時間，是我一星期最快樂的時候。」', q: '阿美在烹飪社的樣子，可以用哪一個成語形容？', opts: ['如魚得水', '班門弄斧', '三人成虎', '退避三舍'], a: 0, why: '阿美到了最適合自己的社團，學得快又開心，就是如魚得水。' }
    ]
  },
  // ==================== L3 寓意加深 ====================
  {
    id: 'cy053', lv: 3, word: '韋編三絕', zhuyin: 'ㄨㄟˊ ㄅㄧㄢ ㄙㄢ ㄐㄩㄝˊ', src: '《史記．孔子世家》',
    quote: '讀易，韋編三絕',
    facts: ['典源是《史記．孔子世家》：孔子晚年喜歡讀《易》｜教育部《成語典》', '「韋」是熟牛皮，古時候用來把竹簡串連成書；孔子反覆讀《易》，串竹簡的皮繩斷了好幾次｜教育部《成語典》釋義、典故說明', '孔子說：如果再多給他幾年時間，他對《易》就能了解得更透澈｜《史記．孔子世家》'],
    story: [
      '在紙還沒有被普遍使用的時候，古人寫字寫在哪裡呢？答案是竹片。人們把竹子削成一條一條細長的竹片，叫做「竹簡」，在上面一個字一個字寫上去。',
      '一片竹簡只能寫一行字，一本書就要用好多好多片。為了不讓竹簡散掉，人們用皮繩把它們一片一片串起來，捲成一捆。這種用來串竹簡的熟牛皮繩，就叫做「韋」。',
      '春秋時代的孔子，是一位很愛讀書的老師。他到了晚年，特別喜歡讀一本叫《易》的書，也就是後來說的《易經》。這本書講的是天地萬物變化的道理，內容非常深奧，很不容易讀懂。',
      '孔子不怕難。他讀一遍不懂，就讀第二遍；第二遍還不懂，就讀第三遍、第四遍……每讀一次，就要把竹簡打開、捲起，再打開、再捲起。',
      '一天又一天，串竹簡的皮繩被他翻來翻去，越磨越細，終於「啪」的一聲斷掉了。孔子把竹簡重新串好，接著讀；過了一段時間，皮繩又斷了。就這樣，皮繩斷了好幾次，孔子還是一直讀下去。',
      '孔子已經是學問很大的人，卻還是這樣認真。他甚至說：如果能再多給他幾年時間，他對《易》的了解就能更透澈。',
      '這件事被寫進《史記．孔子世家》。後來，人們就用「韋編三絕」來比喻讀書非常勤奮、刻苦用功。「絕」是斷掉，「三」表示好幾次。'
    ],
    mean: '串竹簡的皮繩斷了好幾次。比喻讀書非常勤奮、刻苦用功。',
    usage: ['用在稱讚人讀書、研究學問非常勤奮，反覆用功的時候（褒義）。', '重點是「因為反覆讀，把書都讀舊了」的用功；書被弄髒、弄壞，不能說韋編三絕。'],
    misuse: ['「弟弟把故事書拿來當墊子踩，書都破了，真是韋編三絕。」✗　書破是因為不愛惜，不是反覆閱讀，不能用韋編三絕。'],
    eg: ['姊姊為了準備科展，把那本昆蟲圖鑑翻到書頁都鬆了，真有韋編三絕的精神。', '這位作家年輕時韋編三絕，每本喜歡的書都讀了十幾遍。'],
    syn: ['廢寢忘食'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '在紙還沒有被普遍使用以前，古人把字寫在什麼上面？', opts: ['竹片', '石頭', '樹葉', '布料'], a: 0, why: '第一段：「答案是竹片。」' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '孔子讀《易》，為什麼會把皮繩讀斷？', opts: ['反覆打開、捲起竹簡太多次', '他讀書時太生氣，把繩子扯斷', '竹簡太重，繩子撐不住', '他的學生不小心把繩子剪斷'], a: 0, why: '第四、五段：每讀一次就要打開、捲起，翻來翻去，皮繩越磨越細就斷了。' },
      { id: 'r3', p: 2, d: 2, type: 'tf', q: '從孔子說「再多給他幾年時間」，可以推想他覺得自己對《易》的了解還不夠透澈。', a: true, why: '第六段：他希望多幾年，好讓自己「了解得更透澈」，可見他覺得還沒讀通。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '作者在故事前兩段先介紹竹簡和皮繩，有什麼作用？', opts: ['讓人懂皮繩斷掉代表讀了很多遍', '告訴讀者竹子可以做成很多東西', '說明古人寫的字比今天漂亮', '教讀者動手做一本竹簡書'], a: 0, why: '先知道書是用皮繩串竹簡做的，才看得懂「皮繩斷了好幾次」代表孔子翻了非常多次。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '孔子已經是很有學問的人，還是一遍又一遍讀不容易懂的書。你覺得這種「讀很多遍」的方法，適合用在所有的書嗎？請說出你的看法和理由。',
        ref: '我覺得不一定。像《易》這種很深的書，或是課本裡重要的觀念，讀很多遍才能真的懂；可是漫畫、一般的故事書，讀一兩遍就知道內容，不用讀到皮繩斷掉。要看書的難度和讀書的目的來決定。',
        rubric: ['表明適合或不適合所有書的看法', '說出理由（書的難度、讀書目的等）', '能連結到孔子讀《易》的例子'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「韋編三絕」的「絕」是什麼意思？', opts: ['斷掉', '絕對', '好看', '最後'], a: 0, why: '「三絕」就是斷了好幾次，指串竹簡的皮繩斷掉。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '小宏很想把魔術方塊轉好。他借了一本教學書，每天放學都照著書上的步驟練習，看不懂的地方就一頁一頁反覆讀。兩個月後，書的邊角都捲起來了，書背也鬆了好幾頁，小宏終於能在一分鐘內把方塊轉好。', q: '小宏讀教學書的樣子，最適合用哪個成語形容？', opts: ['韋編三絕', '如魚得水', '東施效顰', '百發百中'], a: 0, why: '小宏反覆讀同一本書，把書都讀舊了，正是韋編三絕的用功。' },
      { id: 'p3', k: 'judge', d: 2, type: 'tf', q: '「爺爺研究臺灣的老地名幾十年，那幾本地圖集被他翻得都快散了，真是韋編三絕。」這句話的「韋編三絕」用得恰當。', a: true, why: '因為長年反覆研讀，把書翻到快散，用韋編三絕恰當。' },
      { id: 'p4', k: 'use', d: 3, type: 'mc', ctx: '〈圖書館公告〉最近有些圖書被借回去以後，封面被撕破、內頁被亂畫，甚至泡過水。這種韋編三絕的情形，請大家一定要改善。', q: '公告用「韋編三絕」恰當嗎？', opts: ['不恰當，書被弄壞不是因為用功讀', '恰當，因為書真的被弄得很破舊', '恰當，因為韋編三絕是說書很難借', '不恰當，因為圖書館的書不是竹簡'], a: 0, why: '韋編三絕是稱讚反覆用功讀書。書被撕破、亂畫是不愛惜，用這個成語反而變成稱讚。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '孔子遇到難懂的書，用「一讀再讀」的方法。你在學習上有沒有一直弄不懂的地方（例如一種數學題型、一首要背的詩）？請想一個「韋編三絕」式的練習計畫，說說你會怎麼做。',
        ref: '我一直弄不懂分數的除法。我的計畫是：每天把課本那一頁的例題重新讀一遍，自己再做兩題；做錯的題目抄在筆記本上，週末再重做一次。連續練兩個星期，看看能不能全部做對。',
        rubric: ['說出一個自己弄不懂的學習內容', '提出反覆練習的具體計畫（頻率、方法）', '說明怎麼確認自己有沒有學會'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '為了讀懂這本天文書，她＿＿＿＿，一讀再讀，連書頁都翻得起毛了。', opts: ['韋編三絕', '退避三舍', '杞人憂天', '草木皆兵'], a: 0, why: '一讀再讀、把書翻舊，用韋編三絕。其他三個放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '學校舉辦「最愛的一本書」分享會。小真帶來一本已經很舊的成語故事書，書角都磨圓了，書頁也有好幾處用膠帶黏過。她說，這本書她從二年級讀到現在，至少讀了二十遍，每次讀都有新的發現，裡面的故事她幾乎都能背出來。', q: '小真讀這本書的情形，可以用哪一個成語形容？', opts: ['韋編三絕', '三人成虎', '杯弓蛇影', '班門弄斧'], a: 0, why: '一本書讀了二十遍，讀到書都舊了，是韋編三絕。' }
    ]
  },
  {
    id: 'cy057', lv: 3, word: '樂不思蜀', zhuyin: 'ㄌㄜˋ ㄅㄨˋ ㄙ ㄕㄨˇ', src: '晉．習鑿齒《漢晉春秋》',
    quote: '此間樂，不思蜀',
    facts: ['典源是晉．習鑿齒《漢晉春秋》（《三國志》裴松之注引用）：蜀漢滅亡後，後主劉禪被送到魏國的洛陽｜教育部《成語典》', '司馬昭設宴，故意安排蜀地的歌舞，劉禪仍然很開心；被問想不想念蜀國，他回答「此間樂，不思蜀」｜教育部《成語典》典故說明', '蜀漢舊臣郤正教劉禪改說想念祖先的墳墓，結果被司馬昭看穿，在場的人都笑了｜教育部《成語典》典故說明', '《成語典》辨識：樂不思蜀另有忘本、不想回去的意思；樂而忘返偏重沉迷而不知道回去｜教育部《成語典》'],
    story: [
      '三國時代，劉備在西南方建立了蜀漢。劉備去世以後，由兒子劉禪接下國君的位子，大家叫他「後主」，他的小名叫「阿斗」。',
      '劉禪當國君很多年，後來蜀漢被魏國滅了。劉禪和一些大臣被帶到魏國的都城洛陽，從此住在那裡。',
      '當時魏國真正掌權的人是司馬昭。有一天，他設宴請劉禪吃飯，還特地安排了蜀地的歌舞表演。坐在一旁的蜀漢舊臣，聽到家鄉的音樂，想起已經回不去的故鄉，一個個都難過得低下頭來。只有劉禪看得津津有味，又吃又笑，好像一點都不在意。',
      '過了幾天，司馬昭問劉禪：「你想不想念蜀國啊？」劉禪笑著回答：「這裡很快樂，我不想念蜀國。」',
      '蜀漢的舊臣郤正聽了，私下對劉禪說：「下次司馬昭再問，您應該流著眼淚說：『祖先的墳墓都在蜀地，我每天都很想念。』然後閉上眼睛，表現出很傷心的樣子。」',
      '後來司馬昭又問了一次，劉禪就照著郤正教的話說了一遍，努力想擠出眼淚，卻怎麼也哭不出來，只好閉上眼睛。司馬昭說：「這話怎麼跟郤正說的一模一樣？」劉禪嚇了一跳，睜開眼睛說：「真的就是郤正教我的！」在場的人都忍不住笑了出來。',
      '劉禪說出「此間樂，不思蜀」，讓人覺得他只顧眼前的快樂，忘了自己的國家和人民。後來，人們就用「樂不思蜀」比喻在外地過得太快樂，不想回到原來的地方；也可以形容玩得太開心，忘了要回去。'
    ],
    mean: '快樂得不想念蜀國。比喻在別的地方過得很快樂，不想回到原來的地方；也形容玩得太開心而忘了回去。',
    usage: ['形容在外地或某個地方玩得太開心，捨不得回去。', '有時帶有「忘了根本、忘了責任」的批評意思。', '和「樂而忘返」很像，但樂不思蜀多了「忘本、不想回去」的意思。'],
    misuse: ['「他第一次到外婆家住，想家想得一直哭，真是樂不思蜀。」✗　一直想家，剛好和樂不思蜀相反。'],
    eg: ['表弟到農場玩了三天，餵羊、摘草莓，玩得樂不思蜀，一直吵著不要回家。', '哥哥說他出國念書不會樂不思蜀，學成了一定回來幫忙家裡的事。'],
    syn: ['樂而忘返'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '司馬昭第一次問劉禪想不想念蜀國，劉禪怎麼回答？', opts: ['這裡很快樂，不想念蜀國', '祖先的墳墓在蜀地，很想念', '想回蜀國，請讓我回去', '不知道，要問郤正才知道'], a: 0, why: '第四段：「這裡很快樂，我不想念蜀國。」第二個選項是郤正後來教他說的話。' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '聽到蜀地的歌舞，蜀漢舊臣都難過的低下頭，為什麼？', opts: ['想起再也回不去的家鄉', '覺得表演得太難聽了', '擔心司馬昭會罵他們', '因為他們吃得太飽了'], a: 0, why: '第三段：他們「聽到家鄉的音樂，想起已經回不去的故鄉」。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '司馬昭說「這話怎麼跟郤正說的一模一樣」，表示他發現了什麼？', opts: ['劉禪的話是別人教的，不是真心話', '郤正和劉禪本來就是很要好的朋友', '劉禪的記性比別人好很多', '郤正自己也很想回到蜀國'], a: 0, why: '劉禪擠不出眼淚、說的話又跟郤正一樣，司馬昭看穿那是被教的，不是他真的想念蜀國。' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '比較故事裡劉禪和蜀漢舊臣的表現，作者想讓讀者看出什麼？', opts: ['劉禪只顧眼前快樂，不像舊臣記掛故國', '劉禪比舊臣們更懂得欣賞蜀地的歌舞表演', '舊臣太愛哭，不懂得享受生活', '劉禪和舊臣其實心裡想的一樣'], a: 0, why: '第三段舊臣難過、劉禪又吃又笑；最後一段說劉禪「只顧眼前的快樂，忘了自己的國家」。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '有人說劉禪是真的糊塗；也有人說他是故意裝糊塗，好讓司馬昭放心。你比較同意哪一種說法？請用故事裡的內容說明理由。',
        ref: '我比較同意他是真的不在意。因為舊臣都難過得低頭，他卻又吃又笑；郤正教他說的話，他也演不出來，還自己說出是郤正教的。如果他是故意裝的，應該會演得更像一點。',
        rubric: ['選出一種說法並表明立場', '引用故事中劉禪的表現當證據', '說明證據怎麼支持自己的看法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「樂不思蜀」的「蜀」指的是什麼？', opts: ['劉禪原本的國家蜀漢', '一種很好吃的水果', '司馬昭住的地方', '一首蜀地的歌曲'], a: 0, why: '「不思蜀」就是不想念蜀國，蜀是劉禪原本的國家蜀漢。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '寒假時，小婕到住在花蓮的姑姑家玩。她每天去海邊撿石頭、騎腳踏車、吃好吃的小吃，晚上還跟表姊一起看星星，玩得好開心。家人打電話問她什麼時候回來，她都說：「再住幾天嘛，這裡好好玩，我一點都不想回家！」', q: '小婕在姑姑家的樣子，最適合用哪個成語形容？', opts: ['樂不思蜀', '草木皆兵', '杞人憂天', '退避三舍'], a: 0, why: '在外地玩得太開心，一點都不想回家，就是樂不思蜀。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈日記〉今天是畢業旅行的第一天，可是我很想家，晚上躺在床上一直想著家裡的飯菜，好想趕快回去。我真是樂不思蜀啊！', q: '日記裡的「樂不思蜀」用得恰當。', a: false, why: '作者很想家、想趕快回去，剛好跟樂不思蜀相反。' },
      { id: 'p4', k: 'pair', d: 2, type: 'mc', q: '下面哪一個成語，跟「樂不思蜀」的意思最接近？', opts: ['樂而忘返', '韋編三絕', '負荊請罪', '入木三分'], a: 0, why: '《成語典》把樂而忘返列為近義：都有快樂得忘了回去的意思。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '劉禪在洛陽過得很快樂，卻忘了自己的國家。想一想，當你玩得很開心時（打電動、出去玩、看影片），有沒有忘了該做的事？你可以怎麼提醒自己「玩得開心，也不忘記責任」？',
        ref: '有一次我在朋友家玩桌遊，玩到忘了回家寫功課，結果熬夜才寫完。現在我出去玩以前，會先跟家人說好幾點回家，並在手錶設鬧鐘；鬧鐘一響，就算還想玩也要先回家。',
        rubric: ['說出一次玩得忘了責任的經驗', '提出具體的提醒方法', '說明怎麼兼顧玩樂和責任'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '小狗第一次到大草原，跑來跑去，＿＿＿＿，叫了好幾次都不肯回車上。', opts: ['樂不思蜀', '韋編三絕', '三人成虎', '自相矛盾'], a: 0, why: '玩得太開心不想回去，用樂不思蜀。其他三個放進句子都不通。' },
      { id: 'x2', k: 'use', d: 3, type: 'mc', ctx: '〈校刊專訪〉學長到國外讀書六年，拿到學位後馬上回到家鄉的小學教書。他說：「我在國外一直樂不思蜀，每天都想著家鄉，想早一點回來。」', q: '學長說的「樂不思蜀」用得恰當嗎？', opts: ['不恰當，他很想家，意思相反', '恰當，他在國外住了很久', '恰當，他在國外讀得很快樂', '不恰當，只能用在蜀國'], a: 0, why: '學長每天想著家鄉，跟「快樂得不想回去」剛好相反。樂不思蜀是比喻，不是只能用在蜀國。' }
    ]
  },
  {
    id: 'cy060', lv: 3, word: '邯鄲學步', zhuyin: 'ㄏㄢˊ ㄉㄢ ㄒㄩㄝˊ ㄅㄨˋ', src: '《莊子．秋水》',
    quote: '未得國能，又失其故行矣，直匍匐而歸耳',
    facts: ['典源是《莊子．秋水》：戰國時名家公孫龍聽不懂莊子的話，去請教魏國公子魏牟｜教育部《成語典》典故說明', '魏牟用燕國壽陵少年到趙國都城邯鄲學走路的故事勸他：沒學會別人的，連自己原本的走法也忘了，只好爬回家｜教育部《成語典》典故說明', '《成語典》辨識：東施效顰著重招來反效果；邯鄲學步著重連原有的都喪失掉｜教育部《成語典》'],
    story: [
      '戰國時代，燕國有一個叫壽陵的地方，住著一個少年。他聽說趙國的都城邯鄲很繁華，那裡的人走起路來特別好看，抬頭挺胸、步伐輕快，人人都稱讚。',
      '少年心想：「我走路的樣子普普通通，要是能學會邯鄲人的走法，大家一定會羨慕我！」於是他收拾行李，走了好遠的路，來到邯鄲。',
      '到了邯鄲，他站在大街上，看見一個人走過去，就跟在後面學；又看見另一個人走路的樣子不一樣，又趕快換一個學。今天學這個人的步伐，明天學那個人的擺手，學得手忙腳亂。',
      '他越學越覺得自己原來的走法不好看，就努力把以前的習慣全都改掉，每走一步都要先想：「腳要先抬多高？手要怎麼擺？」結果，邯鄲人的走法他沒有學會，連自己原本怎麼走路，也完全想不起來了。最後，他只好趴在地上，一路爬回燕國。',
      '這個故事記在《莊子．秋水》裡。當時有一位很會辯論的人叫公孫龍，他聽不懂莊子說的道理，卻硬要用自己的方法去理解。魏國的公子魏牟就講了這個故事勸他：「你再這樣硬要學下去，小心連自己原來會的學問也弄丟了。」',
      '後來，人們就用「邯鄲學步」比喻一味模仿別人，不但沒學到，反而把自己原來的本領也丟掉了。'
    ],
    mean: '到邯鄲學走路，沒學會別人的，又忘了自己的走法。比喻一味模仿別人不成，反而失去自己原有的本領或特色。',
    usage: ['用在盲目模仿，結果沒學會、連自己原本會的也丟了的時候（貶義）。', '和「東施效顰」不同：東施效顰重在「學了反而更糟」，邯鄲學步重在「連自己原有的都丟了」。'],
    misuse: ['「他到國外學了兩年英文，口說進步很多，真是邯鄲學步。」✗　學習有成果、沒有失去原本的能力，不能用邯鄲學步。'],
    eg: ['她原本寫字很工整，看到別人寫草書很帥就跟著亂學，結果寫得誰都看不懂，真是邯鄲學步。', '向別人學習是好事，但不要邯鄲學步，把自己原本的優點都丟了。'],
    syn: ['東施效顰', '生搬硬套'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '壽陵少年為什麼要到邯鄲去？', opts: ['想學邯鄲人走路的樣子', '想去邯鄲找工作賺錢', '想去邯鄲拜訪親戚', '想看邯鄲的熱鬧市集'], a: 0, why: '第二段：他想「學會邯鄲人的走法」。' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '少年為什麼後來連自己原來的走法都忘了？', opts: ['他把舊習慣全改掉，又沒學會新的', '他在邯鄲街上摔了一跤，腳受傷了', '邯鄲的路太難走，只能用爬的', '他太想家，沒有心思好好走路'], a: 0, why: '第四段：他「把以前的習慣全都改掉」，新的又沒學會，結果兩邊都沒了。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '魏牟說「小心連自己原來會的學問也弄丟了」，他是在提醒公孫龍什麼？', opts: ['不要硬學自己不適合的東西', '趕快去邯鄲學習走路的樣子', '多找莊子辯論幾次比輸贏', '把自己的學問寫成一本書'], a: 0, why: '第五段：公孫龍聽不懂莊子，卻硬要理解；魏牟怕他像少年一樣，新的沒學到、舊的也丟了。' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '「邯鄲學步」和「東施效顰」都在說模仿失敗，兩者最大的不同是什麼？', opts: ['邯鄲學步強調連原有的都丟了', '邯鄲學步的主角是女生', '東施效顰發生在邯鄲', '東施效顰的主角最後爬回家'], a: 0, why: '依《成語典》辨識：東施效顰著重「反效果」，邯鄲學步著重「連原有的都喪失」，就像少年連路都不會走了。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '少年想讓自己變得更好，這個想法沒有錯。你覺得他應該怎麼學，才不會「邯鄲學步」？請用故事裡他的做法來說明。',
        ref: '他不應該今天學這個、明天學那個，也不應該把自己原來的走法全部丟掉。他可以先看清楚邯鄲人走路好看在哪裡，例如抬頭挺胸，只挑一兩個適合自己的地方慢慢練，原本會的走法留著，這樣就不會兩邊都沒了。',
        rubric: ['指出少年做法的問題（亂學、全部丟掉舊的）', '提出比較好的學習方法', '能用故事中的情節當證據'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「邯鄲學步」的「邯鄲」是什麼？', opts: ['戰國時趙國的都城', '一種走路的姿勢', '少年的名字', '燕國的一條河'], a: 0, why: '邯鄲是戰國時趙國的都城。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '小傑本來跑步很快，他在電視上看到短跑選手的起跑姿勢很帥，就照著亂學，還把自己原本的擺手方式改掉。練了一個月，新的姿勢沒學會，連原本的節奏也亂了。運動會時，他反而跑得比以前還慢，自己也很懊惱。', q: '小傑的情形，最適合用哪個成語形容？', opts: ['邯鄲學步', '樂不思蜀', '韋編三絕', '百發百中'], a: 0, why: '新的沒學會，原本會的也亂了，正是邯鄲學步。' },
      { id: 'p3', k: 'judge', d: 2, type: 'tf', q: '「每天照著字帖練字，練了半年字變得很漂亮，這就是邯鄲學步。」這句話的「邯鄲學步」用得恰當。', a: false, why: '照著字帖練習、而且進步了，是成功的學習，沒有失去原本的能力，不能用邯鄲學步。' },
      { id: 'p4', k: 'use', d: 3, type: 'mc', ctx: '〈作文評語〉你這次的作文，努力模仿課本裡名家的句子，但是每一句都很長、很難懂，原本你最拿手的生動對話也不見了。老師覺得有點像邯鄲學步，下次寫回你自己的樣子吧！', q: '老師用「邯鄲學步」恰當嗎？', opts: ['恰當，模仿沒學好，又丟了原本的優點', '不恰當，因為作者寫這篇作文很努力', '不恰當，邯鄲學步只能說走路', '恰當，因為作者寫的句子太長了'], a: 0, why: '名家的句子沒學好，原本拿手的對話也不見了，正是邯鄲學步。只說句子太長，沒說到「丟了原本的優點」這個重點。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '少年只看到邯鄲人走路好看，卻沒想到自己原本的走法也很好用。想一想，你有沒有自己的「原本的優點」？如果你想向別人學習，要怎麼做才能「學到新的，又不丟掉舊的」？',
        ref: '我畫畫的顏色很大膽，這是我的優點。我很想學同學畫人物很準的方法，我會先只練人物的比例，顏色還是照自己的方式塗。這樣可以把新的方法加進來，又不會把自己的特色丟掉。',
        rubric: ['說出一個自己原本的優點', '說出想向別人學的地方', '提出兼顧新舊的具體做法'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '她看別人用新的方法背單字，就把自己原本有效的方法全丟掉，結果新的不習慣、舊的也忘了，簡直是＿＿＿＿。', opts: ['邯鄲學步', '樂不思蜀', '鷸蚌相爭', '如魚得水'], a: 0, why: '新的沒學會、舊的也丟了，用邯鄲學步。其他三個放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '阿明原本說話的聲音很溫和，大家都喜歡聽他說故事。他羨慕電臺主持人說話很有氣勢，就每天模仿那種又快又大聲的說法。結果他說故事變得結結巴巴，原本吸引人的溫柔語氣也不見了，同學聽了都說不習慣。', q: '阿明的情形，可以用哪一個成語形容？', opts: ['邯鄲學步', '負荊請罪', '如魚得水', '杯弓蛇影'], a: 0, why: '學別人的說話方式沒學好，原本的優點也丟了，是邯鄲學步。' }
    ]
  },
  {
    id: 'cy064', lv: 3, word: '投筆從戎', zhuyin: 'ㄊㄡˊ ㄅㄧˇ ㄘㄨㄥˊ ㄖㄨㄥˊ', src: '《東觀漢記．卷一六．班超列傳》',
    quote: '大丈夫無它志略，猶當效傅介子、張騫立功異域', quoteFrom: '《後漢書．班超傳》',
    facts: ['典源是《東觀漢記．卷一六．班超列傳》：東漢班超家裡窮，替官府抄書賺錢奉養母親｜教育部《成語典》', '班超抄書抄得厭煩，放下筆嘆氣說，大丈夫應該效法傅介子、張騫，到邊疆立功｜教育部《成語典》典故說明', '「戎」是軍隊；投筆從戎比喻棄文從軍，為國家建立功業｜教育部《成語典》釋義', '旁人笑他，班超說「小子安知壯士志哉」；後來他出使西域，讓西域許多國家和漢朝往來｜《後漢書．班超傳》'],
    story: [
      '東漢的時候，有一個年輕人叫班超。他的哥哥班固是有名的史學家，家裡雖然都是讀書人，生活卻很窮。為了養家，班超到官府替人抄寫文書，一個字一個字寫，賺一點點錢奉養母親。',
      '抄書的工作很辛苦，又很單調。每天從早到晚，班超都坐在桌子前低著頭寫，一年又一年，似乎永遠沒有改變。',
      '有一天，班超抄著抄著，忽然把毛筆往桌上一放，長長嘆了一口氣：「男子漢就算沒有什麼了不起的計謀，也應該像傅介子、張騫那樣，到遙遠的邊疆去為國家立功，怎麼能一輩子都待在筆和硯臺旁邊呢？」',
      '旁邊的人聽了，都笑他說大話。班超說：「你們怎麼會懂得壯士的志向呢？」',
      '後來，班超真的離開了書桌，跟著軍隊出征，又奉命帶著少數的人出使西域。西域在中國的西邊，有很多大大小小的國家。班超在那裡憑著勇氣和智慧，和各國往來，讓西域許多國家重新和漢朝交好。他在西域待了三十年左右，年紀很大了才回到故鄉。',
      '班超放下筆、投身軍隊的故事，就是「投筆從戎」的由來。「投」是丟下、放下，「戎」是軍隊。後來，人們用它比喻放下書本或文書工作、從軍報國，也表示有遠大的志向。'
    ],
    mean: '丟下筆去從軍。比喻放下文書工作或書本，加入軍隊，為國家建立功業。',
    usage: ['用在稱讚人放下原本的讀書、文書工作，去從軍報效國家（褒義）。', '一定跟「從軍」有關；只是換工作、改行，不能用投筆從戎。'],
    misuse: ['「他不想再當工程師，辭職去開麵包店，真是投筆從戎。」✗　投筆從戎是放下文書工作去從軍，跟改行開店無關。'],
    eg: ['書上說，那位作家年輕時曾經投筆從戎，在軍隊裡待了好幾年才回來寫作。', '爺爺說，他的老同學大學讀到一半就投筆從戎，後來成了一位飛行員。'],
    syn: ['棄文就武'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '班超原本在官府做什麼工作？', opts: ['抄寫文書', '帶兵打仗', '教小孩讀書', '種田養豬'], a: 0, why: '第一段：「班超到官府替人抄寫文書。」' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '班超說「怎麼能一輩子都待在筆和硯臺旁邊」，表示他想要什麼？', opts: ['到邊疆為國家立功', '換一支更好用的筆', '當一位有名的書法家', '趕快把書抄完回家'], a: 0, why: '第三段：他想「像傅介子、張騫那樣，到遙遠的邊疆去為國家立功」。' },
      { id: 'r3', p: 2, d: 2, type: 'tf', q: '從旁邊的人「笑他說大話」，可以推想當時大家不太相信班超真的做得到。', a: true, why: '第四段：大家笑他說大話，表示不相信一個抄書的人能到邊疆立功。' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '把班超抄書時的心情和後來在西域的表現放在一起看，這個故事最想強調什麼？', opts: ['有遠大志向，又真的去做，才能成功', '抄書是一件很沒有用的工作', '只要會說大話，就會被別人重視', '到外國去一定比待在家好'], a: 0, why: '第三段他立下志向，第五段真的到西域做出成績。光說不做，或只抄書不想改變，都不會有後來的故事。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '班超放下穩定的工作，去做一件很困難、別人都不看好的事。你覺得他的選擇勇敢嗎？如果你有一個大家都說「做不到」的夢想，你會怎麼做？',
        ref: '我覺得他很勇敢，因為抄書雖然單調，但是很安穩；去邊疆很危險，大家還笑他。我想當獸醫，有人說很難考。我會先把自然和數學學好，多讀動物的書，也去動物醫院當小志工，一步一步靠近夢想。',
        rubric: ['對班超的選擇提出看法並說明理由', '說出一個自己的夢想', '提出實現夢想的具體步驟'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「投筆從戎」的「戎」是什麼意思？', opts: ['軍隊', '文章', '毛筆', '邊疆'], a: 0, why: '「戎」是軍隊、軍事；「從戎」就是從軍。' },
      { id: 'p2', k: 'judge', d: 2, type: 'tf', q: '「他從小就愛讀書，長大後一直在大學教書，這就是投筆從戎。」這句話的「投筆從戎」用得恰當。', a: false, why: '他一直在教書，沒有放下文書工作去從軍，不能用投筆從戎。' },
      { id: 'p3', k: 'sit', d: 2, type: 'mc', ctx: '〈地方新聞〉一位在報社當了五年記者的年輕人，看到新聞裡的軍人在颱風過後幫忙清理災區，深受感動。他決定放下手上的採訪工作，報考軍校，希望能用自己的力量保護家園。他的同事說：「我們都很佩服他的決定。」', q: '這位年輕人的選擇，最適合用哪個成語形容？', opts: ['投筆從戎', '樂不思蜀', '邯鄲學步', '負荊請罪'], a: 0, why: '放下記者的文字工作，去報考軍校、從軍報國，就是投筆從戎。' },
      { id: 'p4', k: 'use', d: 3, type: 'mc', ctx: '〈部落格〉我的表哥原本是銀行行員，每天面對電腦和數字。去年他辭掉工作，回到鄉下種有機蔬菜，現在每天在田裡曬太陽。我覺得他真是投筆從戎！', q: '這篇文章用「投筆從戎」恰當嗎？', opts: ['不恰當，表哥是改行種菜，不是從軍', '恰當，因為表哥放下了原本的工作', '恰當，因為種菜跟打仗一樣辛苦', '不恰當，因為銀行行員不用拿毛筆'], a: 0, why: '投筆從戎一定跟從軍有關。表哥是改行種菜，不能用這個成語。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '班超說：「怎麼能一輩子都待在筆和硯臺旁邊呢？」他不滿足於現狀，想做更有意義的事。你長大以後想做什麼對別人有幫助的事？為了這個志向，你現在可以先做哪些準備？',
        ref: '我長大想當消防員，保護大家的安全。現在我可以先把身體練好，每天跳繩、跑步；也可以學會基本的急救知識，參加學校的防災演練，認真記住逃生的方法。',
        rubric: ['說出一個對別人有幫助的志向', '提出現在就能做的具體準備', '說明準備和志向之間的關係'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '他大學念的是中文系，畢業後卻＿＿＿＿，考進空軍學校，夢想開飛機保衛國家。', opts: ['投筆從戎', '樂不思蜀', '韋編三絕', '邯鄲學步'], a: 0, why: '從讀書轉去從軍報國，用投筆從戎。其他三個放進句子都不通。' },
      { id: 'x2', k: 'use', d: 2, type: 'tf', ctx: '小華：「我叔叔本來在公司當會計，後來他放下工作，加入了海軍，現在在船上守護海洋。」\n小明：「哇！你叔叔是投筆從戎呢！」', q: '小明說的「投筆從戎」用得恰當。', a: true, why: '叔叔放下文書性質的會計工作，加入海軍保衛國家，用投筆從戎恰當。' }
    ]
  },
  {
    id: 'cy067', lv: 3, word: '江郎才盡', zhuyin: 'ㄐㄧㄤ ㄌㄤˊ ㄘㄞˊ ㄐㄧㄣˋ', src: '南朝梁．鍾嶸《詩品．卷中》',
    quote: '爾後為詩，不復成語，故世傳江淹才盡',
    facts: ['典源是南朝梁．鍾嶸《詩品．卷中．齊光祿江淹》｜教育部《成語典》', '江淹年輕時家境貧寒但非常好學，詩文很有名；辭去宣城郡守後，在冶亭睡覺時夢見自稱郭璞的人向他要回一枝五色筆，此後寫詩就沒有好句子｜教育部《成語典》典故說明', '江淹（444～505）字文通，經歷宋、齊、梁三個朝代；郭璞（276～324）是東晉文人｜《梁書．江淹傳》、《晉書．郭璞傳》', '《成語典》辨識：「郎」讀ㄌㄤˊ，是對男子的美稱，不可寫作「朗」｜教育部《成語典》'],
    story: [
      '南北朝的時候，有一個人叫江淹。他小時候家裡很窮，卻非常喜歡讀書。年紀輕輕，他寫的詩和文章就很有名，大家都尊稱他「江郎」。「郎」是古時候對年輕男子的美稱。',
      '江淹的文章寫得又美又動人，很多人都喜歡讀。他也越來越受重用，當了好幾個地方的官。',
      '有一次，江淹辭去宣城郡守的官職，在回家的路上，晚上住在一個叫冶亭的地方。他一個人睡著以後，做了一個奇怪的夢。',
      '夢裡，一位相貌堂堂的男子走過來，說自己是郭璞。郭璞是比江淹早一百多年的東晉文人。那人對江淹說：「我有一枝筆，放在你那裡很多年了，現在可以還給我了吧？」江淹往懷裡一摸，果然摸出一枝閃著五種顏色的筆，就把它交了出去。',
      '從那天起，江淹再寫詩，就怎麼也寫不出好句子了。以前文思像泉水一樣湧出來，現在卻常常寫了又刪、刪了又寫。大家都說：「江郎的才華用完了。」',
      '這個夢只是一個傳說，卻讓人想到：才華不是一枝放在口袋裡、永遠用不完的筆。後來，人們就用「江郎才盡」，比喻一個人的文思枯竭，再也寫不出好作品。'
    ],
    mean: '江淹晚年寫不出好詩文。比喻文人的才思用完了，再也寫不出好作品。',
    usage: ['用在寫作、創作的人才思用盡、寫不出好作品的時候。', '說的是「創作的才思」用完，不是體力、錢或東西用完。', '「郎」是對男子的美稱，讀ㄌㄤˊ，不要寫成「朗」。'],
    misuse: ['「他今天跑完三千公尺，累得江郎才盡，一步都走不動。」✗　江郎才盡說的是寫作、創作的才思用完，不是體力用完。'],
    eg: ['這位作家寫了二十本書，最新一本卻平淡無奇，有人擔心他江郎才盡了。', '我想了一整晚還是寫不出童詩的結尾，覺得自己好像江郎才盡。'],
    syn: ['才思枯竭'], ant: ['思如泉湧', '下筆成章', '妙筆生花'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '夢裡的郭璞向江淹要回什麼東西？', opts: ['一枝五色的筆', '一本自己的詩集', '一塊硯臺', '一件衣服'], a: 0, why: '第四段：江淹「摸出一枝閃著五種顏色的筆，就把它交了出去」。' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '「江郎」的「郎」，是古時候對年輕男子的美稱。', a: true, why: '第一段：「『郎』是古時候對年輕男子的美稱。」' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '江淹把筆還給郭璞以後，發生了什麼變化？', opts: ['寫詩再也寫不出好句子', '當的官變得越來越大', '一下子變得很有錢', '開始喜歡上畫畫'], a: 0, why: '第五段：「江淹再寫詩，就怎麼也寫不出好句子了。」' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '作者最後說「才華不是一枝放在口袋裡、永遠用不完的筆」，想提醒讀者什麼？', opts: ['才華要持續努力，不會永遠都在', '要好好保管筆，不要被人拿走', '夢裡發生的事一定會變成真的', '只有用五色筆才能寫出好詩'], a: 0, why: '把夢的故事和最後一段合起來看：作者說夢只是傳說，真正要提醒的是才華不會自己永遠存在。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '江淹失去五色筆就寫不出好詩，這只是一個傳說。你認為一個人的才華會用完嗎？如果你是江淹，會怎麼讓自己重新寫出好作品？',
        ref: '我覺得才華不會真的用完，但是如果不再讀書、不再觀察生活，就會越寫越差。如果我是江淹，我會先休息一陣子，到各地走走看看，多讀別人的好作品，再把新的感受寫下來。',
        rubric: ['對「才華會不會用完」提出看法', '說出理由', '提出重新找回靈感的具體做法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「江郎才盡」是什麼意思？', opts: ['才思用完，寫不出好作品', '江邊住著一個很有才華的人', '把錢花光，什麼都買不起', '做事很有毅力，不會放棄'], a: 0, why: '比喻文人的才思枯竭，寫不出好作品。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '有一位寫童話很有名的作家，年輕時的作品得過很多獎，每一本都很受歡迎。可是這幾年，他出的新書故事越來越普通，情節也跟以前的書差不多，讀者都說：「好像在看同一本書。」他自己也說，坐在書桌前一整天，常常一個字都寫不出來。', q: '這位作家近幾年的情形，最適合用哪個成語形容？', opts: ['江郎才盡', '投筆從戎', '韋編三絕', '樂不思蜀'], a: 0, why: '以前寫得很好，後來寫不出好作品，就是江郎才盡。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈日記〉今天體育課跑了五圈操場，又練了跳遠，我累得江郎才盡，回家連書包都背不動了。', q: '日記裡的「江郎才盡」用得恰當。', a: false, why: '江郎才盡是寫作的才思用完，不是體力用完。累到走不動，可以說「筋疲力盡」。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '把成語和它跟「江郎才盡」的關係配起來。', pairs: [['才思枯竭', '近義：想法、靈感都用完了'], ['思如泉湧', '反義：想法像泉水一樣不停湧出'], ['投筆從戎', '無關：放下筆去從軍']], why: '《成語典》辨識欄：才思枯竭是近義，思如泉湧是反義。投筆從戎雖然也有「筆」，意思無關。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '寫作文、畫畫或想點子時，你有沒有覺得「腦袋空空、什麼都想不出來」的時候？說說你用什麼方法讓自己重新有靈感，或是以後可以試試什麼方法。',
        ref: '寫作文時我常常想不出開頭。我的方法是先離開書桌走一走，或是把題目相關的事情隨便寫下十個詞，再從裡面挑一個最有感覺的開始寫。平常我也會在小本子上記下有趣的事，需要的時候就拿出來看。',
        rubric: ['說出一次想不出來的經驗', '提出找回靈感的具體方法', '方法說得清楚、做得到'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '這部卡通出到第十季，劇情一直重複，觀眾都說編劇已經＿＿＿＿了。', opts: ['江郎才盡', '投筆從戎', '退避三舍', '韋編三絕'], a: 0, why: '劇情一直重複，寫不出新東西，用江郎才盡。其他三個放進句子都不通。' },
      { id: 'x2', k: 'use', d: 2, type: 'mc', ctx: '〈班刊〉這學期班刊徵稿，小如一口氣交了五篇文章，每一篇都寫得很精采，有詩、有故事，還有訪問稿。總編輯說：「小如真是江郎才盡，太厲害了！」', q: '總編輯用「江郎才盡」恰當嗎？', opts: ['不恰當，小如才思豐富，意思剛好相反', '恰當，因為小如很快就把文章都交完了', '恰當，江郎才盡是稱讚很有才華', '不恰當，因為小如不是男生'], a: 0, why: '江郎才盡是才思用完。小如一口氣寫了五篇好文章，應該說「思如泉湧」。成語是比喻，男生女生都可以用。' }
    ]
  },
  {
    id: 'cy070', lv: 3, word: '不恥下問', zhuyin: 'ㄅㄨˋ ㄔˇ ㄒㄧㄚˋ ㄨㄣˋ', src: '《論語．公冶長》',
    quote: '敏而好學，不恥下問，是以謂之文也',
    facts: ['典源是《論語．公冶長》：子貢問孔子，衛國大夫孔圉（孔文子）為什麼可以得到「文」的諡號｜教育部《成語典》', '孔子回答：孔圉聰明又好學，向地位比自己低的人請教也不覺得羞恥｜教育部《成語典》典故說明', '《成語典》辨識：「恥」音ㄔˇ，是羞恥，不可寫作「齒」｜教育部《成語典》'],
    story: [
      '春秋時代，衛國有一位大夫叫孔圉。古時候，有地位的人去世以後，國家會依照他一生的表現，給他一個稱號，叫做「諡號」。孔圉去世後，得到的諡號是「文」，所以大家叫他「孔文子」。',
      '「文」是一個很好的諡號，代表這個人很有學問、很有修養。孔子的學生子貢聽了，心裡不太服氣。他覺得孔圉這個人有些地方做得並不好，怎麼配得上這麼好的稱號呢？',
      '子貢就去問老師：「孔文子憑什麼可以得到『文』這個諡號？」',
      '孔子想了想，回答：「他很聰明，又很喜歡學習；遇到不懂的事，就算要向地位比他低、學問比他淺的人請教，他也不覺得丟臉。所以，給他『文』這個諡號，是有道理的。」',
      '孔子的意思是：一個人有缺點，不代表他沒有值得學習的地方。孔圉身為大夫，地位很高，卻願意放下身段，向身邊任何一個懂的人請教，這是很不容易做到的事。',
      '這段對話記在《論語．公冶長》裡。後來，人們就用「不恥下問」，形容一個人虛心求教，不會因為對方的年紀、身分或學問比自己低，就覺得請教是羞恥的事。'
    ],
    mean: '不把向身分比自己低、學問比自己淺的人請教當作羞恥。形容人虛心好學。',
    usage: ['用在稱讚人願意向年紀、身分或學問比自己低的人請教（褒義）。', '向老師、專家等比自己懂很多的人請教，是本來就應該的，不是「下問」，不能說不恥下問。', '「恥」是羞恥的意思，不要寫成「齒」。'],
    misuse: ['「我數學不會，就去問數學老師，我真是不恥下問。」✗　向老師請教不是「下問」；不恥下問要用在問身分或學問比自己低的人。'],
    eg: ['校長遇到不會用的平板功能，就去問五年級的資訊小老師，這種不恥下問的態度讓大家很佩服。', '舅舅是工程師，卻常常不恥下問，向讀國中的表哥請教新遊戲怎麼玩。'],
    syn: ['虛懷若谷'], ant: ['師心自用'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '孔圉去世後得到的諡號是什麼？', opts: ['文', '武', '仁', '孝'], a: 0, why: '第一段：「得到的諡號是『文』。」' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '子貢為什麼去問孔子這個問題？', opts: ['他覺得孔圉配不上這麼好的諡號', '他想替孔圉另外取一個好聽的名字', '他不知道「文」這個字怎麼寫', '他想跟孔圉學習寫文章'], a: 0, why: '第二段：子貢「心裡不太服氣」，覺得孔圉「怎麼配得上這麼好的稱號」。' },
      { id: 'r3', p: 2, d: 2, type: 'tf', q: '從孔子的回答可以知道，孔子認為一個人只要有缺點，就不值得學習。', a: false, why: '第五段：孔子的意思是「一個人有缺點，不代表他沒有值得學習的地方」。' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '孔圉「不恥下問」為什麼特別難得？', opts: ['地位很高，卻肯向地位低的人請教', '他每天都會問好多好多不同的問題', '他只肯向孔子一個人請教', '他問問題的聲音特別小聲'], a: 0, why: '第五段：「孔圉身為大夫，地位很高，卻願意放下身段……這是很不容易做到的事。」' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '你覺得向年紀比你小、或成績沒有你好的同學請教，是一件容易的事嗎？為什麼？請用孔子對孔圉的評價，說明你的想法。',
        ref: '我覺得不容易，因為會怕別人覺得「你怎麼連這個都不會」。可是孔子說孔圉肯向地位低的人請教，所以值得「文」這個好名字。每個人都有比別人厲害的地方，像我們班的小安成績普通，但很會修東西，向他請教一點都不丟臉。',
        rubric: ['表明容易或不容易，並說出原因', '引用孔子對孔圉的評價', '舉出一個生活中的例子'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「不恥下問」的「恥」是什麼意思？', opts: ['羞恥', '牙齒', '停止', '記住'], a: 0, why: '「恥」是羞恥，「不恥」就是不覺得丟臉。不要寫成「齒」。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '科展快到了，六年級的阿凱負責做機器人，可是程式一直寫不出來。他聽說四年級的小學弟在程式社學過，雖然有點不好意思，還是主動去問：「學弟，這一段要怎麼寫，可以教我嗎？」學弟熱心的教他，兩人一起把機器人完成了，還拿到了佳作。', q: '阿凱的做法，最適合用哪個成語形容？', opts: ['不恥下問', '班門弄斧', '江郎才盡', '退避三舍'], a: 0, why: '六年級的阿凱願意向四年級的學弟請教，不覺得丟臉，就是不恥下問。' },
      { id: 'p3', k: 'use', d: 2, type: 'mc', ctx: '〈聯絡簿〉今天上自然課時，我有一個實驗步驟不懂，下課就去辦公室請教自然老師。老師很仔細的教我，我覺得自己真是不恥下問！', q: '這段聯絡簿用「不恥下問」恰當嗎？', opts: ['不恰當，老師比自己懂，不是「下問」', '恰當，因為作者主動去請教別人', '恰當，因為作者問的是自然問題', '不恰當，因為請教老師是羞恥的事'], a: 0, why: '不恥下問是向身分或學問比自己低的人請教。請教老師是應該的，不是「下問」。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '把成語和它跟「不恥下問」的關係配起來。', pairs: [['虛懷若谷', '近義：心胸像山谷一樣能容納'], ['師心自用', '反義：只相信自己，不聽別人'], ['江郎才盡', '無關：才思用完寫不出好作品']], why: '《成語典》辨識欄：虛懷若谷是近義，師心自用是反義。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '孔圉身分很高，還願意向比他低的人請教。想一想，在班上或家裡，有誰在某件事上懂得比你多，雖然他年紀比你小或平常不起眼？你想向他請教什麼？會怎麼開口？',
        ref: '我的弟弟才二年級，可是他很會折紙飛機，折出來的飛得又高又遠。我想向他請教怎麼折，我會說：「你的飛機飛得好遠，可以教我嗎？」學會以後也要謝謝他。',
        rubric: ['說出一個在某方面比自己懂的人', '說出想請教的具體內容', '寫出一句有禮貌的請教說法'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '經理遇到不會操作的新軟體，就去請教剛進公司的實習生，這種＿＿＿＿的態度值得學習。', opts: ['不恥下問', '江郎才盡', '樂不思蜀', '邯鄲學步'], a: 0, why: '經理向身分比自己低的實習生請教，用不恥下問。其他三個放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 2, type: 'mc', ctx: '社區要辦植物展，退休的林爺爺種了幾十年的花，卻對新品種的多肉植物不太熟悉。他看到隔壁讀小學的小芬把多肉植物照顧得很好，就拿著筆記本去問她：「這種要多久澆一次水？」小芬一一回答，林爺爺都認真記下來。', q: '林爺爺的做法，最適合用哪一個成語形容？', opts: ['不恥下問', '班門弄斧', '韋編三絕', '負荊請罪'], a: 0, why: '林爺爺年紀大、經驗多，卻願意向小學生請教，是不恥下問。' }
    ]
  },
  {
    id: 'cy073', lv: 3, word: '狡兔三窟', zhuyin: 'ㄐㄧㄠˇ ㄊㄨˋ ㄙㄢ ㄎㄨ', src: '《戰國策．齊策四》',
    quote: '狡兔有三窟，僅得免其死耳',
    facts: ['典源是《戰國策．齊策四》：齊國孟嘗君的門客馮諼替他做準備｜教育部《成語典》', '馮諼到薛地收債，把債券全部燒掉，替孟嘗君「買」回百姓的感恩；孟嘗君失勢回到薛地時，百姓出來迎接｜教育部《成語典》典故說明', '馮諼讓梁國的國君派人聘請孟嘗君，使齊王重新任用他，又建議在薛地立宗廟，最後說「三窟已成」｜教育部《成語典》典故說明', '《成語典》使用類別：用在「多處居所」「狡猾詭詐」的表述上｜教育部《成語典》用法說明'],
    story: [
      '戰國時代，齊國有一位很有名的貴族叫孟嘗君，家裡養了好幾千個門客，也就是投靠他、替他出主意或辦事的人。其中有一個人叫馮諼，剛來的時候看起來沒什麼本事，還常常抱怨飯菜不好、出門沒車坐。',
      '有一次，孟嘗君要派人到他的封地薛去收債。馮諼自告奮勇說：「我去！」他問孟嘗君：「收完了錢，要買什麼回來？」孟嘗君說：「你看我家缺什麼，就買什麼吧。」',
      '馮諼到了薛地，把欠錢的百姓都找來，核對完借據以後，竟然當著大家的面，把借據全部燒掉，說：「孟嘗君說，這些錢都不用還了！」百姓高興得歡呼起來。回去以後，馮諼對孟嘗君說：「您家什麼都不缺，只缺『義』，我就替您把『義』買回來了。」孟嘗君聽了很不高興。',
      '過了一年，齊王不再重用孟嘗君，他只好回到薛地。沒想到，離薛地還有一百里，百姓就扶老攜幼出來迎接他。孟嘗君這才明白，對馮諼說：「先生替我買的『義』，我今天終於看到了。」',
      '馮諼說：「狡猾的兔子要有三個洞，才能保住性命。您現在只有一個洞，還不能安心睡覺，讓我再替您挖兩個洞吧！」',
      '於是，馮諼到梁國去，說服梁國的國君派人帶著很多黃金和車子，來請孟嘗君去當官。齊王聽說了很緊張，趕快請孟嘗君回來當宰相。馮諼又建議孟嘗君請齊王在薛地蓋齊國先王的宗廟，讓薛地更安全。一切都安排好了，馮諼才說：「三個洞已經挖好了，您可以安心了。」',
      '後來，人們用「狡兔三窟」比喻為了躲避災禍，事先準備好幾個藏身的地方或退路。'
    ],
    mean: '狡猾的兔子有三個洞穴。比喻為了躲避災禍，事先準備好幾個藏身的地方或好幾條退路。',
    usage: ['形容為了躲避危險，準備好幾個藏身處或退路。', '常帶有「狡猾、詭詐」的意思（例如歹徒有好幾個藏身處）；稱讚人「做事周全、多做準備」時，用「未雨綢繆」比較恰當。'],
    misuse: ['「小明考試前把每一科都準備好了，真是狡兔三窟。」✗　把每一科準備好，不是準備藏身的地方或躲避災禍的退路；狡兔三窟又常帶有狡猾的意味，用在這裡不恰當。'],
    eg: ['警察發現這名嫌犯狡兔三窟，在三個地方都租了房子，花了好幾天才找到他。', '那隻流浪貓狡兔三窟，在公園裡有好幾個躲雨的角落，誰都抓不到牠。'],
    syn: [], ant: ['走投無路'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '馮諼到薛地收債，最後怎麼處理那些借據？', opts: ['當著百姓的面全部燒掉', '原封不動帶回去交給孟嘗君', '一張一張仔細收好', '送給梁國的國君'], a: 0, why: '第三段：「當著大家的面，把借據全部燒掉。」' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '孟嘗君一開始聽說馮諼燒了借據，覺得很高興。', a: false, why: '第三段最後：「孟嘗君聽了很不高興。」他是一年後才明白馮諼的用意。' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '馮諼說替孟嘗君「把『義』買回來了」，是什麼意思？', opts: ['讓百姓感念孟嘗君的恩情', '用錢買了一個叫「義」的寶物', '替孟嘗君買了很多糧食', '教百姓學會一個新的字'], a: 0, why: '燒掉借據，百姓不用還錢，就感念孟嘗君；第四段百姓出來迎接他，就是這份「義」的回報。' },
      { id: 'r4', p: 3, d: 3, type: 'order', q: '把馮諼替孟嘗君準備「三個洞」的事情，照發生順序排好。', items: ['在薛地燒掉借據，讓百姓感恩', '說服梁國派人來聘請孟嘗君', '齊王趕快請孟嘗君回來當宰相', '在薛地蓋先王的宗廟'], why: '第三段燒借據（第一個洞），第六段先讓梁國來請、齊王才緊張的請他回去（第二個洞），最後在薛地蓋宗廟（第三個洞）。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '馮諼一開始被大家看不起，最後卻替孟嘗君想得最周到。你覺得從這個故事，可以學到怎麼看待身邊「看起來沒什麼本事」的人？請用故事內容說明。',
        ref: '不能只看一個人剛開始的樣子就看不起他。馮諼剛來時常常抱怨，好像沒什麼本事，可是他燒借據、去梁國、蓋宗廟，每一步都想得很遠。所以要給別人表現的機會，多了解他擅長什麼。',
        rubric: ['提出對「看起來沒本事的人」的看法', '引用馮諼前後的表現當證據', '說出自己可以怎麼做'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「狡兔三窟」的「窟」是什麼意思？', opts: ['洞穴', '哭泣', '跑步', '窗戶'], a: 0, why: '「窟」是洞穴，「三窟」就是三個洞。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '〈社會新聞〉警方追查一名詐騙集團的主謀，發現他在臺北、臺中、高雄都租了房子，每隔幾天就換一個地方住，還準備了好幾支手機輪流使用。警方花了三個月，才在其中一間房子裡找到他，並查出他騙了很多人的錢。', q: '這名主謀的做法，最適合用哪個成語形容？', opts: ['狡兔三窟', '不恥下問', '樂不思蜀', '投筆從戎'], a: 0, why: '準備好幾個藏身的地方，讓人很難找到，就是狡兔三窟。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈作文〉我的好朋友小安非常誠實，答應別人的事一定做到，從來不說謊，大家都很信任他。他真是一個狡兔三窟的好人！', q: '作文裡的「狡兔三窟」用得恰當。', a: false, why: '狡兔三窟是準備好幾個藏身處，常帶有狡猾的意思，不能用來稱讚人誠實。' },
      { id: 'p4', k: 'judge', d: 2, type: 'tf', q: '「那隻野貓在車底、花叢和舊倉庫都有藏身的地方，一有人靠近就換地方躲，真是狡兔三窟。」這句話的「狡兔三窟」用得恰當。', a: true, why: '有好幾個藏身的地方，用來躲避危險，用得恰當。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '馮諼提醒孟嘗君：只有一個洞不夠安全。想一想，做一件重要的事時（例如參加戶外活動、交報告），如果原本的計畫出問題，你會準備什麼「備用方案」？請舉一個例子說明。',
        ref: '交電腦做的報告時，我怕檔案打不開，所以會存在隨身碟裡，也寄一份到自己的信箱，再印一份紙本。這樣就算其中一個出問題，還有別的可以用，不會手忙腳亂。',
        rubric: ['說出一件重要的事', '提出至少一個具體的備用方案', '說明備用方案怎麼幫自己避免麻煩'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 1, type: 'mc', q: '這個小偷＿＿＿＿，在好幾個城市都有落腳的地方，警察追了很久才抓到他。', opts: ['狡兔三窟', '不恥下問', '韋編三絕', '如魚得水'], a: 0, why: '有好幾個藏身處，用狡兔三窟。其他三個放進句子都不通。' },
      { id: 'x3', k: 'use', d: 2, type: 'tf', ctx: '〈作文〉我家養的小白兔跑得好快，一眨眼就從客廳衝到陽臺，又從陽臺跳回沙發上，全家人都追不上牠，真是狡兔三窟！', q: '作文裡的「狡兔三窟」用得恰當。', a: false, why: '狡兔三窟是比喻準備好幾個藏身的地方或退路，不是形容兔子跑得快。小白兔只是在家裡跑來跑去，並沒有準備藏身處。' }
    ]
  },
  // ==================== L4 分辨用法 ====================
  {
    id: 'cy077', lv: 4, word: '美輪美奐', zhuyin: 'ㄇㄟˇ ㄌㄨㄣˊ ㄇㄟˇ ㄏㄨㄢˋ', src: '《禮記．檀弓下》',
    quote: '美哉輪焉，美哉奐焉',
    facts: ['典源是《禮記．檀弓下》：晉國趙武（趙文子）的新房子落成，晉國的大夫們去祝賀｜教育部《成語典》', '張老表面上稱讚房子高大華美，實際上是提醒趙武不要太奢華，要適可而止｜教育部《成語典》典故說明', '釋義是形容房屋規模高大、裝飾華美；「奐」是文采鮮明的樣子｜教育部《成語典》', '「輪」是高大的樣子｜《禮記．檀弓下》鄭玄注', '《成語典》辨識：「奐」音ㄏㄨㄢˋ，不可寫作「煥」｜教育部《成語典》'],
    story: [
      '春秋時代，晉國有一位大臣叫趙武，大家稱他「趙文子」。有一年，他的新房子蓋好了，晉國的大夫們都帶著禮物，到他家去祝賀。',
      '大家走進新家，抬頭一看：屋子又高又大，梁柱上雕著精細的花紋，顏色鮮豔明亮。有一位大夫叫張老，他看了看，開口說：「真美啊，這麼高大！真美啊，這麼鮮明亮麗！」',
      '張老接著說：「在這裡，可以舉行祭祀、唱歌奏樂；在這裡，也可以辦喪事、哭泣送別；在這裡，還可以招待賓客、讓全族的人聚在一起。」這些話聽起來，好像只是在稱讚房子很好用。',
      '可是聰明的趙武聽出來了。張老表面上誇房子漂亮，其實是在提醒他：房子蓋得這麼豪華，要記得用在正當的事情上，不要太奢侈、太炫耀，適可而止就好。',
      '趙武馬上回答：「我能在這裡祭祀祖先、和族人相聚，平平安安過完一生，就心滿意足了。」說完，他朝北方恭敬的拜了兩拜，表示接受張老的提醒。當時的人都稱讚：張老很會說話，趙武也很懂得聽話。',
      '張老說的「美哉輪焉，美哉奐焉」，「輪」是高大的樣子，「奐」是色彩鮮明的樣子。後來，人們就把它變成「美輪美奐」，用來形容房屋建築高大又華美，也常用在祝賀別人新家落成。',
      '要特別注意：依照《成語典》的解釋，「美輪美奐」形容的是房屋。有人用它稱讚煙火、晚霞、衣服或一桌菜，就用錯了地方；形容風景可以說「美不勝收」。另外，「奐」不要寫成「煥然一新」的「煥」。'
    ],
    mean: '形容房屋建築又高大、又裝飾得很華美。',
    usage: ['用來形容房子、建築物（例如新落成的大樓、廟宇、美術館）高大華美。', '依照《成語典》的釋義，它形容的是「房屋」；風景、煙火、衣服、食物不要用美輪美奐。', '也常用在祝賀別人新家落成的賀詞。', '「奐」音ㄏㄨㄢˋ，不可寫作「煥」。'],
    misuse: ['「跨年煙火在夜空中綻放，真是美輪美奐。」✗　美輪美奐形容的是房屋建築；煙火、風景可以說「美不勝收」。', '「新的體育館外觀美輪美煥。」✗　「奐」不可寫作「煥」。'],
    eg: ['新落成的市立圖書館美輪美奐，挑高的大廳裡擺滿了書。', '這座老廟經過整修，雕梁畫棟，美輪美奐，吸引很多遊客來參觀。'],
    syn: ['富麗堂皇'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '晉國的大夫們為什麼到趙武家去？', opts: ['祝賀他的新房子蓋好了', '參加他家裡辦的生日宴會', '請他幫忙蓋房子', '跟他討論國家大事'], a: 0, why: '第一段：「他的新房子蓋好了，晉國的大夫們都帶著禮物，到他家去祝賀。」' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '張老說「在這裡可以祭祀、辦喪事、招待賓客」，其實是想提醒趙武什麼？', opts: ['房子要用在正當的事，不要太奢侈', '房子太小了，應該再蓋大一點', '趕快在新家辦一場熱鬧的宴會', '新房子的顏色太鮮豔，不好看'], a: 0, why: '第四段：張老是在提醒他「要記得用在正當的事情上，不要太奢侈、太炫耀」。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '從趙武的回答和「拜了兩拜」，可以看出他是怎樣的人？', opts: ['聽得懂別人的提醒，也虛心接受', '很愛炫耀，聽不進別人的意見', '很生氣，覺得張老在找麻煩', '只在意房子漂亮不漂亮'], a: 0, why: '第五段：趙武馬上回答、恭敬下拜，「表示接受張老的提醒」，大家稱讚他「很懂得聽話」。' },
      { id: 'r4', p: 3, d: 3, type: 'tf', q: '依照文章最後一段，用「美輪美奐」稱讚一片美麗的晚霞，是正確的用法。', a: false, why: '最後一段：美輪美奐形容的是房屋，晚霞、煙火要說「美不勝收」。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '張老沒有直接說「你的房子太豪華了」，而是用稱讚的方式提醒趙武。你覺得這種提醒別人的方法好不好？在生活中，你會怎麼委婉的提醒朋友？',
        ref: '我覺得很好，因為趙武是在辦喜事，直接批評會讓他很沒面子。先稱讚再提醒，他比較聽得進去。如果我的朋友上課常常講話，我會先說「你講的東西都很有趣」，再說「可以下課再告訴我嗎？我怕聽不到老師講」。',
        rubric: ['對委婉提醒的方法提出看法並說明理由', '能用故事中張老和趙武的反應當證據', '舉出一個自己委婉提醒朋友的說法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「美輪美奐」的「奐」是什麼意思？', opts: ['色彩鮮明', '交換東西', '大聲呼喚', '光線昏暗'], a: 0, why: '「奐」是文采鮮明的樣子；「輪」是高大的樣子。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '鎮上新蓋了一座兒童美術館。外牆用彩色玻璃拼成一道彩虹，挑高的大廳有三層樓高，天花板垂下一隻巨大的紙鶴。走進去，木頭樓梯一圈圈往上繞，每個角落都布置得很用心。來參觀的人都忍不住拿出相機，在門口拍了好多照片。', q: '這座美術館的建築，最適合用哪個成語形容？', opts: ['美輪美奐', '狡兔三窟', '入木三分', '如魚得水'], a: 0, why: '建築物又高大又裝飾華美，正是美輪美奐。' },
      { id: 'p3', k: 'judge', d: 2, type: 'tf', q: '「表姊穿上新買的洋裝，看起來美輪美奐。」這句話的「美輪美奐」用得恰當。', a: false, why: '美輪美奐形容房屋建築，不能用來形容人或衣服。' },
      { id: 'p4', k: 'use', d: 3, type: 'mc', ctx: '〈校外教學心得〉我們到海邊看日落，天空從橘色變成粉紅色，再變成紫色，海面閃閃發光。這片晚霞真是美輪美奐，我一輩子都忘不了。', q: '這篇心得用「美輪美奐」恰當嗎？', opts: ['不恰當，它形容建築，晚霞要說美不勝收', '恰當，因為晚霞的顏色非常鮮豔', '恰當，美輪美奐可以形容所有美的事物', '不恰當，因為日落的時間太短了'], a: 0, why: '依照《成語典》，美輪美奐形容的是房屋建築。晚霞、風景很美，可以說「美不勝收」。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '張老用稱讚提醒趙武「不要太奢侈」。如果要布置你自己的房間，你會怎麼做，才能讓房間好看又不浪費？請說出兩個具體的做法。',
        ref: '第一，我會用自己畫的畫和全家出遊的照片貼在牆上，不用買很貴的裝飾品。第二，舊的鞋盒包上包裝紙，就能變成收納盒，房間整齊又好看。這樣不用花很多錢，也很有自己的風格。',
        rubric: ['提出兩個具體的布置做法', '做法有考慮到不浪費', '說明這樣做為什麼好看又實用'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '這棟百年老戲院整修完成，外觀雕花精緻、內部金碧輝煌，可說是＿＿＿＿。', opts: ['美輪美奐', '狡兔三窟', '江郎才盡', '負荊請罪'], a: 0, why: '形容建築華美，用美輪美奐。其他三個放進句子都不通。' },
      { id: 'x2', k: 'use', d: 3, type: 'tf', ctx: '〈美食專欄〉這家餐廳的料理擺盤非常講究，每一道菜都像一幅畫，色彩繽紛，真是美輪美奐，讓人捨不得動筷子。', q: '專欄用「美輪美奐」形容菜的擺盤，是恰當的。', a: false, why: '美輪美奐形容的是房屋建築，不能用來形容食物的擺盤。' }
    ]
  },
  {
    id: 'cy080', lv: 4, word: '始作俑者', zhuyin: 'ㄕˇ ㄗㄨㄛˋ ㄩㄥˇ ㄓㄜˇ', src: '《孟子．梁惠王上》',
    quote: '始作俑者，其無後乎',
    facts: ['典源是《孟子．梁惠王上》：孟子向梁惠王談治理國家時，引用孔子的話｜教育部《成語典》', '「俑」是古代陪葬用的木頭或陶土人偶；孔子認為用像人的俑陪葬，在心意上和用真人陪葬差不多，所以痛批最早這樣做的人｜教育部《成語典》典故說明', '孟子說：國君的廚房有肥肉、馬廄有肥馬，百姓卻在挨餓，這比做俑更嚴重｜教育部《成語典》典故說明', '原指最初製作人俑陪葬的人，後來比喻首創惡例的人｜教育部《成語典》釋義'],
    story: [
      '在很久很久以前，有些貴族去世以後，會讓活人跟著陪葬，這是非常殘忍的習俗。後來，人們改用木頭或陶土做成人的樣子，放進墳墓裡代替真人，這種人偶就叫做「俑」。',
      '用人偶代替真人，聽起來好像進步了。可是孔子卻很不以為然。他說：「第一個做俑來陪葬的人，大概會沒有後代吧！」這是一句很重的話。',
      '為什麼孔子這麼生氣呢？因為俑做得跟人一模一樣，用它陪葬，表示心裡還是把「人」當成陪葬品。孔子在意的不只是做法，更是背後那顆不尊重人的心。',
      '到了戰國時代，孟子去見梁國的國君梁惠王。梁惠王說：「我願意聽您的教導。」孟子問他：「害人用的是棍子還是刀子，結果有不一樣嗎？」梁惠王說：「沒有不一樣。」孟子又問：「那用刀子害人，和用不好的政治害人，有不一樣嗎？」梁惠王也說：「沒有不一樣。」',
      '孟子接著說：「現在大王的廚房裡有肥肉，馬廄裡有肥壯的馬，百姓卻餓得面黃肌瘦。孔子連做人偶陪葬都要批評，因為它太像人了；那讓真正的百姓受苦挨餓，又該怎麼說呢？」孟子是要梁惠王明白：當國君的人，一定要把百姓放在心上。',
      '後來，「始作俑者」的意思慢慢變了，用來比喻「第一個開了壞頭、帶頭做壞事的人」。',
      '要特別注意，它只能用在不好的事情上。如果有人第一個想出好點子、帶動好風氣，例如帶頭做資源回收，不能說他是「始作俑者」，可以說他是「發起人」或「帶頭的人」。'
    ],
    mean: '本來指第一個做人偶來陪葬的人。後來比喻第一個開壞頭、首創壞例子的人。',
    usage: ['用來指責第一個帶頭做壞事、開了不好風氣的人（貶義）。', '只能用在壞事；第一個帶頭做好事的人，要說「發起人」「先驅」或「帶頭的人」。'],
    misuse: ['「小美是我們班資源回收的始作俑者，在她的帶動下，大家都會做分類了。」✗　資源回收是好事；始作俑者只能指開壞頭的人。', '「這場園遊會辦得很成功，始作俑者就是熱心的家長會長。」✗　把辦活動成功的功臣說成「始作俑者」，反而變成在罵人。'],
    eg: ['上課偷傳紙條的風氣，始作俑者是後排的兩位同學，後來全班都跟著傳。', '網路上那則假消息的始作俑者，已經被查出來了。'],
    syn: ['罪魁禍首'], ant: [],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '「俑」是什麼？', opts: ['陪葬用的人偶', '古代的兵器', '吃飯用的碗', '孔子的學生'], a: 0, why: '第一段：「用木頭或陶土做成人的樣子……這種人偶就叫做『俑』。」' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '孔子為什麼連用人偶陪葬都要批評？', opts: ['人偶像人，表示心裡仍不尊重人', '人偶做得太醜，看起來不好看', '做人偶要花很多很多錢', '人偶放在墳墓裡會壞掉'], a: 0, why: '第三段：用像人的俑陪葬，「表示心裡還是把『人』當成陪葬品」，孔子在意的是背後的心。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '孟子跟梁惠王提到孔子批評做俑的人，是想勸梁惠王什麼？', opts: ['要照顧百姓，不要讓百姓挨餓', '以後再也不要用人偶來陪葬了', '要多養一些肥壯的馬', '要多讀孔子說過的話'], a: 0, why: '第五段：孔子連做俑都批評，讓百姓挨餓更不應該；孟子要梁惠王「把百姓放在心上」。' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '「始作俑者」從古到今，意思有什麼變化？', opts: ['從「第一個做俑的人」變成「開壞頭的人」', '從「開壞頭的人」變成「第一個做俑的人」', '從「會做人偶的工匠」變成「藝術家」', '古今都是指「做陶土的工人」'], a: 0, why: '第六段：原本指第一個做俑的人，後來比喻「第一個開了壞頭、帶頭做壞事的人」。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '孔子在意的不只是「用什麼陪葬」，更是背後的心意。你同意「做法看起來進步了，但心意沒有變，還是不對」這個想法嗎？請說明理由，並舉一個生活中的例子。',
        ref: '我同意。像有人不再當面罵同學，改成在群組裡偷偷取笑他，做法看起來比較「客氣」，可是不尊重人的心還在，對方一樣會受傷。所以重要的是真心改變想法，而不是只換一種方式。',
        rubric: ['表明同意或不同意並說出理由', '能連結到故事中孔子批評做俑的原因', '舉出一個生活中的例子'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '今天說一個人是「始作俑者」，是在說他怎麼樣？', opts: ['第一個開壞頭的人', '很會做人偶的人', '第一個做好事的人', '最後才加入的人'], a: 0, why: '今天的始作俑者，比喻首創惡例、開了壞頭的人。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '學期初，阿南把教室後面的掃具亂丟，沒有放回櫃子。接著，其他同學看他這樣，也開始把掃把、拖把隨手一丟。到了月底，教室後面亂成一團，整潔比賽還被扣了分。大家回想起來，發現最早這樣做的就是阿南。', q: '在這件事裡，阿南可以用哪個成語形容？', opts: ['始作俑者', '不恥下問', '狡兔三窟', '投筆從戎'], a: 0, why: '阿南第一個亂丟掃具，開了壞頭，大家跟著學，所以他是始作俑者。' },
      { id: 'p3', k: 'judge', d: 2, type: 'tf', q: '「早上在校門口跟大家說『早安』的好習慣，始作俑者是我們的校長。」這句話的「始作俑者」用得恰當。', a: false, why: '說早安是好習慣，始作俑者只能用在壞事上；可以說校長是「帶頭的人」。' },
      { id: 'p4', k: 'use', d: 3, type: 'mc', ctx: '〈校刊報導〉全校「每日一善」活動越來越熱烈，大家互相幫忙、主動撿垃圾。這個好活動的始作俑者，是六年一班的班長，她在上學期第一個提出這個想法。', q: '這篇報導用「始作俑者」恰當嗎？', opts: ['不恰當，這是好活動，應該說發起人', '恰當，因為班長是第一個提出想法的人', '恰當，因為始作俑者就是第一個的意思', '不恰當，因為這個活動不需要做人偶'], a: 0, why: '始作俑者是首創「惡例」的人，用在好活動上會變成罵人。應該說「發起人」。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '「始作俑者」提醒我們：一個不好的開頭，可能會讓很多人跟著學。想一想，你的班上或家裡有沒有一個「不好的開頭」正在慢慢擴散？你可以怎麼做，讓它停下來，或帶頭開一個好的開頭？',
        ref: '我們班有人開始在午休時偷玩手機遊戲，後來越來越多人跟著玩。我可以先做到自己不玩，也可以在班會提出「午休手機放講臺盒子」的辦法，讓大家一起遵守，帶頭開一個好的開頭。',
        rubric: ['說出一個正在擴散的不好習慣', '提出讓它停下來的具體做法', '說明自己可以怎麼帶頭做好的示範'] }
    ],
    xq: [
      { id: 'x1', k: 'sit', d: 2, type: 'mc', ctx: '一開始，只有一位同學在班級群組裡用難聽的綽號叫別人，其他人覺得好玩，也跟著一起叫。後來被叫綽號的同學越來越多，大家常常吵架，班上的氣氛變得很糟。導師找全班討論，才知道這件事是從那位同學開始的。', q: '最早用難聽綽號叫人的那位同學，可以用哪一個成語形容？', opts: ['始作俑者', '不恥下問', '美輪美奐', '如魚得水'], a: 0, why: '他第一個開了用難聽綽號叫人的壞頭，是始作俑者。' },
      { id: 'x2', k: 'use', d: 3, type: 'tf', ctx: '〈新聞短評〉這座城市的「無塑膠袋市場」，現在已經擴大到二十個市場。當初的始作俑者是一位賣菜的阿姨，她第一個請客人自己帶菜籃來買菜。', q: '短評用「始作俑者」稱呼那位阿姨，是恰當的。', a: false, why: '減少塑膠袋是好事，阿姨是值得稱讚的發起人，不能用只指開壞頭的始作俑者。' }
    ]
  },
  {
    id: 'cy084', lv: 4, word: '一傅眾咻', zhuyin: 'ㄧ ㄈㄨˋ ㄓㄨㄥˋ ㄒㄧㄡ', src: '《孟子．滕文公下》',
    quote: '一齊人傅之，眾楚人咻之',
    facts: ['典源是《孟子．滕文公下》：孟子和宋國大夫戴不勝談怎麼讓國君變好｜教育部《成語典》', '孟子用楚國大夫要兒子學齊國話來比喻：一個齊國人教，很多楚國人在旁邊吵，就算天天督促也學不會｜教育部《成語典》典故說明', '「傅」是教導，「咻」是喧擾；比喻學習受干擾難有成效，後來也比喻寡不敵眾｜教育部《成語典》釋義', '《成語典》注音以「ㄧ」為本音，另列變調讀法「ㄧˊ」｜教育部《成語典》'],
    story: [
      '戰國時代，孟子到宋國去。宋國有一位大夫叫戴不勝，他很希望宋國的國君能變成一位好國君。',
      '孟子問他：「假如楚國有一位大夫，想讓兒子學會說齊國話，你覺得應該請齊國人來教，還是請楚國人來教？」戴不勝說：「當然是請齊國人來教。」',
      '孟子說：「好。可是如果只請一個齊國人來教他，旁邊卻圍著一大群楚國人，整天用楚國話跟他說話、在他身邊吵吵鬧鬧，那就算天天督促他，甚至處罰他，他也學不好齊國話。」',
      '「相反的，如果把這個孩子帶到齊國都城熱鬧的街坊，讓他在那裡住上幾年，每天聽到的、說的都是齊國話，那時候就算天天要他說楚國話，他也說不回來了。」',
      '說完這個比方，孟子才說出真正想講的話：「你說薛居州是一位好人，所以安排他在國君身邊。可是，如果國君身邊不論老的、少的、地位高的、地位低的，都是好人，國君想做壞事，又能跟誰一起做呢？如果身邊都不是好人，國君又能跟誰一起做好事呢？只有一個薛居州，又能有多大的影響呢？」',
      '孟子的意思是：環境對一個人的影響非常大。一個好老師的聲音，敵不過一大群人的吵鬧。後來，人們就從「一齊人傅之，眾楚人咻之」這句話，濃縮出「一傅眾咻」，比喻學習時受到很多干擾，很難有成效；也用來比喻一個人的力量太小，敵不過眾人。',
      '「傅」是教導，「咻」是吵鬧、喧嘩，念作ㄒㄧㄡ。要注意，「一傅眾咻」的重點是「很多人在旁邊吵、干擾」，不是「一個老師教很多學生」。'
    ],
    mean: '一個人教，很多人在旁邊吵。比喻學習受到干擾，很難有成效；也比喻勢單力薄，敵不過眾人。',
    usage: ['用在學習時周圍干擾太多，怎麼教、怎麼學都難有效果的時候。', '也可以比喻一個人的意見或力量太小，敵不過一大群人（寡不敵眾）。', '「眾咻」是很多人吵鬧干擾，不是「很多學生在聽課」。'],
    misuse: ['「王老師一個人要教三十個學生，真是一傅眾咻。」✗　「眾咻」是眾人吵鬧干擾，不是學生人數多；只是學生多，不能用一傅眾咻。'],
    eg: ['弟弟在客廳寫功課，旁邊電視開著、表哥們又在玩遊戲，一傅眾咻，寫了一個小時還沒寫完。', '只有他一個人主張保持安靜，其他人都在大聲聊天，一傅眾咻，說了也沒人聽。'],
    syn: [], ant: ['近朱者赤', '蓬生麻中'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '孟子舉的例子裡，楚國大夫想讓兒子學什麼？', opts: ['說齊國話', '寫楚國字', '射箭騎馬', '彈琴唱歌'], a: 0, why: '第二段：「想讓兒子學會說齊國話。」' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '孟子說「只請一個齊國人來教，旁邊卻圍著一大群楚國人」會怎樣？', opts: ['再怎麼督促，也學不好齊國話', '很快就能把齊國話說得很好', '齊國話和楚國話都學得很好', '楚國人也會跟著學會齊國話'], a: 0, why: '第三段：「那就算天天督促他，甚至處罰他，他也學不好齊國話。」' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '孟子講學說話的例子，和薛居州有什麼關係？', opts: ['身邊只有一個好人，就像只有一個老師', '薛居州是很會教齊國話的一位老師', '薛居州就是那位楚國大夫的兒子', '國君想要學齊國話，才請薛居州'], a: 0, why: '第五段：國君身邊只有薛居州一個好人，其他人都不好，就像一個齊國老師敵不過一群吵鬧的楚國人。' },
      { id: 'r4', p: 3, d: 3, type: 'tf', q: '依照文章，「一傅眾咻」可以用來形容「一位老師教很多學生」。', a: false, why: '最後一段：重點是「很多人在旁邊吵、干擾」，不是一個老師教很多學生。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '孟子認為「環境」對學習影響很大。你同意嗎？還是你覺得「自己努力」比環境更重要？請用孟子的例子和你自己的經驗說明。',
        ref: '我同意環境很重要。孟子說孩子住在齊國幾年，自然就會說齊國話；我在圖書館讀書，也比在吵鬧的客廳專心多了。不過自己努力也很重要，如果環境很好但自己不想學，還是學不會。我覺得兩個都要有。',
        rubric: ['表明自己的看法', '引用孟子的例子當證據', '用自己的經驗支持看法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「一傅眾咻」的「咻」是什麼意思？', opts: ['吵鬧、喧嘩', '休息一下', '教導學生', '快速跑走'], a: 0, why: '「咻」是喧擾、吵鬧；「傅」才是教導。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '小敏想在家準備明天的英語單字小考。她坐在客廳，表弟們在旁邊玩捉迷藏，大聲尖叫；電視播著綜藝節目，笑聲一直傳過來；樓上又在裝修，電鑽聲響個不停。她背了一整個晚上，一個單字也沒記住，急得快哭了。', q: '小敏背單字的情形，最適合用哪個成語形容？', opts: ['一傅眾咻', '始作俑者', '美輪美奐', '不恥下問'], a: 0, why: '想學習，周圍卻有很多吵鬧干擾，學不好，就是一傅眾咻。' },
      { id: 'p3', k: 'judge', d: 2, type: 'tf', q: '「這次班會只有小華反對，其他三十個人都支持另一個方案，他一個人說破了嘴也沒用，真是一傅眾咻。」這句話的「一傅眾咻」用得恰當。', a: true, why: '一傅眾咻也可以比喻勢單力薄、敵不過眾人，用在這裡恰當。' },
      { id: 'p4', k: 'use', d: 3, type: 'mc', ctx: '〈補習班廣告〉本班老師經驗豐富，一位老師同時指導四十位學生，一傅眾咻，教學效率最高！', q: '這則廣告用「一傅眾咻」恰當嗎？', opts: ['不恰當，眾咻是吵鬧干擾，不是學生很多', '恰當，因為一位老師教很多學生', '恰當，因為一傅眾咻表示教學很有效', '不恰當，因為一傅眾咻只能用在學齊國話'], a: 0, why: '「眾咻」是眾人吵鬧，一傅眾咻是說學習受干擾、效果不好。用在廣告裡，反而在說自己教不好。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '孟子說，在吵鬧的環境裡很難學好。想一想你平常寫功課、讀書的地方，有哪些會干擾你的「眾咻」？你可以怎麼改變環境，或改變自己的做法，讓學習更有效？',
        ref: '我寫功課時，手機的通知聲和電視聲最會干擾我。我可以把手機放到另一個房間，請家人看電視時把聲音轉小，或是先到書房寫完功課再出來看電視。',
        rubric: ['說出至少一個會干擾自己的東西', '提出改變環境或做法的具體方法', '說明這樣做為什麼能讓學習更有效'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '圖書館旁邊正在施工，敲打聲整天不停，同學們想專心讀書也難，真是＿＿＿＿。', opts: ['一傅眾咻', '始作俑者', '退避三舍', '樂不思蜀'], a: 0, why: '讀書受到吵鬧干擾，用一傅眾咻。其他三個放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 3, type: 'mc', ctx: '五年二班要決定校外教學去哪裡。只有阿德提出去科學館，還準備了好多資料說明科學館的展覽。可是其他同學都想去遊樂園，大家一起大聲喊「遊樂園！遊樂園！」，阿德的聲音完全被蓋過去，最後只好放棄。', q: '阿德的處境，最適合用哪一個成語形容？', opts: ['一傅眾咻', '不恥下問', '狡兔三窟', '如魚得水'], a: 0, why: '一個人的意見敵不過一大群人的喊聲，是一傅眾咻「寡不敵眾」的意思。' }
    ]
  },
  {
    id: 'cy087', lv: 4, word: '左右逢源', zhuyin: 'ㄗㄨㄛˇ ㄧㄡˋ ㄈㄥˊ ㄩㄢˊ', src: '《孟子．離婁下》',
    quote: '取之左右逢其原',
    facts: ['典源是《孟子．離婁下》，原本寫作「左右逢原」，「源」和「原」通用｜教育部《成語典》', '孟子主張求學要用心體會、自己領悟；學得深厚，用的時候才能隨手取用，好像左右兩邊都碰到水源｜教育部《成語典》典故說明', '後來比喻辦事得心應手，或處事圓融｜教育部《成語典》釋義', '《成語典》辨識：近義有八面玲瓏、得心應手、無往不利，反義是左支右絀｜教育部《成語典》'],
    story: [
      '戰國時代的孟子，是一位很重視讀書方法的思想家。他常常和學生討論：怎麼樣才算真正「學會」一樣東西？',
      '孟子說：「君子用正確的方法，一步一步深入學習，是希望自己能真正領悟、得到心得。」他認為，聽老師講、把書背下來，還不夠；要自己動腦想、用心體會，那些學問才會變成「自己的」。',
      '孟子接著說：學問變成自己的，就會牢牢的留在心裡；牢牢留在心裡，就能累積得又多又深；累積得又多又深，要用的時候，隨手一拿就有，不管往左邊拿、往右邊拿，都能碰到源頭，用也用不完。這就是原文說的「取之左右逢其原」。',
      '我們可以想像兩個挖井的人。第一個人只會跟著別人挖，挖得很淺就停了，井水一下子就用完，每次口渴都要到處借水。第二個人自己研究哪裡有水，一直往下挖，挖到了地底的泉源，從此不管什麼時候打水，水都源源不斷。孟子說的「自己領悟」，就像第二個人挖到的泉源。',
      '所以，「左右逢源」原本是說：學問真正學通了，用起來就得心應手、取之不盡。「原」就是水源，後來寫成「源」。',
      '後來，這個成語的意思慢慢擴大，用來形容一個人做起事來很順手，到處都能找到辦法；也用來形容一個人很會跟各方面的人相處，處事圓融。',
      '要小心，「左右逢源」說的是「處處順利、處處有辦法」。如果一個人事情太多、時間不夠、處處應付不來，應該說「左支右絀」，那剛好是左右逢源的反義詞。'
    ],
    mean: '原本指學問學通了，用的時候隨手就能取到源頭、用之不盡。後來比喻做事得心應手、處處順利，或處事圓融。',
    usage: ['形容學問紮實、做事得心應手，或很會跟各方面的人相處（處事圓融）。', '和「左支右絀」相反：左支右絀是事情太多、處處應付不來，不能說成左右逢源。', '「源」原本寫作「原」，兩字通用；今天一般寫「左右逢源」。'],
    misuse: ['「他一下要準備考試、一下要練球，零用錢也不夠用，真是左右逢源。」✗　處處應付不來是「左支右絀」，剛好是左右逢源的反義。'],
    eg: ['姊姊把基本的數學觀念學得很紮實，遇到新的題型也能左右逢源，很快想出解法。', '新來的店長很會跟顧客和員工溝通，工作起來左右逢源。'],
    syn: ['八面玲瓏', '得心應手', '無往不利'], ant: ['左支右絀'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '「左右逢源」原本寫作什麼？', opts: ['左右逢原', '左右逢圓', '左右縫源', '左右風原'], a: 0, why: '第五段：「『原』就是水源，後來寫成『源』。」' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '孟子認為，聽老師講、把書背下來為什麼「還不夠」？', opts: ['要自己體會，學問才會是自己的', '把書背下來，會浪費掉太多時間', '老師講的內容常常是錯的', '書上的字太多了記不起來'], a: 0, why: '第二段：「要自己動腦想、用心體會，那些學問才會變成『自己的』。」' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '文章用兩個挖井的人來比喻，第二個人挖到的「泉源」代表什麼？', opts: ['自己真正學通的學問', '跟別人借來的一桶水', '一口又深又漂亮的井', '存了很多錢的撲滿'], a: 0, why: '第四段最後：孟子說的「自己領悟」，就像第二個人挖到的泉源。' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '「左右逢源」和「左支右絀」的意思有什麼不同？', opts: ['一個處處順手，一個處處應付不來', '一個是往左邊走，一個是往右邊走', '兩個都是在說做事很順利', '兩個都是在說挖井很辛苦'], a: 0, why: '最後一段：左右逢源是「處處順利、處處有辦法」；左支右絀是「處處應付不來」，剛好相反。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '孟子認為學問要「自己領悟」，自己想通才算學會。你覺得「自己想通」和「老師直接告訴你答案」，哪一種學得比較牢？請用文章內容和你的學習經驗說明。',
        ref: '我覺得自己想通比較牢。文章說自己領悟的學問像挖到泉源，用不完。我學分數時，老師直接給公式，我很快就忘了；後來我自己用畫圖想通為什麼要通分，現在遇到新題目也會做。不過想不通時，請老師給一點提示也很重要。',
        rubric: ['表明哪一種學得比較牢', '引用文章內容（自己領悟、泉源的比喻）', '舉出自己的學習經驗當證據'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「左右逢源」的「源」是什麼意思？', opts: ['水的源頭', '人的緣分', '事情原因', '畫的圓圈'], a: 0, why: '「源」是水源、源頭；原本寫作「原」。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '小傑把英文的基本字根學得很熟。上英語課時，老師出了好多沒教過的新單字，小傑看看字根，就猜出了大部分的意思；課後做閱讀測驗，也是越寫越順手。同學問他怎麼那麼厲害，他說：「因為基本功打好了，遇到什麼都用得上。」', q: '小傑學英文的情形，最適合用哪個成語形容？', opts: ['左右逢源', '一傅眾咻', '始作俑者', '江郎才盡'], a: 0, why: '基本功學通了，遇到新東西都能用上，得心應手，就是左右逢源的本義。' },
      { id: 'p3', k: 'pair', d: 2, type: 'match', q: '把成語和它跟「左右逢源」的關係配起來。', pairs: [['得心應手', '近義：做起事來很順手'], ['左支右絀', '反義：事情太多，處處應付不來'], ['一傅眾咻', '無關：學習受到干擾']], why: '《成語典》辨識欄：得心應手是近義，左支右絀是反義。' },
      { id: 'p4', k: 'use', d: 3, type: 'mc', ctx: '〈週記〉這個星期我要準備月考、練鋼琴比賽，還要幫忙照顧生病的小狗，每件事都做不好，時間根本不夠用，我真是左右逢源。', q: '這篇週記用「左右逢源」恰當嗎？', opts: ['不恰當，處處應付不來應該說左支右絀', '恰當，因為作者同時做了很多事', '恰當，因為左右逢源就是很忙的意思', '不恰當，因為作者沒有提到水源'], a: 0, why: '作者每件事都做不好、時間不夠，是「左支右絀」，剛好是左右逢源的反義。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '孟子說，學問自己想通了，用起來就能「左右逢源」。請選一個你正在學的科目，說說哪一個「基本功」如果學得很紮實，以後會讓你在很多地方都用得上，以及你打算怎麼練。',
        ref: '我選數學的「乘法」。乘法學得熟，以後算面積、算分數、買東西算錢都用得上。我打算每天練十題，錯的題目自己畫圖想為什麼，而不是只背答案，這樣才是真的懂。',
        rubric: ['選出一個科目和一個基本功', '說明這個基本功可以用在哪些地方', '提出具體的練習方法'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '他對各種樂器都很熟悉，不管樂團缺哪個位置，他都能補上，表演時總是＿＿＿＿。', opts: ['左右逢源', '一傅眾咻', '美輪美奐', '始作俑者'], a: 0, why: '樣樣都能應付、處處得心應手，用左右逢源。其他三個放進句子都不通。' },
      { id: 'x2', k: 'use', d: 3, type: 'tf', ctx: '小華：「我同時參加了三個社團，作業又多，每天都忙得團團轉，什麼都做不完。」\n小明：「你現在真是左右逢源啊！」', q: '小明說的「左右逢源」用得恰當。', a: false, why: '小華什麼都做不完，是處處應付不來的「左支右絀」，不是左右逢源。' }
    ]
  },
  {
    id: 'cy090', lv: 4, word: '既往不咎', zhuyin: 'ㄐㄧˋ ㄨㄤˇ ㄅㄨˋ ㄐㄧㄡˋ', src: '《論語．八佾》',
    quote: '成事不說，遂事不諫，既往不咎',
    facts: ['典源是《論語．八佾》：魯哀公問孔子的學生宰我，祭祀土地神的牌位該用什麼木頭｜教育部《成語典》', '宰我照夏、商、周的習慣回答，又附會說周朝用栗木是要讓百姓「戰栗」；孔子認為他隨便猜測古人的用意，說了這段話提醒他說話要謹慎｜教育部《成語典》典故說明', '釋義是對過去的錯誤不再追究責難；多用在寬恕諒解的情境｜教育部《成語典》', '《成語典》辨識：「咎」音ㄐㄧㄡˋ，是責怪、追究；古書偶爾寫作「究」，但現代不宜寫成「究」｜教育部《成語典》'],
    story: [
      '春秋時代的魯國，國君叫魯哀公。古時候，國家會為土地神立一個木頭做的牌位，叫做「社」，讓大家祭拜。',
      '有一天，魯哀公問孔子的學生宰我：「做土地神的牌位，應該用什麼木頭呢？」',
      '宰我回答：「夏朝的人用松木，商朝的人用柏木，周朝的人用栗木。」說到這裡都還沒問題，可是宰我又多加了一句：「周朝用栗木，是要讓百姓看了害怕得發抖，也就是『戰栗』。」',
      '其實，宰我只是看到「栗」這個字，就自己猜測古人的用意，並沒有根據。孔子覺得這樣說很不妥當，萬一國君真的相信了，以為治理百姓就是要讓他們害怕，那就糟了。',
      '孔子聽說了這件事，說：「已經做成的事，就不要再解說；已經完成的事，就不要再勸阻；已經過去的事，就不要再追究了。」',
      '孔子這句話，一方面是說：話已經說出去了，再責備也收不回來；另一方面，也是在提醒宰我：以後說話要謹慎，沒有把握的事，不要隨便亂說。',
      '這段話記在《論語．八佾》裡。後來，人們用其中的「既往不咎」，表示對過去的錯誤不再追究、不再責怪，多用在寬恕、原諒別人的時候。「咎」是責怪、追究的意思，讀作ㄐㄧㄡˋ，不要寫成「究」。'
    ],
    mean: '對過去的錯誤，不再追究責怪。',
    usage: ['用在原諒別人過去犯的錯，不再追究的時候，有寬恕的意思。', '要有「過去的錯誤」才能用；過去發生的好事、開心的回憶，不能說既往不咎。', '「咎」音ㄐㄧㄡˋ，現在不宜寫成「究」。'],
    misuse: ['「去年全家去露營好開心，那些回憶我們就既往不咎吧。」✗　既往不咎是原諒過去的「錯誤」，開心的回憶不是錯誤。', '「只要你誠心改過，我們可以既往不究。」✗　依《成語典》，「咎」現在不宜寫作「究」。'],
    eg: ['弟弟把我的模型弄壞後主動道歉，還幫我重新黏好，我決定既往不咎。', '老闆說，只要員工以後準時上班，之前遲到的事就既往不咎。'],
    syn: [], ant: ['嚴懲不貸'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '魯哀公問宰我什麼問題？', opts: ['土地神的牌位該用什麼木頭', '要怎麼樣做，才能讓百姓害怕', '孔子最喜歡什麼樹', '國家該種多少棵栗樹'], a: 0, why: '第二段：「做土地神的牌位，應該用什麼木頭呢？」' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '宰我的回答，哪一部分讓孔子覺得不妥？', opts: ['亂猜用栗木是要讓百姓怕', '說夏朝的人用的是松木', '說商朝的人用的是柏木', '回答國君的速度太慢'], a: 0, why: '第三、四段：前面說各朝用什麼木頭「都還沒問題」，多加的那句「讓百姓戰栗」才是沒有根據的猜測。' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '孔子說「已經過去的事，就不要再追究了」，同時也在提醒宰我什麼？', opts: ['說話要謹慎，沒把握別亂說', '趕快去跟國君道歉認錯', '以後要多種一些栗樹', '以後不要再回答國君'], a: 0, why: '第六段：孔子「也是在提醒宰我：以後說話要謹慎，沒有把握的事，不要隨便亂說」。' },
      { id: 'r4', p: 3, d: 3, type: 'tf', q: '依照文章，「既往不咎」是對過去的錯誤不再追究，所以不能用來形容「過去發生的開心回憶」。', a: true, why: '最後一段：既往不咎是對過去的「錯誤」不再追究，開心的回憶不是錯誤。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '孔子沒有重重責罵宰我，而是說「既往不咎」，再提醒他以後要小心。你覺得這種處理方式好不好？如果你的朋友說錯了話，你會怎麼回應？',
        ref: '我覺得很好。話已經說出去了，一直罵也收不回來，不如提醒他下次注意。如果朋友說錯了話，例如把謠言當真告訴別人，我會跟他說「沒關係，以後聽到消息先查一查再說」，不會一直責怪他。',
        rubric: ['對孔子的處理方式提出看法並說明理由', '能用故事內容當證據', '提出自己回應朋友的具體說法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「既往不咎」的「咎」是什麼意思？', opts: ['責怪、追究', '過去的事', '以後的事', '高興快樂'], a: 0, why: '「咎」是責怪、追究罪過；「既往」才是已經過去的事。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '上學期，小翰常常跟同學吵架，還弄壞過班上的植物盆栽。這學期他改變很多，主動幫忙澆花、照顧新的盆栽，也向以前吵過架的同學道歉。班會上，有人又提起他去年弄壞盆栽的事，班長說：「他已經改過了，以前的事就不要再追究了。」', q: '班長的態度，最適合用哪個成語形容？', opts: ['既往不咎', '始作俑者', '一傅眾咻', '左右逢源'], a: 0, why: '對小翰過去的錯誤不再追究，就是既往不咎。' },
      { id: 'p3', k: 'judge', d: 2, type: 'tf', q: '「他偷看了我的日記，可是他已經誠心道歉，還保證不會再犯，我就既往不咎了。」這句話的「既往不咎」用得恰當。', a: true, why: '對方犯了錯、已經道歉，自己選擇不再追究，用得恰當。' },
      { id: 'p4', k: 'use', d: 3, type: 'mc', ctx: '〈畢業感言〉六年來，我們一起參加運動會、校外教學、園遊會，留下好多美好的回憶。畢業以後，這些快樂的時光就讓它既往不咎吧！', q: '這段感言用「既往不咎」恰當嗎？', opts: ['不恰當，它是原諒錯誤，快樂回憶不是錯誤', '恰當，因為那些事都已經過去了', '恰當，因為既往不咎就是不要再想過去', '不恰當，因為畢業以後還會再見面'], a: 0, why: '既往不咎是對過去的「錯誤」不再追究。美好的回憶不是錯誤，用了反而像在說那些回憶是錯事。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '孔子說「已經過去的事，就不要再追究了」。想一想，有沒有人曾經對你做錯事、你一直放在心上？你覺得什麼時候適合「既往不咎」？什麼時候還是需要把話說清楚？',
        ref: '二年級時有同學故意把我的鉛筆盒藏起來，我一直記得。現在他對我很好，也道過歉，我覺得可以既往不咎。可是如果有人一直重複做錯事、還傷害別人，我就要把話說清楚，或是請老師幫忙，不能只是原諒。',
        rubric: ['說出一個被別人做錯事的經驗', '說明適合既往不咎的情況', '說明需要把話說清楚的情況'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '只要你把借走的書還回來，再好好道個歉，我們就＿＿＿＿，還是好朋友。', opts: ['既往不咎', '左右逢源', '美輪美奐', '一傅眾咻'], a: 0, why: '對方改正錯誤後不再追究，用既往不咎。其他三個放進句子都不通。' },
      { id: 'x2', k: 'use', d: 3, type: 'tf', ctx: '小美：「上個週末我們全家去海邊玩，那天的夕陽好美，我好想再去一次。」\n小芳：「那些都過去了，你就既往不咎吧！」', q: '小芳說的「既往不咎」用得恰當。', a: false, why: '去海邊看夕陽是開心的事，不是錯誤，沒有什麼要「不追究」的，用既往不咎不恰當。' }
    ]
  },
  {
    id: 'cy093', lv: 4, word: '敝帚自珍', zhuyin: 'ㄅㄧˋ ㄓㄡˇ ㄗˋ ㄓㄣ', src: '《東觀漢記．光武帝紀》',
    quote: '家有敝帚，享之千金',
    facts: ['典源是《東觀漢記．光武帝紀》：東漢光武帝劉秀派吳漢攻打在蜀地自立為王的公孫述｜教育部《成語典》', '吳漢的軍隊進成都後放任士兵燒殺搶掠，光武帝下詔責備；副將劉禹也勸他，說了「家有敝帚，享之千金」｜教育部《成語典》典故說明', '三國魏文帝曹丕〈典論論文〉也引用里語「家有弊帚，享之千金」，說明人不容易看見自己作品的缺點｜三國魏．曹丕〈典論．論文〉', '《成語典》辨識：「敝」是破舊，音ㄅㄧˋ，不可寫作「蔽」｜教育部《成語典》'],
    story: [
      '東漢剛建立的時候，天下還沒有完全平定。在西南方的蜀地，有一個叫公孫述的人自己稱王，光武帝劉秀好幾次勸他歸順，他都不肯。光武帝只好派大將吳漢帶兵去攻打。',
      '吳漢的軍隊打到成都城下，公孫述的部下投降了。照理說，仗打完了，應該好好安撫城裡的百姓。',
      '可是吳漢卻放任士兵在城裡搶東西、放火，百姓的家被弄得亂七八糟。消息傳回京城，光武帝非常生氣，寫了詔書責備吳漢。',
      '吳漢的副將劉禹也勸他：「城裡有很多老人、婦女和小孩。俗話說：『家有敝帚，享之千金。』一把破掃把，對主人來說也像千金一樣寶貴。百姓的家再普通，也是他們最珍惜的地方啊！」劉禹認為，對百姓這樣不留情，就失去了仁義的心。',
      '「敝」是破舊，「帚」是掃把。後來，三國時代的魏文帝曹丕在一篇談文章的作品裡，也用了這句俗話。他說：很多人寫文章，總覺得自己寫的最好，看不見自己的缺點，就像把自家的破掃把當成寶貝一樣。',
      '慢慢的，人們把這句話濃縮成「敝帚自珍」，比喻東西雖然不怎麼好，但因為是自己的，所以特別珍惜。今天，它常用在說自己的東西或作品，帶有謙虛的味道，例如：「這幅畫畫得不好，只是我敝帚自珍，捨不得丟。」',
      '要注意，「敝帚自珍」是說「珍惜自己的東西」。稱讚別人的寶物很珍貴，或是提醒大家愛惜公物，都不能用它。另外，「敝」是破舊的意思，不要寫成「蔽」。'
    ],
    mean: '把自家的破掃把也當成寶貝。比喻東西雖然不好，但因為是自己的，所以特別珍惜。',
    usage: ['用在說自己（或某人對他自己）的東西、作品雖然不怎麼樣，卻非常珍惜；說自己時帶有謙虛的意思。', '不能用來稱讚別人的東西「很珍貴、很值錢」，也不是「愛惜公物」的意思。', '「敝」是破舊，不可寫作「蔽」。'],
    misuse: ['「博物館裡那件價值連城的古董花瓶，真是敝帚自珍。」✗　敝帚自珍是說不怎麼好的東西因為是自己的而珍惜；價值很高的古董不能這樣說。', '「我們要敝帚自珍，愛護學校的公物。」✗　敝帚自珍說的是珍惜「自己的」東西，愛護公物要說「愛惜公物」。'],
    eg: ['這本日記的字寫得歪歪扭扭，但我敝帚自珍，一直把它放在書桌最上層。', '爺爺那臺舊收音機早就收不太到訊號了，他卻敝帚自珍，每天都要擦一擦。'],
    syn: ['敝屣自珍'], ant: ['視若草芥', '棄如敝屣'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '光武帝派吳漢去攻打誰？', opts: ['在蜀地稱王的公孫述', '東漢的副將劉禹', '三國的魏文帝曹丕', '成都城裡的百姓'], a: 0, why: '第一段：公孫述在蜀地自己稱王，光武帝派吳漢去攻打。' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '劉禹說「家有敝帚，享之千金」，是想提醒吳漢什麼？', opts: ['百姓的家再普通，也是他們最珍惜的', '掃把很重要，出去打仗時要多帶一些', '成都城裡藏著價值千金的寶物', '打掃軍營的時候要用新的掃把'], a: 0, why: '第四段：「百姓的家再普通，也是他們最珍惜的地方啊！」' },
      { id: 'r3', p: 3, d: 2, type: 'mc', q: '曹丕用這句俗話，是在說寫文章的人有什麼問題？', opts: ['看不見自己作品的缺點', '字寫得太醜，別人都看不懂', '常常把掃把弄丟', '寫得太慢交不出來'], a: 0, why: '第五段：很多人「總覺得自己寫的最好，看不見自己的缺點」。' },
      { id: 'r4', p: 3, d: 3, type: 'tf', q: '依照文章，稱讚別人的收藏很珍貴時，可以說他「敝帚自珍」。', a: false, why: '最後一段：敝帚自珍是「珍惜自己的東西」，而且東西不怎麼好；稱讚別人的寶物很珍貴不能用它。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '曹丕說，人常常把自己的作品當寶貝，看不見缺點。你同意嗎？珍惜自己的作品，和接受別人的建議，可以同時做到嗎？請說明你的想法。',
        ref: '我同意，因為自己花了很多心血，就會覺得每個地方都很好。但我覺得兩者可以同時做到：我可以把作品好好收著，表示我珍惜它；同時請別人幫我看，記下可以改進的地方，下一次做得更好。',
        rubric: ['對曹丕的說法表示同不同意並說明理由', '說明珍惜作品和接受建議能不能同時做到', '提出具體的做法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「敝帚自珍」的「敝帚」是什麼？', opts: ['破舊的掃把', '很貴的寶物', '新買的刷子', '掃地的工人'], a: 0, why: '「敝」是破舊，「帚」是掃把。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '小安一年級時用黏土捏了一隻小烏龜，形狀歪歪的，殼上的顏色也塗出了線。家人整理房間時問她要不要丟掉，小安搖搖頭，把小烏龜放回書架上：「它雖然不好看，可是是我第一次做的作品，我捨不得丟。」', q: '小安對小烏龜的感情，最適合用哪個成語形容？', opts: ['敝帚自珍', '既往不咎', '美輪美奐', '左右逢源'], a: 0, why: '作品不怎麼好看，但因為是自己做的而特別珍惜，就是敝帚自珍。' },
      { id: 'p3', k: 'judge', d: 2, type: 'tf', q: '「我寫的這首童詩雖然很普通，但我敝帚自珍，把它抄在筆記本的第一頁。」這句話的「敝帚自珍」用得恰當。', a: true, why: '說自己的作品普通卻很珍惜，帶有謙虛的意思，用得恰當。' },
      { id: 'p4', k: 'use', d: 3, type: 'mc', ctx: '〈參觀心得〉博物館裡展出一件一千年前的玉器，雕工精細，是國家的重要寶物，專家說它非常珍貴。這件玉器真是敝帚自珍啊！', q: '這篇心得用「敝帚自珍」恰當嗎？', opts: ['不恰當，玉器很珍貴，又不是自己的舊東西', '恰當，因為玉器被人好好的保存了一千年', '恰當，因為敝帚自珍就是形容寶物', '不恰當，因為玉器不是掃把做的'], a: 0, why: '敝帚自珍是「東西不怎麼好，但因為是自己的而珍惜」。珍貴的國寶不能這樣形容。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '你有沒有一樣東西，在別人眼中不怎麼樣，你卻很珍惜（舊玩具、第一次的作品、朋友送的小東西）？說說它的故事，以及你為什麼「敝帚自珍」。',
        ref: '我有一個掉了一隻耳朵的小熊玩偶，是我出生時阿嬤送的。它已經很舊了，可是每次抱著它就會想到阿嬤，所以我一直捨不得丟，還請家人幫我把耳朵縫回去。',
        rubric: ['說出一樣自己珍惜的東西', '說出它的故事或來歷', '說明珍惜它的原因'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '這張我小時候畫的全家福，人物畫得像火柴人，但我＿＿＿＿，一直把它貼在床頭。', opts: ['敝帚自珍', '既往不咎', '一傅眾咻', '始作俑者'], a: 0, why: '畫得不好卻因為是自己的而珍惜，用敝帚自珍。其他三個放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 3, type: 'mc', ctx: '哥哥的球鞋穿了三年，鞋底磨平了，鞋帶也換過好幾次。家人說要買一雙新的給他，他卻說：「這是我第一次參加籃球比賽時穿的鞋，雖然舊了，我還是想留著。」他把球鞋洗得乾乾淨淨，收在鞋盒裡，放在衣櫃最上層。', q: '哥哥對這雙舊球鞋的態度，可以用哪一個成語形容？', opts: ['敝帚自珍', '美輪美奐', '口蜜腹劍', '既往不咎'], a: 0, why: '舊球鞋已經不好穿了，哥哥卻因為它有特別的回憶而珍惜，是敝帚自珍。' }
    ]
  },
  {
    id: 'cy096', lv: 4, word: '口蜜腹劍', zhuyin: 'ㄎㄡˇ ㄇㄧˋ ㄈㄨˋ ㄐㄧㄢˋ', src: '五代周．王仁裕《開元天寶遺事．肉腰刀》',
    quote: '口有蜜，腹有劍', quoteFrom: '《資治通鑑．唐紀三十一》',
    facts: ['典源是五代周．王仁裕《開元天寶遺事．肉腰刀》：唐玄宗時的宰相李林甫妒賢嫉能，當時的人叫他「肉腰刀」｜教育部《成語典》', '李林甫當了十九年宰相，常用甜言蜜語引誘政敵上當，再暗中陷害｜教育部《成語典》典故說明', '李林甫騙李適之說華山有金礦，要他建議開採，再對玄宗說華山是王氣所在不能挖，使李適之被罷去宰相｜教育部《成語典》典故說明', '《資治通鑑》記載「世謂李林甫口有蜜，腹有劍」｜《資治通鑑．唐紀三十一》', '《成語典》辨識：笑裡藏刀側重面容和善，口蜜腹劍側重話語甜蜜；「蜜」不可寫作「密」｜教育部《成語典》'],
    story: [
      '唐朝玄宗皇帝的時候，有一位宰相叫李林甫，他一共當了十九年的宰相。李林甫很會說話，見到人總是笑咪咪的，說的都是讓人聽了很舒服的好話。',
      '可是，李林甫心裡最怕的，就是有人比他更有才能、更受皇帝喜歡。只要發現誰可能威脅到自己的位子，他就會想辦法把那個人趕走。',
      '有一次，玄宗讓一位叫李適之的人也當上宰相。李林甫表面上跟李適之很要好，心裡卻很不高興。',
      '有一天，李林甫很親切的對李適之說：「我聽說華山底下有金礦，要是挖出來，國家就不缺錢了。皇上還不知道這件事，您趕快去告訴皇上吧！」李適之覺得這是為國家做好事，就照著去跟玄宗說了。',
      '玄宗聽了很心動，轉頭問李林甫的意見。李林甫卻一臉嚴肅的說：「這件事我早就知道了。可是華山是保佑國家的重要地方，不能隨便挖，所以我一直不敢說。」玄宗聽了，覺得李林甫想得很周到，反而認為李適之做事不夠細心。沒過多久，李適之的宰相就被撤掉了。',
      '李林甫用這種方法，害了很多人。當時的人都說，他是一把「肉腰刀」——看起來是人，其實像一把藏在身上的刀；還說他「嘴裡有蜜，肚子裡藏著劍」。',
      '後來，人們就用「口蜜腹劍」比喻一個人嘴上說得很甜、很好聽，心裡卻很陰險，處處想陷害別人。要注意，「蜜」是蜂蜜的蜜，不要寫成「祕密」的「密」。'
    ],
    mean: '嘴裡有蜜，肚子裡藏著劍。比喻嘴巴說得很好聽，心裡卻很陰險，想暗中陷害別人。',
    usage: ['用在批評表面上說好話、背地裡害人的人（貶義），是很重的批評。', '重點是「心裡想害人」；只是說話好聽、喜歡稱讚別人，不能說口蜜腹劍。', '「蜜」不可寫作「密」。和「笑裡藏刀」很像：笑裡藏刀側重臉上和善，口蜜腹劍側重說話甜蜜。'],
    misuse: ['「小芳說話溫柔，常常稱讚別人，真是口蜜腹劍。」✗　只是說話好聽，沒有想害人，不能用口蜜腹劍，這樣說會冤枉人。', '「那個騙子口密腹劍，騙走了很多人的錢。」✗　「蜜」不可寫作「密」，應寫「口蜜腹劍」。'],
    eg: ['故事裡的狐狸口蜜腹劍，一邊稱讚烏鴉的歌聲，一邊想騙走牠的肉。', '交朋友要看他做了什麼，不能只聽好聽的話，才不會被口蜜腹劍的人騙了。'],
    syn: ['佛口蛇心', '笑裡藏刀', '表裡不一'], ant: ['表裡如一'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '李林甫跟李適之說，華山底下有什麼？', opts: ['金礦', '寶劍', '泉水', '古墓'], a: 0, why: '第四段：「我聽說華山底下有金礦。」' },
      { id: 'r2', p: 2, d: 2, type: 'mc', q: '李林甫為什麼要騙李適之去跟皇帝說金礦的事？', opts: ['想讓皇帝覺得李適之做事不細心', '想讓國家趕快挖到華山底下的金子', '想跟李適之一起去華山玩', '想讓李適之變得很有錢'], a: 0, why: '第二、五段：李林甫想趕走威脅自己的人；結果玄宗「認為李適之做事不夠細心」，撤掉了他。' },
      { id: 'r3', p: 2, d: 2, type: 'tf', q: '李林甫在皇帝面前說「華山不能挖」，是因為他真的剛剛才想到這個問題。', a: false, why: '第五段他自己說「這件事我早就知道了」，可見他是故意設計好的。' },
      { id: 'r4', p: 3, d: 3, type: 'mc', q: '當時的人叫李林甫「肉腰刀」，和「口蜜腹劍」有什麼共同的意思？', opts: ['外表看起來無害，其實會傷人', '他身上隨時都帶著一把刀', '他很喜歡吃肉，也愛吃蜂蜜', '他是唐朝最會用刀的將軍'], a: 0, why: '第六段：「看起來是人，其實像一把藏在身上的刀」，跟嘴上甜、心裡藏劍的意思一樣。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '李適之相信了李林甫的「好話」，結果被害。你覺得要怎麼分辨一個人是真心對你好，還是「口蜜腹劍」？請用故事中的情節說明。',
        ref: '要看他做的事，不能只聽他說的話。李林甫說的話很好聽，可是他叫李適之去做事，自己卻在皇帝面前說相反的話。如果一個人當面稱讚我，背後卻說我壞話，或是要我做一件對他有好處、對我有害的事，就要小心。',
        rubric: ['提出分辨的方法（看行動、看前後是否一致等）', '能用故事中李林甫的做法當證據', '方法具體，可以用在生活中'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「口蜜腹劍」的「腹」是什麼意思？', opts: ['肚子、內心', '背部、後面', '嘴巴、說話', '手臂、力氣'], a: 0, why: '「腹」是肚子，這裡比喻心裡；「腹劍」就是心裡藏著劍。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '阿華在大家面前常常稱讚小志：「你畫得真好，是我們班最厲害的！」還說要幫小志報名繪畫比賽。可是報名截止前，阿華卻偷偷把小志的報名表藏起來，自己去報名，還跟別人說小志根本不想參加。小志知道以後非常難過。', q: '阿華的行為，最適合用哪個成語形容？', opts: ['口蜜腹劍', '敝帚自珍', '既往不咎', '不恥下問'], a: 0, why: '阿華嘴上稱讚小志，背地裡卻陷害他，是口蜜腹劍。' },
      { id: 'p3', k: 'use', d: 2, type: 'tf', ctx: '〈日記〉今天在麵包店，店員很熱情的介紹每一種麵包，還送我們試吃，告訴我們哪一種最新鮮。阿姨說這位店員真是口蜜腹劍。', q: '日記中阿姨說的「口蜜腹劍」用得恰當。', a: false, why: '店員只是熱情介紹，沒有想害人。口蜜腹劍要有「心裡想陷害別人」的意思，這樣說會冤枉人。' },
      { id: 'p4', k: 'pair', d: 2, type: 'match', q: '把成語和它跟「口蜜腹劍」的關係配起來。', pairs: [['笑裡藏刀', '近義：臉上和善，心裡藏著壞主意'], ['表裡如一', '反義：外表和內心一樣'], ['敝帚自珍', '無關：珍惜自己的舊東西']], why: '《成語典》辨識欄：笑裡藏刀是近義，表裡如一是反義。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '李林甫靠好聽的話騙了很多人。在網路上或生活中，你有沒有遇過說話很好聽、卻可能別有目的的情況（例如「免費送你」的訊息、陌生人的稱讚）？你會怎麼保護自己？',
        ref: '我曾收到訊息說「恭喜你中獎，點這個連結就能領獎品」。說得很好聽，可是可能是詐騙。我不會點連結，也不會給出家裡的地址和電話，會先問家人或老師。陌生人一直稱讚我、要我跟他走，我也會拒絕並離開。',
        rubric: ['說出一個話很好聽但可能有目的的情況', '提出保護自己的具體做法', '說明為什麼要這樣做'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '他當面稱讚你的報告做得好，背地裡卻跟別人說你是抄來的，這種＿＿＿＿的人，一定要小心。', opts: ['口蜜腹劍', '敝帚自珍', '左右逢源', '美輪美奐'], a: 0, why: '當面說好話、背後害人，用口蜜腹劍。其他三個放進句子都不通。' },
      { id: 'x2', k: 'use', d: 3, type: 'mc', ctx: '〈班會紀錄〉這學期的模範生小琪，說話總是很有禮貌，常常鼓勵同學，也會主動幫忙打掃。有同學說：「她說話這麼好聽，一定是口蜜腹劍。」', q: '這位同學說的「口蜜腹劍」恰當嗎？', opts: ['不恰當，小琪沒有害人的心，這樣說是冤枉她', '恰當，因為小琪說話真的很好聽', '恰當，因為說好話的人都不能相信', '不恰當，因為口蜜腹劍只能用來形容古代宰相'], a: 0, why: '口蜜腹劍的重點是心裡想害人。小琪說話好聽、也真心幫忙，說她口蜜腹劍是冤枉她。' }
    ]
  },
  {
    id: 'cy099', lv: 4, word: '削足適履', zhuyin: 'ㄒㄩㄝˋ ㄗㄨˊ ㄕˋ ㄌㄩˇ', src: '《淮南子．說林》',
    quote: '譬猶削足而適履，殺頭而便冠',
    facts: ['典源是《淮南子．說林》；《淮南子》是西漢淮南王劉安召集門下賓客寫成的書｜教育部《成語典》', '《淮南子》評論春秋時晉獻公寵愛驪姬、聽信挑撥，使父子骨肉互相傷害，把這種情形比作削腳穿鞋、砍頭戴帽｜教育部《成語典》典故說明', '釋義：鞋子太小，就把腳削小來配合鞋子；比喻拘泥成例、勉強遷就，不知變通（貶義）｜教育部《成語典》', '《成語典》注音：「削」讀ㄒㄩㄝˋ｜教育部《成語典》'],
    story: [
      '西漢的時候，淮南王劉安請了很多有學問的客人，一起寫了一本書，叫做《淮南子》。書裡收集了很多道理，常常用生活中的小比方，來說明大事情。',
      '在〈說林〉這一篇裡，作者談到一件春秋時代的事：晉國的國君晉獻公，很寵愛一位叫驪姬的妃子。驪姬想讓自己的兒子當太子，就常常在晉獻公面前說其他兒子的壞話。晉獻公聽信了她的話，讓原本的太子申生陷入危險，另外兩個兒子重耳和夷吾，也被逼得逃到國外去。',
      '作者覺得很可惜：父親和兒子，本來應該是最親的人，卻因為有人在中間挑撥，變成互相傷害。為了眼前的一點東西，卻傷害了自己最重要的家人，這實在太不合理了。',
      '於是作者打了一個比方：這就好像鞋子太小，穿不下，就把自己的腳削掉一塊，硬塞進鞋子裡；又好像帽子太小，戴不上，就把頭削小去配合帽子。鞋子和帽子本來是為了保護腳和頭，現在卻為了它們去傷害腳和頭，不是本末倒置了嗎？',
      '「削」是用刀削去，「適」是配合、適應，「履」是鞋子。後來，人們就用「削足適履」，比喻死守現成的規定或做法，不管實際情況，硬要勉強遷就，結果反而傷害了真正重要的東西。',
      '想一想：鞋子太小，正確的做法應該是什麼？當然是換一雙合腳的鞋子，而不是削腳。做事情也一樣，規定和方法是為了幫助人，如果不合用，就要懂得調整，不能反過來要人硬去配合。'
    ],
    mean: '鞋子太小，就把腳削小去配合鞋子。比喻死守現成的做法，不管實際情況，勉強遷就，不懂得變通。',
    usage: ['批評人只顧遵守現成的規定、做法或模式，不管合不合實際，硬要遷就（貶義）。', '重點是「為了配合不合適的東西，反而傷害了重要的東西」；只是努力適應新環境，不能說削足適履。', '依《成語典》，「削」讀ㄒㄩㄝˋ。'],
    misuse: ['「轉學到新學校，他很快就交到朋友、適應了新的作息，真是削足適履。」✗　積極適應環境是好事，沒有勉強遷就、傷害重要的東西，不能用削足適履。'],
    eg: ['為了讓作文剛好寫滿一頁，他把最精采的段落刪掉，這樣削足適履，反而讓文章變得不完整。', '座位不一定要每學期都照舊，如果有人看不清黑板還硬要照排，就是削足適履了。'],
    syn: ['生搬硬套', '殺頭便冠'], ant: ['因地制宜', '因時制宜', '量體裁衣'],
    rq: [
      { id: 'r1', p: 1, d: 1, type: 'mc', q: '《淮南子》是誰和門下的客人一起寫的？', opts: ['淮南王劉安', '晉國的晉獻公', '驪姬', '重耳'], a: 0, why: '第一段：「淮南王劉安請了很多有學問的客人，一起寫了一本書。」' },
      { id: 'r2', p: 1, d: 1, type: 'tf', q: '依照最後一段，鞋子太小時，作者認為應該換一雙合腳的鞋子。', a: true, why: '最後一段：「當然是換一雙合腳的鞋子，而不是削腳。」' },
      { id: 'r3', p: 2, d: 2, type: 'mc', q: '作者為什麼覺得晉獻公的事「很可惜」？', opts: ['最親的家人因為挑撥而互相傷害', '晉國的鞋子都做得太小了', '驪姬的兒子沒有當上太子', '晉獻公一點都不喜歡讀《淮南子》'], a: 0, why: '第三段：父親和兒子本來最親，「卻因為有人在中間挑撥，變成互相傷害」。' },
      { id: 'r4', p: 3, d: 2, type: 'mc', q: '作者把晉獻公的事比作「削腳穿鞋」，兩者共同的問題是什麼？', opts: ['為了次要的東西，傷害了最重要的', '都是在說鞋子和帽子的價錢太貴了', '都是在說春秋時代生活辛苦', '都是在說家人要住在一起'], a: 0, why: '第三、四段：為了眼前的東西傷害家人，就像為了鞋子削掉腳，都是本末倒置。' },
      { id: 'r5', p: 4, d: 3, type: 'open', q: '文章最後說「規定和方法是為了幫助人」。你同意嗎？請舉一個學校或家裡的規定，說說如果它不合用，應該怎麼調整，才不會「削足適履」。',
        ref: '我同意。像我們班規定每個人都要坐固定座位，可是有一位同學近視看不清黑板，如果硬要他坐後面，就是削足適履。應該讓他換到前面，規定是為了讓大家好好上課，不是要讓人看不到。',
        rubric: ['表明同不同意並說明理由', '舉出一個具體的規定', '提出合理的調整方法'] }
    ],
    pq: [
      { id: 'p1', k: 'mean', d: 1, type: 'mc', q: '「削足適履」的「履」是什麼意思？', opts: ['鞋子', '腳掌', '帽子', '走路'], a: 0, why: '「履」是鞋子；「適履」就是去配合鞋子。' },
      { id: 'p2', k: 'sit', d: 2, type: 'mc', ctx: '學校規定每班的話劇表演都要剛好五分鐘。五年一班的劇本很精采，排練時演了七分鐘。編劇小組沒有想辦法讓節奏緊湊一點，而是直接把故事最重要的結局整段刪掉。結果正式演出時，觀眾都看不懂故事到底在說什麼。', q: '五年一班的做法，最適合用哪個成語形容？', opts: ['削足適履', '敝帚自珍', '既往不咎', '口蜜腹劍'], a: 0, why: '為了配合五分鐘的限制，硬把最重要的結局刪掉，傷害了整齣戲，就是削足適履。' },
      { id: 'p3', k: 'judge', d: 2, type: 'tf', q: '「褲管太長了，就把它剪短一點，讓弟弟穿起來剛剛好，這是削足適履。」這句話的「削足適履」用得恰當。', a: false, why: '把褲子改成配合人，是調整東西來適合人，剛好和「削腳去配合鞋子」相反。' },
      { id: 'p4', k: 'use', d: 3, type: 'mc', ctx: '〈校刊評論〉學校的游泳課原本只教自由式，可是有一半的同學怕水，連漂浮都不會。體育組決定先開「水中適應班」，讓怕水的同學從玩水開始練習。有人批評這是削足適履。', q: '這位批評者用「削足適履」恰當嗎？', opts: ['不恰當，學校是依照學生情況調整，剛好相反', '恰當，因為學校改變了原本的課程', '恰當，因為游泳課本來就應該照原樣只教自由式', '不恰當，因為游泳課不用穿鞋子'], a: 0, why: '學校是依照學生的實際情況調整課程，正是「量體裁衣」，和削足適履相反。' },
      { id: 'p5', k: 'xfer', d: 3, type: 'open', q: '鞋子太小，應該換鞋，不是削腳。想一想，你在學習或生活中，有沒有「硬把自己塞進不合適的方法」的經驗（例如照著別人的讀書計畫、硬要一次做完所有功課）？你後來怎麼調整？',
        ref: '我曾經照著同學的方法，每天晚上讀書讀到十一點，結果白天上課一直打瞌睡。後來我改成早點睡、早上起來讀二十分鐘，比較適合我，成績也沒有退步。',
        rubric: ['說出一個硬套不合適方法的經驗', '說明它帶來的問題', '提出自己調整後的做法'] }
    ],
    xq: [
      { id: 'x1', k: 'fill', d: 2, type: 'mc', q: '每個孩子的興趣和能力都不一樣，硬要大家用同一種方法學習，只會＿＿＿＿，讓很多人學不好。', opts: ['削足適履', '敝帚自珍', '左右逢源', '既往不咎'], a: 0, why: '硬要每個人遷就同一種方法，不管實際情況，用削足適履。其他三個放進句子都不通。' },
      { id: 'x2', k: 'sit', d: 3, type: 'mc', ctx: '阿明的舅舅安排家族旅行，照著網路上一份「三天玩遍十個景點」的行程表走。可是阿嬤走路比較慢，表妹還小需要午睡。大家為了趕上行程，一路小跑步，阿嬤累得腳痛，表妹也哭鬧不停，最後誰都玩得不開心。', q: '舅舅安排行程的方式，最適合用哪一個成語形容？', opts: ['削足適履', '如魚得水', '口蜜腹劍', '一傅眾咻'], a: 0, why: '不管家人的實際情況，硬要大家配合現成的行程表，結果每個人都不開心，是削足適履。' }
    ]
  }
]);
window.DATA_CY_READ = (window.DATA_CY_READ || []).concat([
  {
    id: 'cyr03', lv: 2, genre: '新聞', domain: ['社會', '科技'], title: '「水塔有蛇」？一則謠言的三個小時',
    uses: ['cy023', 'cy026', 'cy027'],
    facts: ['報導中的學校、人物、事件都是虛構的｜虛構情境'],
    body: [
      { h: '校園小記者　第十二期' },
      '【本刊記者林小晴／報導】上星期二晚上，一則「學校水塔裡有蛇」的消息，在學生和家長的群組裡傳得沸沸揚揚，第二天一早，總務處就接到好幾通家長的電話，問孩子還能不能喝飲水機的水。本刊記者花了三天追查，發現這條「蛇」，其實是一條澆花用的水管。',
      { h: '一張模糊的照片' },
      '事情是這樣開始的。星期二傍晚，六年級的一位同學在後山步道拍夕陽，照片角落剛好拍到水塔。他回家把照片放大，看到水塔旁邊有一條彎彎曲曲的黑影，越看越像一條大蛇，就把照片傳到班級群組，問大家：「這是不是蛇？」',
      '他後來接受訪問時說：「天色很暗，照片又放得很大，我一看就嚇到了。現在想起來，真的有點杯弓蛇影。」',
      { h: '三個小時，傳了十幾個群組' },
      '照片一開始只是一個問句，可是轉傳的人越來越多，問號就不見了。記者整理了這則消息被轉傳的經過：',
      { timeline: { cap: '「水塔有蛇」消息的傳播經過（記者整理）', items: [['星期二 18:30', '六年級同學在班級群組問：「這是不是蛇？」'], ['星期二 19:10', '有人轉傳到社團群組，改成「水塔旁邊有蛇」'], ['星期二 20:00', '消息傳進家長群組，變成「水塔裡有蛇，水不能喝」'], ['星期二 21:30', '已經傳進十幾個群組，有人留言「我也聽說了」'], ['星期三 08:00', '學校總務處接到好幾通家長來電']] } },
      '記者訪問了五位轉傳的同學，沒有一個人親眼看過那條蛇。有人說：「大家都在傳，應該是真的吧。」這正像成語「三人成虎」說的：一句沒有根據的話，說的人多了，就讓人信以為真。',
      { h: '真相：一條綠色水管' },
      '星期三早上，總務主任和工友伯伯一起到後山檢查。他們發現，水塔的蓋子鎖得好好的，旁邊的草地上，躺著一條園藝社用來澆花的綠色長水管。傍晚的陽光從側面照過來，水管的影子就像一條盤起來的蛇。總務處也請人檢驗了水質，結果一切正常。',
      { h: '壞事變成一堂好課' },
      '這次的事件讓很多人虛驚一場，卻也有意外的收穫。資訊課的陳老師把它變成一堂「網路消息查證課」，教大家看到消息時先問三個問題：「誰說的？有沒有證據？可以去哪裡查？」陳老師說：「這次的謠言雖然讓大家緊張，但我們也因此學會分辨真假消息，有點像塞翁失馬。」',
      '最先拍照的那位同學，也在課堂上分享了自己的經驗。他說：「以後看到看不清楚的東西，我會先問大人，或請大人幫忙確認，不會直接傳出去。」'
    ],
    qs: [
      { id: 'q1', p: 1, d: 1, type: 'mc', q: '照片裡那條像蛇的黑影，其實是什麼？', opts: ['園藝社澆花用的綠色水管', '水塔上斷掉的一條電線', '後山步道的一根長樹枝', '一條從山上爬下來的蛇'], a: 0, why: '「真相」那一段：草地上「躺著一條園藝社用來澆花的綠色長水管」。' },
      { id: 'q2', p: 1, d: 1, type: 'mc', q: '從時間軸看，消息最早是在什麼時間、什麼地方出現的？', opts: ['星期二 18:30，班級群組', '星期二 19:10，社團群組', '星期二 20:00，家長群組', '星期三 08:00，總務處'], a: 0, why: '時間軸第一列：星期二 18:30，六年級同學在班級群組發問。' },
      { id: 'q3', p: 2, d: 2, type: 'mc', q: '記者說「轉傳的人越來越多，問號就不見了」，意思是什麼？', opts: ['原本是疑問，傳著傳著就被說成事實', '大家打字太快，都忘了打問號', '群組不能傳送有問號的訊息', '轉傳的人其實都知道那不是真的蛇'], a: 0, why: '對照時間軸：從「這是不是蛇？」變成「水塔旁邊有蛇」，再變成「水塔裡有蛇，水不能喝」，疑問變成了肯定的說法。' },
      { id: 'q4', p: 2, d: 2, type: 'mc', q: '最先拍照的同學說自己「有點杯弓蛇影」，是因為他怎麼了？', opts: ['把水管的影子看成蛇，自己嚇自己', '在後山看到真的蛇，嚇得跑回家', '故意做了一張假照片傳給大家', '把消息轉傳到十幾個群組裡'], a: 0, why: '杯弓蛇影是把影子看成蛇、白白驚慌。他把放大後的水管影子當成蛇，正是這樣。' },
      { id: 'q5', p: 3, d: 2, type: 'match', q: '把報導裡的事情和最適合的成語配起來。', pairs: [['把水管的影子看成蛇', '杯弓蛇影'], ['沒人看過蛇，傳的人多了就被當真', '三人成虎'], ['謠言讓人緊張，卻換來一堂查證課', '塞翁失馬']], why: '看錯東西而驚慌是杯弓蛇影；謠言重複多了被當真是三人成虎；壞事後來帶來好處是塞翁失馬。' },
      { id: 'q6', p: 4, d: 3, type: 'open', q: '陳老師教大家看到消息時先問三個問題：「誰說的？有沒有證據？可以去哪裡查？」如果你在群組裡看到「明天停課」的消息，請用這三個問題，說說你會怎麼查證、要不要轉傳。',
        ref: '我會先看是誰說的，如果只是同學說「聽說」，就不一定可靠。再看有沒有證據，例如有沒有附上學校或市政府的公告。最後我會去學校網站或市政府的停課公告查。查到正式公告才轉傳；查不到就不傳，還會提醒大家先查證。',
        rubric: ['用到「誰說的」來判斷消息來源', '用到「有沒有證據」或「去哪裡查」說出查證方法', '說清楚要不要轉傳和理由'] }
    ]
  },
  {
    id: 'cyr06', lv: 3, genre: '圖表資料', domain: ['健康', '數學'], title: '籃球校隊的一年',
    uses: ['cy051', 'cy052', 'cy059', 'cy060'],
    facts: ['校隊、人物、比賽紀錄都是虛構的｜虛構情境'],
    body: [
      '去年八月，學校的籃球校隊重新成立，十二位隊員大多是第一次參加校隊。教練請隊長小凱把這一年的比賽和練習記錄下來，做成下面這張表。',
      { table: { cap: '表一　籃球校隊一年紀錄（每週練習時數是當月平均）', head: ['月份', '參加的比賽', '結果', '每週練習時數'], rows: [['9月', '友誼賽（對東山國小）', '輸 18：32', '3小時'], ['10月', '區運會預賽', '輸 12：40', '3小時'], ['11月', '友誼賽（對東山國小）', '輸 16：35', '4小時'], ['12月', '沒有比賽', '—', '6小時'], ['1月', '友誼賽（對北門國小）', '贏 30：26', '6小時'], ['3月', '區運會複賽', '贏 34：28', '6小時'], ['4月', '區運會決賽', '贏 36：33', '7小時']] } },
      { h: '隊長的話' },
      '十月的區運會預賽，我們遇到去年的冠軍隊。他們傳球又快又準，我們連球都碰不太到，最後輸了二十八分。下場時，大家看著記分板，只能望洋興嘆：原來別人已經那麼強了。',
      '回來以後，我們看了很多職業球隊的影片，決定學他們的「遠距離三分球戰術」。可是我們的手還不夠有力，三分球幾乎都投不進，連原本練熟的上籃也亂了。十一月的友誼賽，我們又輸了，還輸得比九月更多。教練說：「你們這是邯鄲學步，新的沒學會，舊的也忘了。」',
      '十二月沒有比賽，我們決定從頭來過。每週練習從四小時增加到六小時，多出來的兩小時，就是每週兩天早上七點到球場練運球和上籃。冬天的早上又冷又暗，大家心裡都記著十月輸了二十八分的那場球，還是咬著牙撐下去。那段日子，我們真的是臥薪嘗膽。',
      '一月的友誼賽，我們第一次贏球。到了四月的區運會決賽，我們再次遇到十月打敗我們的冠軍隊。這一次，我們捲土重來，用最熟練的快攻和上籃，以三分之差贏得了冠軍！',
      { h: '教練的提醒' },
      '教練看著表一說：「練習時間增加，成績也跟著進步，這不是巧合。不過，練習也要適量，每週七小時已經是上限，大家還要留時間寫功課、好好睡覺。運動是為了讓身體更健康，可不要練到受傷了。」'
    ],
    qs: [
      { id: 'q1', p: 1, d: 1, type: 'mc', q: '依照表一，校隊第一次贏球是在幾月？', opts: ['1月', '11月', '3月', '4月'], a: 0, why: '表一中第一個「贏」出現在1月的友誼賽（30：26），隊長的話也說「一月的友誼賽，我們第一次贏球」。' },
      { id: 'q2', p: 1, d: 1, type: 'mc', q: '依照表一，哪一個月的每週練習時數最多？', opts: ['4月', '12月', '1月', '9月'], a: 0, why: '4月是7小時，其他月份最多是6小時。' },
      { id: 'q3', p: 2, d: 2, type: 'mc', q: '十一月的友誼賽，教練說隊員「邯鄲學步」，是因為發生了什麼事？', opts: ['學三分球沒學會，上籃也亂了', '練習時間太少，大家不認真', '對手太強，只能在旁邊感嘆', '隊員都想當隊長而吵架'], a: 0, why: '隊長說三分球「幾乎都投不進，連原本練熟的上籃也亂了」，新的沒學會、舊的也丟了，就是邯鄲學步。' },
      { id: 'q4', p: 3, d: 2, type: 'mc', q: '比較九月和十一月對東山國小的兩場友誼賽，下面哪一個說法正確？', opts: ['十一月輸的分數比九月多', '十一月贏了，九月輸了', '兩場輸的分數一樣多', '九月的練習時數比較多'], a: 0, why: '9月18：32輸14分，11月16：35輸19分，十一月輸得比較多；練習時數9月3小時、11月4小時。' },
      { id: 'q5', p: 3, d: 3, type: 'match', q: '把隊長說的經過，和他用的成語配起來。', pairs: [['看到冠軍隊太強，覺得自己差太多', '望洋興嘆'], ['亂學別人的戰術，連原本會的都忘了', '邯鄲學步'], ['冬天每天早起刻苦練習', '臥薪嘗膽'], ['輸過之後再挑戰同一隊並贏得冠軍', '捲土重來']], why: '看到對手的強大而感嘆自己不如人是望洋興嘆；模仿不成反失原本的是邯鄲學步；刻苦自勵是臥薪嘗膽；失敗後重新再來並成功是捲土重來。' },
      { id: 'q6', p: 4, d: 3, type: 'open', q: '教練說「練習時間增加，成績也跟著進步」，又說「練習也要適量」。請用表一的數字支持教練的第一句話，再說說你同不同意第二句話，為什麼？',
        ref: '9月到11月每週只練3到4小時，三場都輸；12月以後增加到6到7小時，1月、3月、4月三場都贏，可見練習時間多，成績也進步了。我同意要適量，因為我們還要寫功課、睡覺，練太多會太累，還可能受傷，反而不能比賽。',
        rubric: ['正確引用表一的數字（練習時數和比賽結果）', '說明數字怎麼支持「練習多、成績進步」', '表明是否同意「練習要適量」並說出理由'] }
    ]
  },
  {
    id: 'cyr09', lv: 4, genre: '多文本', domain: ['語文', '社會'], title: '學東西時，環境重不重要？',
    uses: ['cy083', 'cy084', 'cy087', 'cy089'],
    facts: ['文中的班級、人物、調查數字都是虛構的｜虛構情境', '「一傅眾咻」語本《孟子．滕文公下》，孟子用楚國人學齊國話說明環境對學習的影響｜教育部《成語典》'],
    body: [
      '五年三班這個月語文課的討論主題是「學東西的時候，環境重不重要」。老師請兩位同學各寫一篇看法，再請全班做一份小調查。下面是他們的資料。',
      { doc: '文本一：環境最重要', from: '五年三班　王小芸' },
      '我以前都在客廳寫功課。弟弟在旁邊看卡通，阿姨在講電話，電視的聲音、笑聲一直傳過來。我常常寫一題就分心一次，上學期的數學小考從九十分、八十分，一路掉到六十幾分，成績每況愈下。',
      '後來我讀到孟子說的故事：一個齊國人教楚國孩子說齊國話，旁邊卻有一大群楚國人吵鬧，孩子怎麼學都學不會。這就是「一傅眾咻」。我發現自己就是那個孩子！這學期我改到社區圖書館寫功課，安安靜靜的，一個月後，小考又回到八十五分。所以我認為：環境對學習最重要。',
      { doc: '文本二：態度比環境更重要', from: '五年三班　陳大偉' },
      '我家在夜市擺攤賣滷味，我常常在攤位後面的小桌子寫功課，旁邊有客人、有叫賣聲，一點都不安靜。可是我每天都先把當天學的東西弄懂，再寫作業，不懂的地方就記下來，第二天問老師。',
      '因為基本觀念學得很紮實，遇到新的題目，我常常能左右逢源，從學過的方法裡找到解法。我覺得環境吵不吵不是最重要的。一個人換到很安靜的地方，如果不用心、只想趕快寫完，跟每天認真弄懂的人比起來，還是會望塵莫及。',
      { doc: '文本三：五年三班「寫功課的地方」調查（30人）' },
      { table: { cap: '表一　平常寫功課的地點，和覺得自己專心的人數', head: ['寫功課的地點', '人數', '覺得自己專心的人數'], rows: [['自己的房間', 12, 10], ['客廳', 9, 3], ['安親班', 6, 4], ['家裡的店', 3, 2]] } },
      { table: { cap: '表二　你覺得「環境」和「自己的態度」哪一個比較重要？', head: ['選項', '人數'], rows: [['環境比較重要', 14], ['自己的態度比較重要', 11], ['兩個一樣重要', 5]] } },
      '老師的小提醒：表一的「專心」是同學自己覺得的，不是考試成績；調查的人數也不多，所以只能當作參考。'
    ],
    qs: [
      { id: 'q1', p: 1, d: 1, type: 'mc', q: '依照表一，在哪裡寫功課的同學最多？', opts: ['自己的房間', '客廳', '安親班', '家裡的店'], a: 0, why: '表一：自己的房間12人，是最多的。' },
      { id: 'q2', p: 2, d: 2, type: 'mc', q: '小芸說自己「就是那個孩子」，意思是什麼？', opts: ['她也在吵鬧的環境裡學不好', '她也想要跟齊國人學說齊國話', '她的弟弟正在學楚國話', '她跟那個孩子一樣大'], a: 0, why: '孟子故事裡的孩子在一群人吵鬧中學不會；小芸在吵鬧的客廳寫功課，成績每況愈下，處境一樣。' },
      { id: 'q3', p: 3, d: 2, type: 'mc', q: '小芸和大偉的看法，最大的不同是什麼？', opts: ['小芸認為環境最重要，大偉認為態度更重要', '小芸喜歡圖書館，大偉喜歡逛夜市', '小芸的成績一直比較好，大偉的成績比較差', '小芸住在城市，大偉住在鄉下'], a: 0, why: '兩篇的標題和最後一句就是他們的主張：文本一「環境最重要」，文本二「態度比環境更重要」。' },
      { id: 'q4', p: 3, d: 3, type: 'mc', q: '從表一來看，哪一個說法最有根據？', opts: ['在客廳寫功課的人，覺得專心的比例最低', '在家裡的店寫功課的人最不專心', '在安親班寫功課的人，全部都覺得很專心', '覺得專心的人，大部分在客廳寫功課'], a: 0, why: '客廳9人只有3人覺得專心（三分之一），比房間（12人中10人）、安親班（6人中4人）、家裡的店（3人中2人）的比例都低。' },
      { id: 'q5', p: 4, d: 3, type: 'mc', q: '大偉在夜市攤位旁寫功課，表一中「家裡的店」3人裡有2人覺得專心。這筆資料可以怎麼看？', opts: ['能支持大偉，但人數太少只能參考', '可以證明環境對學習一點都不重要', '可以證明小芸的說法錯了', '跟兩篇文章都沒有關係'], a: 0, why: '3人中有2人覺得專心，跟大偉的經驗相符；可是只有3個人，老師也提醒「只能當作參考」，不能拿來證明誰對誰錯。' },
      { id: 'q6', p: 4, d: 3, type: 'open', q: '讀完三份資料，你覺得學東西時，環境和自己的態度哪一個比較重要？請至少用兩份文本裡的內容當證據，並說說你會怎麼安排自己寫功課的地方。',
        ref: '我覺得兩個都重要，但態度更根本。文本一的小芸換到安靜的地方，成績就進步了，可見環境有影響；文本二的大偉在吵鬧的夜市也能學好，是因為他每天先把觀念弄懂。表一裡客廳覺得專心的人最少，所以我會在自己的房間寫功課，把手機放外面，寫之前先複習今天學的內容。',
        rubric: ['清楚表明自己的看法', '至少引用兩份文本的內容當證據', '說出安排寫功課地點的具體做法'] }
    ]
  }
]);
